CREATE OR REPLACE FUNCTION "public"."_environment_shared_in"("p_env" "uuid", "p_workspace" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.environment e
    where e.id = p_env
      and e.kind = 'cloud'
      and e.shared
      and e.archived_at is null
      and e.workspace_id = p_workspace
  );
$$;


ALTER FUNCTION "public"."_environment_shared_in"("p_env" "uuid", "p_workspace" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_environment_usable"("p_env" "uuid", "p_user" "uuid", "p_workspace" "uuid", "p_mac_only" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.environment e
    where e.id = p_env
      and e.archived_at is null
      and (
        (e.kind = 'mac' and e.owner_user_id = p_user)
        or (
          not p_mac_only
          and e.kind = 'cloud'
          and e.workspace_id = p_workspace
          and (e.shared or e.created_by = p_user)
          and exists (select 1 from public.member m where m.workspace_id = p_workspace and m.user_id = p_user)
        )
      )
  );
$$;


ALTER FUNCTION "public"."_environment_usable"("p_env" "uuid", "p_user" "uuid", "p_workspace" "uuid", "p_mac_only" boolean) OWNER TO "postgres";


