CREATE OR REPLACE FUNCTION "public"."age_out_stale_proposals"("p_cutoff" timestamp with time zone, "p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "workspace_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with candidates as (
    select pc.id
    from proposed_change pc
    where pc.status = 'pending'
      and pc.applied_at is null
      and pc.result_entity_id is null
      and (pc.extra ->> 'applied_at') is null
      and pc.created_at < p_cutoff
      and (p_workspace_id is null or pc.workspace_id = p_workspace_id)
      and not exists (
        select 1 from captures cap
        where cap.id = pc.capture_id
          and coalesce((cap.metadata ->> 'demo')::boolean, false) = true
      )
    order by pc.created_at asc
    limit case when p_limit is not null and p_limit > 0 then p_limit else null end
  )
  update proposed_change pc set
    status = 'dismissed',
    extra = coalesce(pc.extra, '{}'::jsonb) || jsonb_build_object(
      'aged_out', true,
      'aged_out_reason', 'stale — the meeting''s moment passed',
      'aged_out_cutoff', p_cutoff
    )
  from candidates c
  where pc.id = c.id
    and pc.status = 'pending'
    and pc.applied_at is null
    and pc.result_entity_id is null
    and (pc.extra ->> 'applied_at') is null
  returning pc.id, pc.workspace_id;
$$;


ALTER FUNCTION "public"."age_out_stale_proposals"("p_cutoff" timestamp with time zone, "p_workspace_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_link_user_for_email"("p_email" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select u.id
  from auth.users u
  where lower(u.email) = lower(btrim(coalesce(p_email, '')))
    and u.email_confirmed_at is not null
    and u.deleted_at is null
  order by u.created_at
  limit 1
$$;


ALTER FUNCTION "public"."agent_link_user_for_email"("p_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."agent_link_user_for_email"("p_email" "text") IS 'The confirmed Dial8 user signing in with this email, else null (432). Service role only: an agent link request by email never reveals whether anyone matched.';


CREATE OR REPLACE FUNCTION "public"."agent_run_claim_ci_fix"("p_run_id" "uuid", "p_workspace_id" "uuid", "p_head_sha" "text", "p_fix_run_id" "uuid", "p_max" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_trail jsonb;
  v_fixes integer;
begin
  select coalesce(ci_fix_trail, '[]'::jsonb) into v_trail
    from public.agent_run
   where id = p_run_id
     and workspace_id = p_workspace_id
     for update;
  if not found then
    return 'missing';
  end if;

  if exists (select 1 from jsonb_array_elements(v_trail) e where e ->> 'head_sha' = p_head_sha) then
    return 'duplicate';
  end if;

  if exists (
    select 1 from jsonb_array_elements(v_trail) e
     where e ->> 'kind' = 'fix'
       and not exists (
         select 1 from public.agent_run f
          where f.id::text = e ->> 'fix_run_id'
            and f.status in ('pr_open', 'completed', 'failed', 'canceled')
       )
  ) then
    return 'busy';
  end if;

  select count(*) into v_fixes from jsonb_array_elements(v_trail) e where e ->> 'kind' = 'fix';

  if v_fixes >= p_max then
    if exists (select 1 from jsonb_array_elements(v_trail) e where e ->> 'kind' = 'gave_up') then
      return 'reported';
    end if;
    update public.agent_run
       set ci_fix_trail = v_trail || jsonb_build_array(jsonb_build_object('kind', 'gave_up', 'head_sha', p_head_sha, 'at', now()))
     where id = p_run_id;
    return 'exhausted';
  end if;

  update public.agent_run
     set ci_fix_trail = v_trail || jsonb_build_array(jsonb_build_object('kind', 'fix', 'head_sha', p_head_sha, 'fix_run_id', p_fix_run_id, 'at', now()))
   where id = p_run_id;
  return 'start';
end;
$$;


ALTER FUNCTION "public"."agent_run_claim_ci_fix"("p_run_id" "uuid", "p_workspace_id" "uuid", "p_head_sha" "text", "p_fix_run_id" "uuid", "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_run_claim_proactive_coding"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_flow_id" "uuid", "p_fire_key" "text", "p_max" integer, "p_since" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_count integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('proactive_coding:' || p_workspace_id::text, 0));

  select id into v_id from public.agent_run where fire_key = p_fire_key and workspace_id = p_workspace_id;
  if found then
    return v_id;
  end if;

  select count(*) into v_count
    from public.agent_run
   where workspace_id = p_workspace_id
     and kind = 'coding'
     and origin = 'attempt'
     and ci_fix_of_run_id is null
     and created_at >= p_since;
  if v_count >= p_max then
    return null;
  end if;

  insert into public.agent_run (workspace_id, kind, status, origin, origin_depth, flow_id, fire_key, triggered_by)
  values (p_workspace_id, 'coding', 'queued', 'attempt', 1, p_flow_id, p_fire_key, p_user_id)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."agent_run_claim_proactive_coding"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_flow_id" "uuid", "p_fire_key" "text", "p_max" integer, "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_run_note_outside_read"("p_run_id" "uuid", "p_workspace_id" "uuid", "p_tool" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.agent_run
     set outside_reads = outside_reads || p_tool
   where id = p_run_id
     and workspace_id = p_workspace_id
     and p_tool is not null
     and char_length(p_tool) between 1 and 200
     and not (p_tool = any (outside_reads))
     and cardinality(outside_reads) < 20;
$$;


