CREATE OR REPLACE FUNCTION "public"."ai_team_member_default_bot_character"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.bot_character is not null then
    return new;
  end if;

  if new.is_system then
    if new.system_key = 'mail' and exists (
      select 1 from public.ai_team_member c
      where c.workspace_id = new.workspace_id and c.role = 'correspondent'
    ) then
      return new;
    end if;
    new.bot_character := public.default_bot_character(new.system_key, null);
  else
    new.bot_character := coalesce(
      public.default_bot_character(null, new.role),
      public.free_bot_character(new.workspace_id)
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."ai_team_member_default_bot_character"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_team_member_guard_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- (a) Everyone, the server included: a teammate's team is one of its
  -- workspace's teams.
  if not exists (
    select 1 from public.team t
    where t.id = new.team_id and t.workspace_id = new.workspace_id
  ) then
    raise exception 'a teammate''s team must be one of its workspace''s teams (ai_team_member %)', new.id
      using errcode = 'check_violation';
  end if;

  -- (b) The server (service role) and the database itself (no request) check
  -- who may first. A request with no sign-in ('anon') is not trusted.
  if coalesce(auth.role(), '') in ('', 'service_role') then
    return new;
  end if;

  -- (c) Anyone signed in: a teammate stays in its workspace...
  if tg_op = 'UPDATE' and new.workspace_id is distinct from old.workspace_id then
    raise exception 'a teammate stays in its workspace (ai_team_member %)', old.id
      using errcode = 'insufficient_privilege';
  end if;
  -- ...and a system teammate is only ever one seeding would make: one of the
  -- built-in ones, on its own anchor recipe (seed_system_teammates, migration
  -- 318). A workspace made by a signed-in user seeds them as that user.
  if tg_op = 'INSERT' and new.is_system and not (
    new.system_key in ('captures', 'mail', 'prospecting', 'evals', 'crm', 'assistant')
    and exists (
      select 1 from public.recipe r
      where r.id = new.agent_recipe_id
        and r.slug = 'loop-' || replace(new.system_key, '_', '-')
        and r.workspace_id is null
        and r.category = 'agent'
    )
  ) then
    raise exception 'a system teammate is one of the built-in ones, on its own anchor recipe (ai_team_member %)', new.id
      using errcode = 'insufficient_privilege';
  end if;

  -- (d) A workspace owner or admin.
  if public.get_member_role(new.workspace_id) in ('owner', 'admin') then
    return new;
  end if;

  -- (e) Anyone else adds a teammate with the defaults: it can only look.
  if tg_op = 'INSERT' then
    if new.allowed_side_effects is distinct from '{read}'::text[]
       or new.autonomy is distinct from 'propose'
       or new.role is not null
       or new.tool_allowlist is not null
       or new.can_delegate_to is distinct from '{}'::text[]
       or new.fronts_only then
      raise exception 'only a workspace owner or admin sets what a teammate may do on its own (ai_team_member)'
        using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;

  if new.allowed_side_effects is distinct from old.allowed_side_effects
     or new.autonomy is distinct from old.autonomy
     or new.role is distinct from old.role
     or new.tool_allowlist is distinct from old.tool_allowlist
     or new.can_delegate_to is distinct from old.can_delegate_to
     or new.fronts_only is distinct from old.fronts_only
     -- A work bot's persona: the agent it speaks for, or the loop anchor.
     or (old.fronts_only and new.agent_recipe_id is distinct from old.agent_recipe_id) then
    raise exception 'only a workspace owner or admin changes what a teammate may do on its own, or what a work bot speaks for (ai_team_member %)', old.id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."ai_team_member_guard_limits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_team_member_protect_system"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.is_system
       and not public._wsmerge_active()
       and exists (select 1 from public.workspace w where w.id = old.workspace_id)
       and exists (select 1 from public.team t where t.id = old.team_id) then
      raise exception 'system teammates cannot be deleted (ai_team_member %)', old.id
        using errcode = 'restrict_violation';
    end if;
    return old;
  end if;

  if new.is_system is distinct from old.is_system
     or new.system_key is distinct from old.system_key
     or (old.is_system and new.agent_recipe_id is distinct from old.agent_recipe_id) then
    raise exception 'is_system, system_key and a system teammate''s agent are fixed at insert (ai_team_member %)', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."ai_team_member_protect_system"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."append_capture_transcript"("p_capture_id" "uuid", "p_workspace_id" "uuid", "p_append" "text", "p_base_length" integer) RETURNS TABLE("status" "text", "server_length" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_stored text;
  v_ended timestamptz;
  v_locked boolean;
  v_len integer;
  v_updated_id uuid;
begin
  select transcript, ended_at, is_transcript_locked
    into v_stored, v_ended, v_locked
  from captures
  where id = p_capture_id and workspace_id = p_workspace_id;

  if not found then
    return query select 'not_found'::text, null::integer;
    return;
  end if;

  if v_ended is not null or v_locked then
    return query select 'locked'::text, coalesce(char_length(v_stored), 0);
    return;
  end if;

  v_len := coalesce(char_length(v_stored), 0);

  if v_len <> p_base_length then
    return query select 'base_mismatch'::text, v_len;
    return;
  end if;

  update captures
  set transcript = coalesce(v_stored, '') || p_append
  where id = p_capture_id
    and workspace_id = p_workspace_id
    and transcript is not distinct from v_stored
  returning id into v_updated_id;

  if v_updated_id is null then
    select coalesce(char_length(transcript), 0) into v_len
    from captures
    where id = p_capture_id and workspace_id = p_workspace_id;
    return query select 'conflict'::text, v_len;
    return;
  end if;

  return query select 'applied'::text, v_len + char_length(p_append);
end;
$$;


ALTER FUNCTION "public"."append_capture_transcript"("p_capture_id" "uuid", "p_workspace_id" "uuid", "p_append" "text", "p_base_length" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."append_user_voice_profile"("p_rows" "jsonb", "p_max_session_rows" integer DEFAULT 40, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := public._resolve_requester(p_user_id);
  inserted integer;
BEGIN
  INSERT INTO public.user_voice_profile (user_id, embedding, quality, session_id, source)
  SELECT v_uid, (r->>'embedding')::vector(512), (r->>'quality')::real,
         (r->>'session_id')::uuid, 'session_confirm'
  FROM jsonb_array_elements(p_rows) AS r;
  GET DIAGNOSTICS inserted = ROW_COUNT;

  -- Keep the newest meeting-learned rows; the Settings passages stay.
  DELETE FROM public.user_voice_profile
   WHERE id IN (
     SELECT id FROM public.user_voice_profile
      WHERE user_id = v_uid AND source = 'session_confirm'
      ORDER BY created_at DESC, id
     OFFSET GREATEST(p_max_session_rows, 0)
   );

  RETURN inserted;
END
$$;


ALTER FUNCTION "public"."append_user_voice_profile"("p_rows" "jsonb", "p_max_session_rows" integer, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."area_memory_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(auth.role(), '') in ('', 'service_role') then
    new.updated_at := now();
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() or new.source = 'learned' then
      raise exception 'A line you add is yours (created_by), told or edited, never learned'
        using errcode = 'insufficient_privilege';
    end if;
    new.updated_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  if new.id is distinct from old.id
     or new.workspace_id is distinct from old.workspace_id
     or new.area is distinct from old.area
     or new.scope is distinct from old.scope
     or new.user_id is distinct from old.user_id
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at then
    raise exception 'A memory line cannot move or change who made it: delete it and add a new one'
      using errcode = 'insufficient_privilege';
  end if;

  if old.status = 'active' and new.status = 'proposed' then
    raise exception 'An active memory line cannot go back to proposed'
      using errcode = 'check_violation';
  end if;
  if new.source is distinct from old.source and new.source <> 'edited' then
    raise exception 'A changed memory line is edited, never told or learned'
      using errcode = 'insufficient_privilege';
  end if;

  new.updated_by := auth.uid();
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."area_memory_guard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."area_memory_guard"() IS 'BEFORE INSERT OR UPDATE on area_memory (317). Unless the caller is the service role or has no request context: a new line is the caller''s (created_by) and never learned; a line never moves workspace, area, scope or user, keeps created_by/created_at, never goes from active back to proposed, and a changed source can only become edited.';


CREATE OR REPLACE FUNCTION "public"."attachment_rag_search"("p_user_id" "text", "p_embedding" "text", "p_workspace_id" "text" DEFAULT NULL::"text", "p_project_ids" "text"[] DEFAULT '{}'::"text"[], "p_limit" integer DEFAULT 10, "p_threshold" double precision DEFAULT 0.3) RETURNS TABLE("chunk_id" "uuid", "attachment_id" "uuid", "project_id" "uuid", "chunk_text" "text", "chunk_type" "text", "page_number" integer, "file_name" "text", "file_category" "text", "mime_type" "text", "storage_path" "text", "parent_capture_id" "uuid", "parent_action_id" "uuid", "similarity" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID := p_user_id::UUID;
    v_embedding halfvec(3072) := p_embedding::halfvec(3072);
    v_workspace_id UUID := CASE WHEN p_workspace_id IS NOT NULL THEN p_workspace_id::UUID ELSE NULL END;
    v_has_project_filter BOOLEAN := COALESCE(array_length(p_project_ids, 1), 0) > 0;
    v_project_ids UUID[];
BEGIN
    IF auth.uid() IS NOT NULL AND auth.uid() <> v_user_id THEN
        RETURN;
    END IF;

    IF v_has_project_filter THEN
        v_project_ids := ARRAY(SELECT unnest(p_project_ids)::UUID);
    END IF;

    RETURN QUERY
    SELECT
        ac.id as chunk_id,
        ac.attachment_id,
        ac.project_id,
        ac.chunk_text,
        ac.chunk_type,
        ac.page_number,
        a.file_name,
        a.file_category,
        a.mime_type,
        a.storage_path,
        a.note_id as parent_capture_id,
        a.action_id as parent_action_id,
        1 - (ac.embedding <=> v_embedding) as similarity
    FROM attachment_chunks ac
    JOIN attachments a ON a.id = ac.attachment_id
    WHERE ac.user_id = v_user_id
      AND ac.embedding IS NOT NULL
      AND 1 - (ac.embedding <=> v_embedding) >= p_threshold
      AND (v_workspace_id IS NULL OR ac.workspace_id = v_workspace_id)
      -- 223: same as rag_search — chunk ownership does not imply that the
      -- attachment's parent capture is still visible to this user.
      AND (
          a.note_id IS NULL
          OR EXISTS (
              SELECT 1 FROM public.captures c
              WHERE c.id = a.note_id
                AND (c.visibility = 'workspace' OR c.user_id = v_user_id)
          )
      )
      AND (
          NOT v_has_project_filter
          OR ac.project_id = ANY(v_project_ids)
      )
    ORDER BY ac.embedding <=> v_embedding
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."attachment_rag_search"("p_user_id" "text", "p_embedding" "text", "p_workspace_id" "text", "p_project_ids" "text"[], "p_limit" integer, "p_threshold" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attention_item_expire_with_proposal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.attention_item a
     SET status = 'expired',
         resolved_at = now()
   WHERE a.proposal_id = OLD.id
     AND a.status = 'pending';
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."attention_item_expire_with_proposal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attention_item_follow_proposal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_card_status text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NULL;
  END IF;

  IF OLD.status = 'pending' THEN
    v_card_status := CASE
      WHEN NEW.status = 'applied' THEN 'accepted'
      WHEN NEW.status = 'dismissed'
           AND (coalesce(NEW.extra ->> 'aged_out', '') = 'true'
                OR coalesce(NEW.extra ->> 'dismiss_reason', '') = 'aged_out_30d') THEN 'expired'
      WHEN NEW.status = 'dismissed' THEN 'dismissed'
      ELSE 'expired'
    END;

    UPDATE public.attention_item a
       SET status = v_card_status,
           resolved_at = now(),
           payload = coalesce(a.payload, '{}'::jsonb)
                     || jsonb_build_object('resolved_with_proposal', NEW.status)
     WHERE a.proposal_id = NEW.id
       AND a.status = 'pending'
       AND NOT (a.kind = 'draft_email' AND NEW.status = 'applied');

  ELSIF NEW.status = 'pending' THEN
    BEGIN
    UPDATE public.attention_item a
       SET status = 'pending',
           resolved_at = NULL,
           payload = a.payload - 'resolved_with_proposal'
     WHERE a.id = (
             SELECT c.id
               FROM public.attention_item c
              WHERE c.proposal_id = NEW.id
                AND c.status <> 'pending'
                AND c.payload ->> 'resolved_with_proposal' IS NOT NULL
              ORDER BY c.resolved_at DESC NULLS LAST
              LIMIT 1
           )
       AND (a.expires_at IS NULL OR a.expires_at > now())
       AND NOT EXISTS (
             SELECT 1
               FROM public.attention_item p
              WHERE p.proposal_id = NEW.id
                AND p.status = 'pending'
           );
    EXCEPTION WHEN unique_violation THEN
      -- Another transaction's card for this proposal landed first: it stands.
      NULL;
    END;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."attention_item_follow_proposal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."billing_overspenders"() RETURNS TABLE("user_id" "uuid", "plan_name" "text", "cost_used" numeric, "plan_limit" numeric, "wallet" numeric, "over_by" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE r record; eff ai_plan_definitions; v_wallet numeric;
BEGIN
  FOR r IN SELECT up.user_id, up.current_period_cost_usd FROM ai_user_plans up LOOP
    SELECT (rp.plan_def).* INTO eff FROM resolve_effective_plan(r.user_id) rp;
    IF eff.monthly_cost_limit_usd IS NULL THEN CONTINUE; END IF;
    SELECT COALESCE(balance_usd, 0) INTO v_wallet FROM ai_user_credits WHERE ai_user_credits.user_id = r.user_id;
    v_wallet := COALESCE(v_wallet, 0);
    IF r.current_period_cost_usd > eff.monthly_cost_limit_usd + GREATEST(v_wallet, 0) + 0.50 THEN
      user_id := r.user_id; plan_name := eff.name; cost_used := r.current_period_cost_usd;
      plan_limit := eff.monthly_cost_limit_usd; wallet := v_wallet;
      over_by := r.current_period_cost_usd - (eff.monthly_cost_limit_usd + GREATEST(v_wallet, 0));
      RETURN NEXT;
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION "public"."billing_overspenders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."billing_wallet_drift"() RETURNS TABLE("user_id" "uuid", "cached_balance" numeric, "ledger_balance" numeric, "diff" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT c.user_id, c.balance_usd AS cached_balance, COALESCE(l.total, 0) AS ledger_balance,
         c.balance_usd - COALESCE(l.total, 0) AS diff
  FROM ai_user_credits c
  LEFT JOIN (SELECT ai_credit_ledger.user_id, SUM(amount_usd) AS total FROM ai_credit_ledger GROUP BY ai_credit_ledger.user_id) l
    ON l.user_id = c.user_id
  WHERE ABS(c.balance_usd - COALESCE(l.total, 0)) > 0.01;
$$;


ALTER FUNCTION "public"."billing_wallet_drift"() OWNER TO "postgres";


