CREATE OR REPLACE FUNCTION "public"."can_edit_contact"("p_contact_id" "uuid", "p_workspace_id" "uuid", "p_visibility" "text", "p_created_by_member_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID;
  v_member_id UUID;
  v_role TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  IF NOT public.is_workspace_member(p_workspace_id) THEN
    RETURN FALSE;
  END IF;

  -- Resolve member
  SELECT m.id, m.role INTO v_member_id, v_role
  FROM public.member m
  WHERE m.user_id = v_user_id
    AND m.workspace_id = p_workspace_id
  LIMIT 1;

  -- Creator has full access
  IF v_member_id = p_created_by_member_id THEN
    RETURN TRUE;
  END IF;

  -- Admins have full access
  IF v_role IN ('owner', 'admin') THEN
    RETURN TRUE;
  END IF;

  -- Workspace-visible: any member can edit
  IF p_visibility = 'workspace' THEN
    RETURN TRUE;
  END IF;

  -- Explicit edit share to this member
  IF EXISTS (
    SELECT 1 FROM public.contact_share cs
    WHERE cs.contact_id = p_contact_id
      AND cs.shared_with_member_id = v_member_id
      AND cs.access_level = 'edit'
  ) THEN
    RETURN TRUE;
  END IF;

  -- Explicit edit share to a team this member is in
  IF EXISTS (
    SELECT 1 FROM public.contact_share cs
    JOIN public.team_member tm ON tm.team_id = cs.shared_with_team_id
    WHERE cs.contact_id = p_contact_id
      AND tm.member_id = v_member_id
      AND cs.access_level = 'edit'
  ) THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_edit_contact"("p_contact_id" "uuid", "p_workspace_id" "uuid", "p_visibility" "text", "p_created_by_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_edit_document"("p_id" "uuid", "p_workspace_id" "uuid", "p_created_by" "uuid", "p_type" "text", "p_slug" "text", "p_published_status" "text", "p_frontmatter" "jsonb", "p_project_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role   text;
  v_member uuid;
begin
  select m.role, m.id
    into v_role, v_member
    from public.member m
   where m.workspace_id = p_workspace_id
     and m.user_id = auth.uid()
   limit 1;

  -- Not a member, or a guest: never.
  if v_role is null or v_role not in ('owner', 'admin', 'member') then
    return false;
  end if;
  if v_role in ('owner', 'admin') then
    return true;
  end if;
  -- The product doc and machine-written spec pages: owner or admin only.
  if public.is_product_doc(p_workspace_id, p_id) then
    return false;
  end if;
  if coalesce(p_type, 'note') = 'spec' then
    return false;
  end if;
  -- The creator.
  if p_created_by is not null and p_created_by = v_member then
    return true;
  end if;
  -- A plain member: a shared wiki page only.
  return coalesce(p_published_status, '') = 'published'
     and not (coalesce(p_frontmatter, '{}'::jsonb) ? 'meeting_prep')
     and p_project_id is null
     and (p_slug is not null or coalesce(p_type, 'note') <> 'note');
end
$$;


ALTER FUNCTION "public"."can_edit_document"("p_id" "uuid", "p_workspace_id" "uuid", "p_created_by" "uuid", "p_type" "text", "p_slug" "text", "p_published_status" "text", "p_frontmatter" "jsonb", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_team_members"("t_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.team t
    JOIN public.member m ON m.workspace_id = t.workspace_id AND m.user_id = auth.uid()
    WHERE t.id = t_id
      AND (
        m.role IN ('owner', 'admin')
        OR EXISTS (
          SELECT 1 FROM public.team_member tm
          JOIN public.member m2 ON m2.id = tm.member_id
          WHERE tm.team_id = t_id
            AND tm.team_role = 'lead'
            AND m2.user_id = auth.uid()
        )
      )
  );
$$;


ALTER FUNCTION "public"."can_manage_team_members"("t_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_contact"("p_contact_id" "uuid", "p_workspace_id" "uuid", "p_visibility" "text", "p_created_by_member_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID;
  v_member_id UUID;
  v_role TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Must be a workspace member
  IF NOT public.is_workspace_member(p_workspace_id) THEN
    RETURN FALSE;
  END IF;

  -- Workspace-wide contacts: everyone sees them
  IF p_visibility = 'workspace' THEN
    RETURN TRUE;
  END IF;

  -- Resolve current user's member_id in this workspace
  SELECT m.id, m.role INTO v_member_id, v_role
  FROM public.member m
  WHERE m.user_id = v_user_id
    AND m.workspace_id = p_workspace_id
  LIMIT 1;

  -- Owner always sees their own contacts
  IF v_member_id = p_created_by_member_id THEN
    RETURN TRUE;
  END IF;

  -- Workspace owner/admin can see all contacts
  IF v_role IN ('owner', 'admin') THEN
    RETURN TRUE;
  END IF;

  -- Team visibility: user shares a team with the contact creator
  IF p_visibility = 'team' AND p_created_by_member_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.team_member tm1
      JOIN public.team_member tm2 ON tm2.team_id = tm1.team_id
      WHERE tm1.member_id = v_member_id
        AND tm2.member_id = p_created_by_member_id
    ) THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- Explicit share to this member
  IF EXISTS (
    SELECT 1 FROM public.contact_share cs
    WHERE cs.contact_id = p_contact_id
      AND cs.shared_with_member_id = v_member_id
  ) THEN
    RETURN TRUE;
  END IF;

  -- Explicit share to a team this member is in
  IF EXISTS (
    SELECT 1 FROM public.contact_share cs
    JOIN public.team_member tm ON tm.team_id = cs.shared_with_team_id
    WHERE cs.contact_id = p_contact_id
      AND tm.member_id = v_member_id
  ) THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_view_contact"("p_contact_id" "uuid", "p_workspace_id" "uuid", "p_visibility" "text", "p_created_by_member_id" "uuid") OWNER TO "postgres";


