    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET status = 'cancelled', updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id AND status IN ('confirmed', 'in_progress');
    RETURN FOUND;
END;
$$;


