CREATE OR REPLACE FUNCTION "public"."chat_memory_op_prune"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  delete from public.chat_memory_op where created_at < now() - interval '7 days';
  return null;
end;
$$;


ALTER FUNCTION "public"."chat_memory_op_prune"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chat_memory_op_prune"() IS 'AFTER INSERT (statement) on chat_memory_op (328): drops results older than 7 days.';


CREATE OR REPLACE FUNCTION "public"."chat_memory_recall_commit"("p_operation_id" "text", "p_session_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_conversation_id" "uuid", "p_phase" "text", "p_result" "jsonb", "p_epoch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_inserted integer;
  v_result jsonb;
begin
  insert into public.chat_memory_op (operation_id, session_id, user_id, op, phase, result)
  values (p_operation_id, p_session_id, p_user_id, 'recall', p_phase, p_result)
  on conflict (operation_id) do nothing;
  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    select result into v_result
      from public.chat_memory_op
     where operation_id = p_operation_id and session_id = p_session_id and user_id = p_user_id and op = 'recall';
    return jsonb_build_object('won', false, 'result', v_result);
  end if;

  if p_epoch is not null then
    insert into public.chat_memory_epoch as e (
      session_id, user_id, workspace_id, conversation_id, snapshot, snapshot_hash,
      epoch_at, epoch_seq, live_delta_seqs, facts_shown, updated_at
    )
    values (
      p_session_id, p_user_id, p_workspace_id, p_conversation_id,
      coalesce(p_epoch->'snapshot', '[]'::jsonb),
      coalesce(p_epoch->>'snapshot_hash', ''),
      coalesce((p_epoch->>'epoch_at')::timestamptz, now()),
      coalesce((p_epoch->>'epoch_seq')::integer, 0),
      coalesce(array(select jsonb_array_elements_text(p_epoch->'live_delta_seqs')::integer), '{}'),
      coalesce((p_epoch->>'facts_shown')::boolean, false),
      now()
    )
    on conflict (session_id) do update set
      snapshot = excluded.snapshot,
      snapshot_hash = excluded.snapshot_hash,
      epoch_at = excluded.epoch_at,
      epoch_seq = excluded.epoch_seq,
      live_delta_seqs = excluded.live_delta_seqs,
      facts_shown = excluded.facts_shown,
      updated_at = now()
    where e.user_id = p_user_id and e.workspace_id = p_workspace_id;
  end if;

  return jsonb_build_object('won', true, 'result', p_result);
end;
$$;


ALTER FUNCTION "public"."chat_memory_recall_commit"("p_operation_id" "text", "p_session_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_conversation_id" "uuid", "p_phase" "text", "p_result" "jsonb", "p_epoch" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chat_memory_recall_commit"("p_operation_id" "text", "p_session_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_conversation_id" "uuid", "p_phase" "text", "p_result" "jsonb", "p_epoch" "jsonb") IS 'Store a recall result by operationId and, only when it won, the session''s new epoch state, in one transaction (328). Server only.';


