CREATE TABLE IF NOT EXISTS "public"."lens_finding" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "member_id" "uuid" NOT NULL,
    "flow_id" "uuid",
    "capture_id" "uuid",
    "lens" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "body" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "item_hash" "text" NOT NULL,
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "used_at" timestamp with time zone,
    CONSTRAINT "lens_finding_body_check" CHECK (("jsonb_typeof"("body") = 'object'::"text")),
    CONSTRAINT "lens_finding_item_hash_check" CHECK ((("char_length"("item_hash") >= 1) AND ("char_length"("item_hash") <= 64))),
    CONSTRAINT "lens_finding_kind_check" CHECK (("kind" ~ '^[a-z][a-z0-9_]{0,39}$'::"text")),
    CONSTRAINT "lens_finding_lens_check" CHECK (("lens" ~ '^[a-z][a-z0-9_-]{0,39}$'::"text")),
    CONSTRAINT "lens_finding_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'claimed'::"text", 'used'::"text", 'dismissed'::"text"])))
);


ALTER TABLE "public"."lens_finding" OWNER TO "postgres";


COMMENT ON TABLE "public"."lens_finding" IS 'What a lens flow takes from a call (flows F3, src/lib/flows/lens-deliver.ts): content moments for the post pass, marketing findings for the product doc. Written by the server; read by its owner.';


CREATE OR REPLACE FUNCTION "public"."claim_lens_batch"("p_workspace_id" "uuid", "p_lens" "text", "p_limit" integer DEFAULT 30) RETURNS SETOF "public"."lens_finding"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_day_start timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
begin
  perform pg_advisory_xact_lock(hashtextextended('lens_batch:' || p_workspace_id::text || ':' || p_lens, 0));
  if exists (
    select 1 from public.lens_finding
    where workspace_id = p_workspace_id and lens = p_lens
      and status in ('claimed', 'used') and used_at >= v_day_start
  ) then
    return;
  end if;
  return query
  update public.lens_finding f
  set status = 'claimed', used_at = now()
  where f.id in (
    select id from public.lens_finding
    where workspace_id = p_workspace_id and lens = p_lens and kind <> 'testimonial'
      and created_at >= now() - interval '30 days'
      and (status = 'new' or (status = 'claimed' and used_at < now() - interval '1 hour'))
    order by created_at
    limit greatest(1, least(p_limit, 100))
    for update skip locked
  )
  returning f.*;
end
$$;


ALTER FUNCTION "public"."claim_lens_batch"("p_workspace_id" "uuid", "p_lens" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_neighborhood"("p_workspace_id" "text", "p_entity_type" "text", "p_entity_id" "text", "p_depth" integer DEFAULT 2, "p_limit" integer DEFAULT 60, "p_requesting_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_workspace_id UUID;
    v_center_id UUID;
    v_depth INTEGER := LEAST(GREATEST(COALESCE(p_depth, 2), 1), 3);
    v_edges JSONB;
    v_nodes JSONB;
    v_requester UUID := public._resolve_visibility_requester(p_requesting_user_id);
BEGIN
    BEGIN
        v_workspace_id := p_workspace_id::UUID;
        v_center_id := p_entity_id::UUID;
    EXCEPTION WHEN others THEN
        RETURN jsonb_build_object(
            'center', jsonb_build_object('type', p_entity_type, 'id', p_entity_id),
            'depth', v_depth,
            'nodes', '[]'::jsonb,
            'edges', '[]'::jsonb
        );
    END;

    -- Membership gate (275): enforced whenever the requester is KNOWN — whether
    -- it came from the JWT or from an explicit p_requesting_user_id — not only
    -- when a JWT happens to be present. A sessionless caller that asserts no
    -- requester at all sees workspace-visible rows only, and is trusted to
    -- scope itself (service-role already has the whole database).
    IF v_requester IS NOT NULL AND NOT public._is_member_of(v_requester, v_workspace_id) THEN
        RETURN jsonb_build_object(
            'center', jsonb_build_object('type', p_entity_type, 'id', v_center_id),
            'depth', v_depth,
            'nodes', '[]'::jsonb,
            'edges', '[]'::jsonb
        );
    END IF;

    -- Asking about a hidden centre returns an empty graph, same shape as the
    -- membership refusal above.
    -- 341: an email centre is hidden from everyone.
    -- 353: someone else's chat is hidden too.
    IF p_entity_type = 'email'
       OR (p_entity_type = 'conversation' AND NOT EXISTS (
             SELECT 1 FROM public.chat_conversations cc
             WHERE cc.id = v_center_id AND v_requester IS NOT NULL AND cc.user_id = v_requester))
       OR (p_entity_type = 'capture' AND NOT public.capture_visible_to(v_center_id, v_requester))
       OR (p_entity_type = 'claim' AND NOT public.claim_visible_to(v_center_id, v_requester))
       -- 369: a private document is its creator's alone.
       OR (p_entity_type = 'document' AND NOT public.document_visible_to(v_center_id, v_requester)) THEN
        RETURN jsonb_build_object(
            'center', jsonb_build_object('type', p_entity_type, 'id', v_center_id),
            'depth', v_depth,
            'nodes', '[]'::jsonb,
            'edges', '[]'::jsonb
        );
    END IF;

    WITH RECURSIVE frontier AS (
        SELECT
            p_entity_type AS node_type,
            v_center_id AS node_id,
            0 AS hop,
            ARRAY[p_entity_type || ':' || v_center_id::text] AS visited
        UNION ALL
        SELECT
            nxt.node_type,
            nxt.node_id,
            f.hop + 1,
            f.visited || (nxt.node_type || ':' || nxt.node_id::text)
        FROM frontier f
        JOIN LATERAL (
            SELECT
                CASE WHEN el.source_type = f.node_type AND el.source_id = f.node_id
                     THEN el.target_type ELSE el.source_type END AS node_type,
                CASE WHEN el.source_type = f.node_type AND el.source_id = f.node_id
                     THEN el.target_id ELSE el.source_id END AS node_id
            FROM public.entity_link el
            WHERE el.workspace_id = v_workspace_id
              AND (
                   (el.source_type = f.node_type AND el.source_id = f.node_id)
                OR (el.target_type = f.node_type AND el.target_id = f.node_id)
              )
        ) nxt ON true
        WHERE f.hop < v_depth
          AND NOT ((nxt.node_type || ':' || nxt.node_id::text) = ANY(f.visited))
          AND (nxt.node_type <> 'capture' OR public.capture_visible_to(nxt.node_id, v_requester))
          AND (nxt.node_type <> 'claim'   OR public.claim_visible_to(nxt.node_id, v_requester))
          AND (nxt.node_type <> 'document' OR public.document_visible_to(nxt.node_id, v_requester))
          -- 341: the walk never reaches an email.
          AND nxt.node_type <> 'email'
          -- 353: nor someone else's chat.
          AND (nxt.node_type <> 'conversation' OR EXISTS (
                SELECT 1 FROM public.chat_conversations cc
                WHERE cc.id = nxt.node_id AND v_requester IS NOT NULL AND cc.user_id = v_requester))
    ),
    reached AS (
        SELECT node_type, node_id, MIN(hop) AS hop
        FROM frontier
        GROUP BY node_type, node_id
    ),
    candidate AS (
        SELECT
            el.source_type, el.source_id, el.target_type, el.target_id,
            el.relation, el.created_at,
            LEAST(rs.hop, rt.hop) AS edge_hop
        FROM public.entity_link el
        JOIN reached rs ON rs.node_type = el.source_type AND rs.node_id = el.source_id
        JOIN reached rt ON rt.node_type = el.target_type AND rt.node_id = el.target_id
        WHERE el.workspace_id = v_workspace_id
    ),
    deg AS (
        SELECT node_type, node_id, COUNT(*)::float AS d
        FROM (
            SELECT source_type AS node_type, source_id AS node_id FROM candidate
            UNION ALL
            SELECT target_type, target_id FROM candidate
        ) u
        GROUP BY node_type, node_id
    ),
    claim_score AS (
        SELECT
            c.id,
            (CASE c.confirmation
                 WHEN 'confirmed' THEN 2.0
                 WHEN 'dismissed' THEN -2.0
                 ELSE 0.0 END)
          + (CASE WHEN c.status = 'active' THEN 1.0 ELSE -1.0 END)
          + COALESCE(c.confidence, 0.5)
          + 1.0 / (1.0 + GREATEST(EXTRACT(EPOCH FROM (now() - c.updated_at)), 0) / (86400.0 * 30.0))
            AS score
        FROM public.claim c
        WHERE c.workspace_id = v_workspace_id
          AND c.id IN (
              SELECT n.node_id FROM (
                  SELECT source_type AS node_type, source_id AS node_id FROM candidate
                  UNION
                  SELECT target_type, target_id FROM candidate
              ) n
              WHERE n.node_type = 'claim'
          )
    ),
    edges AS (
        SELECT cd.source_type, cd.source_id, cd.target_type, cd.target_id, cd.relation
        FROM candidate cd
        LEFT JOIN claim_score ss ON cd.source_type = 'claim' AND ss.id = cd.source_id
        LEFT JOIN claim_score ts ON cd.target_type = 'claim' AND ts.id = cd.target_id
        LEFT JOIN deg ds ON ds.node_type = cd.source_type AND ds.node_id = cd.source_id
        LEFT JOIN deg dt ON dt.node_type = cd.target_type AND dt.node_id = cd.target_id
        ORDER BY
            cd.edge_hop ASC,
            COALESCE(ss.score, 0.5) + COALESCE(ts.score, 0.5)
              + 0.05 * LEAST(COALESCE(ds.d, 0) + COALESCE(dt.d, 0), 20.0) DESC,
            cd.created_at DESC,
            cd.source_id, cd.target_id, cd.relation
        LIMIT p_limit
    )
    SELECT jsonb_agg(jsonb_build_object(
        'source_type', e.source_type,
        'source_id', e.source_id,
        'target_type', e.target_type,
        'target_id', e.target_id,
        'relation', e.relation
    )) INTO v_edges FROM edges e;

    WITH endpoints AS (
        SELECT DISTINCT node_type, node_id FROM (
            SELECT (e->>'source_type') AS node_type, (e->>'source_id')::uuid AS node_id
            FROM jsonb_array_elements(COALESCE(v_edges, '[]'::jsonb)) e
            UNION
            SELECT (e->>'target_type'), (e->>'target_id')::uuid
            FROM jsonb_array_elements(COALESCE(v_edges, '[]'::jsonb)) e
            UNION
            SELECT p_entity_type, v_center_id
        ) u
    )
    SELECT jsonb_agg(jsonb_build_object(
        'node_type', ep.node_type,
        'node_id', ep.node_id,
        'label', CASE ep.node_type
            WHEN 'claim'        THEN LEFT(cl.text, 140)
            WHEN 'capture'      THEN cap.title
            WHEN 'document'     THEN doc.title
            WHEN 'project'      THEN prj.name
            WHEN 'action'       THEN act.title
            WHEN 'contact'      THEN con.full_name
            WHEN 'member'       THEN mem.display_name
            WHEN 'initiative'   THEN ini.name
            WHEN 'attachment'   THEN att.file_name
            WHEN 'conversation' THEN conv.title
            WHEN 'company'      THEN comp.name
            WHEN 'campaign'     THEN camp.name
            ELSE NULL END,
        'claim_text',   CASE WHEN ep.node_type = 'claim' THEN cl.text ELSE NULL END,
        'claim_type',   CASE WHEN ep.node_type = 'claim' THEN cl.type ELSE NULL END,
        'confidence',   CASE WHEN ep.node_type = 'claim' THEN cl.confidence ELSE NULL END,
        'confirmation', CASE WHEN ep.node_type = 'claim' THEN cl.confirmation ELSE NULL END,
        'status',       CASE WHEN ep.node_type = 'claim' THEN cl.status ELSE NULL END
    )) INTO v_nodes
    FROM endpoints ep
    LEFT JOIN public.claim    cl  ON ep.node_type = 'claim'        AND cl.id  = ep.node_id AND cl.workspace_id = v_workspace_id AND public.claim_visible_to(cl.id, v_requester)
    LEFT JOIN public.captures cap ON ep.node_type = 'capture'      AND cap.id = ep.node_id AND cap.workspace_id = v_workspace_id AND (cap.visibility = 'workspace' OR (v_requester IS NOT NULL AND cap.user_id = v_requester))
    LEFT JOIN public.document doc ON ep.node_type = 'document'     AND doc.id = ep.node_id AND doc.workspace_id = v_workspace_id AND public.document_visible_to(doc.id, v_requester)
    LEFT JOIN public.projects prj ON ep.node_type = 'project'      AND prj.id = ep.node_id AND prj.workspace_id = v_workspace_id
    LEFT JOIN public.actions  act ON ep.node_type = 'action'       AND act.id = ep.node_id AND act.workspace_id = v_workspace_id
    LEFT JOIN public.contact  con ON ep.node_type = 'contact'      AND con.id = ep.node_id AND con.workspace_id = v_workspace_id
    LEFT JOIN public.member   mem ON ep.node_type = 'member'       AND mem.id = ep.node_id AND mem.workspace_id = v_workspace_id
    LEFT JOIN public.initiative ini ON ep.node_type = 'initiative' AND ini.id = ep.node_id AND ini.workspace_id = v_workspace_id
    LEFT JOIN public.attachments att ON ep.node_type = 'attachment' AND att.id = ep.node_id AND att.workspace_id = v_workspace_id
    LEFT JOIN public.chat_conversations conv ON ep.node_type = 'conversation' AND conv.id = ep.node_id AND conv.workspace_id = v_workspace_id AND v_requester IS NOT NULL AND conv.user_id = v_requester
    LEFT JOIN public.company  comp ON ep.node_type = 'company'      AND comp.id = ep.node_id AND comp.workspace_id = v_workspace_id
    LEFT JOIN public.campaign camp ON ep.node_type = 'campaign'     AND camp.id = ep.node_id AND camp.workspace_id = v_workspace_id;

    RETURN jsonb_build_object(
        'center', jsonb_build_object('type', p_entity_type, 'id', v_center_id),
        'depth', v_depth,
        'nodes', COALESCE(v_nodes, '[]'::jsonb),
        'edges', COALESCE(v_edges, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION "public"."claim_neighborhood"("p_workspace_id" "text", "p_entity_type" "text", "p_entity_id" "text", "p_depth" integer, "p_limit" integer, "p_requesting_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_visible_to"("p_claim_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    -- 341: a claim learned from mail is visible to no one.
    NOT EXISTS (
      SELECT 1 FROM public.claim_source cs
      WHERE cs.claim_id = p_claim_id
        AND cs.source_type = 'email'
    )
    AND (
      NOT EXISTS (SELECT 1 FROM public.claim_source cs WHERE cs.claim_id = p_claim_id)
      OR EXISTS (
        SELECT 1 FROM public.claim_source cs
        WHERE cs.claim_id = p_claim_id
          AND CASE cs.source_type
            WHEN 'capture' THEN EXISTS (
              SELECT 1 FROM public.captures c
              WHERE c.id = cs.source_id
                AND NOT c.is_eval
                AND (c.visibility = 'workspace'
                     OR (p_user_id IS NOT NULL AND c.user_id = p_user_id))
            )
            WHEN 'attachment' THEN EXISTS (
              SELECT 1 FROM public.attachments a
              WHERE a.id = cs.source_id
                AND (
                  a.note_id IS NULL
                  OR EXISTS (
                    SELECT 1 FROM public.captures c
                    WHERE c.id = a.note_id
                      AND NOT c.is_eval
                      AND (c.visibility = 'workspace'
                           OR (p_user_id IS NOT NULL AND c.user_id = p_user_id))
                  )
                )
            )
            -- 353: a chat is only its owner's.
            WHEN 'conversation' THEN EXISTS (
              SELECT 1 FROM public.chat_conversations cc
              WHERE cc.id = cs.source_id
                AND p_user_id IS NOT NULL
                AND cc.user_id = p_user_id
            )
            WHEN 'email' THEN FALSE
            -- 369: a private document is its creator's alone.
            WHEN 'document' THEN public.document_visible_to(cs.source_id, p_user_id)
            ELSE TRUE
          END
      )
    );
$$;


ALTER FUNCTION "public"."claim_visible_to"("p_claim_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_attachment_knowledge"("p_attachment_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := public._resolve_requester(p_user_id);
BEGIN
  IF NOT public._is_member_of(v_uid, p_workspace_id) THEN
    RAISE EXCEPTION 'not a member of workspace' USING ERRCODE = '42501';
  END IF;
  RETURN public._cleanup_claim_provenance(
    p_workspace_id,
    jsonb_build_array(jsonb_build_object('t', 'attachment', 'id', p_attachment_id))
  );
END
$$;


ALTER FUNCTION "public"."cleanup_attachment_knowledge"("p_attachment_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_notifications"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with gone as (
    delete from public.notification
    where (is_read = true and created_at < now() - interval '30 days')
       or created_at < now() - interval '90 days'
    returning 1
  )
  select count(*)::integer from gone;
$$;


ALTER FUNCTION "public"."cleanup_old_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_adopt_domain_contacts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.domain IS NULL OR NEW.domain = ''
     OR public.is_personal_email_domain(NEW.domain) THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.domain IS NOT DISTINCT FROM OLD.domain THEN
    RETURN NEW;
  END IF;
  -- Adopt only as the workspace's canonical (oldest) company for this
  -- domain — a newer case-variant duplicate must not split the rollup.
  IF NEW.id <> (
    SELECT id FROM public.company
    WHERE workspace_id = NEW.workspace_id
      AND lower(domain) = lower(NEW.domain)
    ORDER BY created_at, id
    LIMIT 1
  ) THEN
    RETURN NEW;
  END IF;
  UPDATE public.contact
  SET company_id = NEW.id,
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('company_autolinked', true),
      updated_at = now()
  WHERE workspace_id = NEW.workspace_id
    AND company_id IS NULL
    AND email IS NOT NULL
    AND member_id IS NULL
    AND (source_provider IS NULL OR source_provider <> 'hubspot')
    AND lower(split_part(email, '@', 2)) = lower(NEW.domain);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."company_adopt_domain_contacts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_visible_to"("p_company_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_member_id    uuid;
  v_role         text;
BEGIN
  SELECT c.workspace_id INTO v_workspace_id
    FROM public.company c
   WHERE c.id = p_company_id;
  IF v_workspace_id IS NULL THEN RETURN FALSE; END IF;

  IF p_user_id IS NULL THEN
    RETURN EXISTS (
      SELECT 1 FROM public.contact ct
       WHERE ct.company_id = p_company_id
         AND ct.merged_into_contact_id IS NULL
         AND ct.visibility = 'workspace'
    );
  END IF;

  SELECT m.id, m.role INTO v_member_id, v_role
    FROM public.member m
   WHERE m.user_id = p_user_id AND m.workspace_id = v_workspace_id
   LIMIT 1;
  IF v_member_id IS NULL THEN RETURN FALSE; END IF;

  IF v_role IN ('owner','admin') THEN RETURN TRUE; END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.contact ct
     WHERE ct.company_id = p_company_id
       AND ct.merged_into_contact_id IS NULL
       AND public.contact_visible_to(ct.id, p_user_id)
  );
END
$$;


ALTER FUNCTION "public"."company_visible_to"("p_company_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_action"("p_user_id" "uuid", "p_action_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET status = 'completed', completed_at = NOW(), updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id AND status IN ('confirmed', 'in_progress');
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."complete_action"("p_user_id" "uuid", "p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_action"("p_user_id" "uuid", "p_action_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET status = 'confirmed', updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id AND status = 'suggested';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."confirm_action"("p_user_id" "uuid", "p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_autolink_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_domain text;
  v_company_id uuid;
BEGIN
  -- Only a real email change may re-link (see header: UPDATE OF fires on
  -- column mention, and the UI round-trips unchanged emails on blur).
  IF TG_OP = 'UPDATE' AND NEW.email IS NOT DISTINCT FROM OLD.email THEN
    RETURN NEW;
  END IF;
  IF NEW.company_id IS NOT NULL
     OR NEW.email IS NULL
     OR NEW.member_id IS NOT NULL
     OR NEW.source_provider = 'hubspot' THEN
    RETURN NEW;
  END IF;
  v_domain := lower(split_part(NEW.email, '@', 2));
  IF v_domain = '' OR public.is_personal_email_domain(v_domain) THEN
    RETURN NEW;
  END IF;
  -- Duplicate domains resolve to the oldest company, deterministically —
  -- the adopt trigger and backfill below must pick the same one.
  SELECT id INTO v_company_id
  FROM public.company
  WHERE workspace_id = NEW.workspace_id
    AND lower(domain) = v_domain
  ORDER BY created_at, id
  LIMIT 1;
  IF v_company_id IS NOT NULL THEN
    NEW.company_id := v_company_id;
    NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb)
      || jsonb_build_object('company_autolinked', true);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contact_autolink_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_emails_text"("emails" "text"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$ SELECT array_to_string(coalesce(emails, '{}'), ' ') $$;


ALTER FUNCTION "public"."contact_emails_text"("emails" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_visible_to"("p_contact_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_c         public.contact%ROWTYPE;
  v_member_id uuid;
  v_role      text;
BEGIN
  SELECT * INTO v_c FROM public.contact WHERE id = p_contact_id;
  IF v_c.id IS NULL THEN RETURN FALSE; END IF;

  IF p_user_id IS NULL THEN RETURN v_c.visibility = 'workspace'; END IF;

  SELECT m.id, m.role INTO v_member_id, v_role
    FROM public.member m
   WHERE m.user_id = p_user_id AND m.workspace_id = v_c.workspace_id
   LIMIT 1;
  IF v_member_id IS NULL THEN RETURN FALSE; END IF;

  IF v_c.visibility = 'workspace' THEN RETURN TRUE; END IF;
  IF v_member_id = v_c.created_by_member_id THEN RETURN TRUE; END IF;
  IF v_role IN ('owner','admin') THEN RETURN TRUE; END IF;

  IF v_c.visibility = 'team' AND v_c.created_by_member_id IS NOT NULL AND EXISTS (
       SELECT 1
         FROM public.team_member tm1
         JOIN public.team_member tm2 ON tm2.team_id = tm1.team_id
        WHERE tm1.member_id = v_member_id
          AND tm2.member_id = v_c.created_by_member_id
  ) THEN RETURN TRUE; END IF;

  IF EXISTS (
       SELECT 1 FROM public.contact_share cs
        WHERE cs.contact_id = p_contact_id AND cs.shared_with_member_id = v_member_id
  ) THEN RETURN TRUE; END IF;

  IF EXISTS (
       SELECT 1
         FROM public.contact_share cs
         JOIN public.team_member tm ON tm.team_id = cs.shared_with_team_id
        WHERE cs.contact_id = p_contact_id AND tm.member_id = v_member_id
  ) THEN RETURN TRUE; END IF;

  RETURN FALSE;
END
$$;


