CREATE OR REPLACE FUNCTION "public"."delete_capture_with_knowledge"("p_capture_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid            uuid := public._resolve_requester(p_user_id);
  v_owner          uuid;
  v_attachment_ids uuid[] := '{}';
  v_pairs          jsonb;
  v_cleanup        jsonb;
BEGIN
  SELECT user_id INTO v_owner
    FROM public.captures
   WHERE id = p_capture_id AND workspace_id = p_workspace_id
     FOR UPDATE;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'capture not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not the capture owner' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(array_agg(id), '{}') INTO v_attachment_ids
    FROM public.attachments
   WHERE note_id = p_capture_id;
  v_pairs := jsonb_build_array(jsonb_build_object('t', 'capture', 'id', p_capture_id));
  IF cardinality(v_attachment_ids) > 0 THEN
    v_pairs := v_pairs || (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('t', 'attachment', 'id', aid)), '[]'::jsonb)
        FROM unnest(v_attachment_ids) AS aid
    );
  END IF;
  v_cleanup := public._cleanup_claim_provenance(p_workspace_id, v_pairs);
  DELETE FROM public.captures
   WHERE id = p_capture_id AND workspace_id = p_workspace_id;
  RETURN jsonb_build_object(
    'capture_id',  p_capture_id,
    'attachments', cardinality(v_attachment_ids),
    'cleanup',     v_cleanup
  );
END
$$;


ALTER FUNCTION "public"."delete_capture_with_knowledge"("p_capture_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_document_with_knowledge"("p_document_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid        uuid := public._resolve_requester(p_user_id);
  v_exists     boolean;
  v_created_by uuid;
  v_member     uuid;
  v_role       text;
  v_cleanup    jsonb;
begin
  if not public._is_member_of(v_uid, p_workspace_id) then
    raise exception 'not a member of workspace' using errcode = '42501';
  end if;

  select true, d.created_by into v_exists, v_created_by
    from public.document d
   where d.id = p_document_id and d.workspace_id = p_workspace_id
     for update;

  if v_exists is null then
    raise exception 'document not found' using errcode = 'P0002';
  end if;

  -- Owner or admin; or the creator, except the product doc.
  select m.id, m.role into v_member, v_role
    from public.member m
   where m.user_id = v_uid and m.workspace_id = p_workspace_id
   limit 1;

  if not (
    v_role in ('owner', 'admin')
    or (
      v_created_by is not null
      and v_created_by = v_member
      and not public.is_product_doc(p_workspace_id, p_document_id)
    )
  ) then
    raise exception 'only the creator or an admin can delete this document' using errcode = '42501';
  end if;

  v_cleanup := public._cleanup_claim_provenance(
    p_workspace_id,
    jsonb_build_array(jsonb_build_object('t', 'document', 'id', p_document_id))
  );

  delete from public.document
   where id = p_document_id and workspace_id = p_workspace_id;

  return jsonb_build_object(
    'document_id', p_document_id,
    'cleanup',     v_cleanup
  );
end
$$;


ALTER FUNCTION "public"."delete_document_with_knowledge"("p_document_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_action"("p_user_id" "uuid", "p_action_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET
        is_dismissed = TRUE,
        dismissed_reason = p_reason,
        dismissed_at = NOW(),
        updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id AND status = 'suggested';
    RETURN FOUND;
END;
$$;


