CREATE OR REPLACE FUNCTION "public"."document_guard_outside_derived"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  -- The service role, postgres and SECURITY DEFINER functions are server paths.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.outside_derived := false;
  else
    new.outside_derived := old.outside_derived;
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."document_guard_outside_derived"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_guard_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role   text;
  v_member uuid;
begin
  -- The service role, postgres and SECURITY DEFINER functions (move_document,
  -- delete_document_with_knowledge, the workspace-move engine) are server
  -- paths with their own gates.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if new.id is distinct from old.id or new.workspace_id is distinct from old.workspace_id then
    raise exception 'a document changes workspace only through move_document' using errcode = '42501';
  end if;

  -- The stamp's value, and whether the key is there at all (440): kind tests
  -- frontmatter ? key, which an array or string frontmatter can also pass
  -- while frontmatter -> key reads NULL.
  if (new.frontmatter -> 'meeting_prep') is distinct from (old.frontmatter -> 'meeting_prep')
     or (coalesce(new.frontmatter, '{}'::jsonb) ? 'meeting_prep') is distinct from (coalesce(old.frontmatter, '{}'::jsonb) ? 'meeting_prep') then
    raise exception 'a meeting prep stamp is written by the server only' using errcode = '42501';
  end if;

  -- The Now file's stamp (440), the same way.
  if (new.frontmatter -> 'now') is distinct from (old.frontmatter -> 'now')
     or (coalesce(new.frontmatter, '{}'::jsonb) ? 'now') is distinct from (coalesce(old.frontmatter, '{}'::jsonb) ? 'now') then
    raise exception 'a Now file stamp is written by the server only' using errcode = '42501';
  end if;

  v_role := public.get_member_role(old.workspace_id);
  if v_role in ('owner', 'admin') then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'only an owner or admin can change who created a document' using errcode = '42501';
  end if;

  v_member := public.current_member_id(old.workspace_id);
  if old.created_by is not null and old.created_by = v_member then
    return new;
  end if;

  if new.status is distinct from old.status
     or new.published_status is distinct from old.published_status
     or new.slug is distinct from old.slug
     or new.type is distinct from old.type then
    raise exception 'only the creator or an admin can archive, unpublish, rename the slug of or retype a shared page' using errcode = '42501';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."document_guard_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_system_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    if private.is_system_document(old.workspace_id, old.id, old.canon_key) then
      raise exception 'this is a system document: it can be edited, not deleted' using errcode = 'P0013';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE'
     and new.status = 'archived'
     and old.status is distinct from 'archived'
     and private.is_system_document(old.workspace_id, old.id, coalesce(old.canon_key, new.canon_key)) then
    raise exception 'this is a system document: it can be edited, not archived' using errcode = 'P0013';
  end if;

  -- From a client, only an owner or admin sets or clears the key; a member
  -- may set (never clear) a personal key on a document they created.
  if current_user in ('authenticated', 'anon')
     and (case when tg_op = 'INSERT' then new.canon_key is not null else new.canon_key is distinct from old.canon_key end)
     and coalesce(public.get_member_role(new.workspace_id), '') not in ('owner', 'admin')
     and not (
       new.canon_key is not null
       and new.canon_key ~ '^(person|content-brief):'
       and (tg_op = 'INSERT' or old.canon_key is null)
       and new.created_by is not null
       and new.created_by = public.current_member_id(new.workspace_id)
     ) then
    raise exception 'only an owner or admin can set which documents are system documents' using errcode = '42501';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."document_system_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_track_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source    text;
  v_summary   text;
  v_author    uuid;
  v_latest_id uuid;
  v_latest_no integer;
  v_latest_kind text;
  v_latest_author uuid;
  v_latest_at timestamptz;
  v_latest_meta jsonb;
  v_coalesce  boolean := false;
  v_meta      jsonb;
begin
  if tg_op = 'INSERT' then
    new.revision := 1;
    new.edit_source := null;
    new.edit_summary := null;
    new.edit_meta := null;
    return new;
  end if;

  v_source := new.edit_source;
  v_summary := nullif(btrim(coalesce(new.edit_summary, '')), '');
  -- What a section edit was (376): only an object, at most 8 KB, else nothing.
  v_meta := case
    when jsonb_typeof(new.edit_meta) = 'object' and octet_length(new.edit_meta::text) <= 8192 then new.edit_meta
    else null
  end;
  new.edit_source := null;
  new.edit_summary := null;
  new.edit_meta := null;

  if new.content is not distinct from old.content and new.title is not distinct from old.title then
    -- Not a change to the text: the revision is the trigger's to set.
    new.revision := old.revision;
    return new;
  end if;

  if auth.uid() is not null then
    -- A signed-in caller writes as themselves: a human edit, by their own
    -- member row, whatever edit_source and last_edited_by they sent.
    v_source := 'human';
    v_meta := null;
    v_author := public.current_member_id(new.workspace_id);
    new.last_edited_by := v_author;
  elsif coalesce(v_source, 'system') = 'system' and new.last_edited_by is not distinct from old.last_edited_by then
    -- A server write that names no new editor has no author (not the last one's).
    v_author := null;
  else
    v_author := new.last_edited_by;
  end if;

  select r.id, r.revision_number, r.author_kind, r.author_id, r.created_at, r.edit_meta
    into v_latest_id, v_latest_no, v_latest_kind, v_latest_author, v_latest_at, v_latest_meta
    from public.document_revision r
   where r.document_id = old.id
   order by r.revision_number desc
   limit 1;

  new.revision := greatest(old.revision, coalesce(v_latest_no, 0)) + 1;

  if v_latest_id is null or v_latest_no <> old.revision then
    -- The state being replaced isn't in history yet: keep it as a baseline,
    -- so this change can be undone. An empty untitled body has nothing to
    -- go back to.
    if coalesce(old.content, '') <> '' or coalesce(old.title, '') <> '' then
      insert into public.document_revision (
        document_id, workspace_id, revision_number, title, content, content_json,
        frontmatter, tags, author_id, author_kind, change_summary, created_at, updated_at
      ) values (
        old.id, old.workspace_id, old.revision, old.title, old.content, old.content_json,
        old.frontmatter, old.tags, coalesce(old.last_edited_by, old.created_by), null, null,
        old.updated_at, old.updated_at
      )
      on conflict (document_id, revision_number) do nothing;
    end if;
  else
    -- The latest row is the state being replaced: a human autosave by the
    -- same person within 10 minutes of that row folds into it.
    v_coalesce := v_source = 'human'
      and v_author is not null
      and v_latest_kind = 'human'
      and v_latest_author = v_author
      and v_summary is null
      and v_meta is null
      and v_latest_at > now() - interval '10 minutes';
    -- A Now file (440): an agent write folds into the agent row it replaces,
    -- from the same writer (edit_meta.writer) for the same person, within 10
    -- minutes of that row's created_at. A summary doesn't stop it.
    if not coalesce(v_coalesce, false)
       and coalesce(new.frontmatter, '{}'::jsonb) ? 'now'
       and v_source = 'agent'
       and v_author is not null
       and v_latest_kind = 'agent'
       and v_latest_author = v_author
       and nullif(v_meta ->> 'writer', '') is not null
       and (v_meta ->> 'writer') = (v_latest_meta ->> 'writer')
       and v_latest_at > now() - interval '10 minutes' then
      v_coalesce := true;
    end if;
  end if;

  if v_coalesce then
    update public.document_revision
       set revision_number = new.revision,
           title = new.title,
           content = new.content,
           content_json = new.content_json,
           frontmatter = new.frontmatter,
           tags = new.tags,
           change_summary = coalesce(v_summary, change_summary),
           edit_meta = coalesce(v_meta, edit_meta),
           updated_at = now()
     where id = v_latest_id;
  else
    insert into public.document_revision (
      document_id, workspace_id, revision_number, title, content, content_json,
      frontmatter, tags, author_id, author_kind, change_summary, edit_meta, created_at, updated_at
    ) values (
      new.id, new.workspace_id, new.revision, new.title, new.content, new.content_json,
      new.frontmatter, new.tags, v_author, coalesce(v_source, 'system'), v_summary, v_meta,
      now(), now()
    );
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."document_track_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_visibility_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF new.visibility = 'private' THEN
    -- A private document needs its creator, except one that was already
    -- private and has lost its creator (their member row was removed).
    IF new.created_by IS NULL
       AND NOT (tg_op = 'UPDATE' AND old.visibility = 'private') THEN
      RAISE EXCEPTION 'a private document needs its creator' USING ERRCODE = 'P0015';
    END IF;
    IF private.is_system_document(new.workspace_id, new.id, new.canon_key) THEN
      RAISE EXCEPTION 'this is a system document: it can''t be private' USING ERRCODE = 'P0014';
    END IF;
  END IF;

  -- A Now file (440) is its creator's alone: always private, never canon.
  IF coalesce(new.frontmatter, '{}'::jsonb) ? 'now' THEN
    IF new.visibility IS DISTINCT FROM 'private' THEN
      RAISE EXCEPTION 'a Now file is always private' USING ERRCODE = 'P0016';
    END IF;
    IF new.canon_key IS NOT NULL THEN
      RAISE EXCEPTION 'a Now file is never a canon document' USING ERRCODE = 'P0016';
    END IF;
  END IF;

  -- From a client, only its creator says who can see a document.
  IF tg_op = 'UPDATE'
     AND new.visibility IS DISTINCT FROM old.visibility
     AND current_user IN ('authenticated', 'anon')
     AND (old.created_by IS NULL OR old.created_by IS DISTINCT FROM public.current_member_id(old.workspace_id)) THEN
    RAISE EXCEPTION 'only its creator can change who can see a document' USING ERRCODE = '42501';
  END IF;

  RETURN new;
END
$$;


ALTER FUNCTION "public"."document_visibility_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_visible_to"("p_document_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.document d
    WHERE d.id = p_document_id
      AND (
        d.visibility = 'workspace'
        OR (
          p_user_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM public.member m
            WHERE m.id = d.created_by
              AND m.user_id = p_user_id
          )
        )
      )
  );
$$;


ALTER FUNCTION "public"."document_visible_to"("p_document_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_action_status_team"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_state_team uuid;
  v_name public.workflow_state.name%TYPE;
  v_category public.workflow_state.category%TYPE;
BEGIN
  IF new.status_id IS NULL OR new.team_id IS NULL THEN
    RETURN new;
  END IF;

  SELECT ws.team_id, ws.name, ws.category
  INTO v_state_team, v_name, v_category
  FROM public.workflow_state ws
  WHERE ws.id = new.status_id;

  -- Fast path: unknown state (let the FK speak) or already consistent.
  IF v_state_team IS NULL OR v_state_team = new.team_id THEN
    RETURN new;
  END IF;

  new.status_id := COALESCE(
    (SELECT ws2.id FROM public.workflow_state ws2
     WHERE ws2.team_id = new.team_id AND lower(ws2.name) = lower(v_name)
     ORDER BY ws2.sort_order ASC, ws2.id ASC LIMIT 1),
    (SELECT ws2.id FROM public.workflow_state ws2
     WHERE ws2.team_id = new.team_id AND ws2.category = v_category
     ORDER BY ws2.sort_order ASC, ws2.id ASC LIMIT 1),
    (SELECT ws2.id FROM public.workflow_state ws2
     WHERE ws2.team_id = new.team_id AND ws2.is_default
     ORDER BY ws2.sort_order ASC, ws2.id ASC LIMIT 1),
    (SELECT ws2.id FROM public.workflow_state ws2
     WHERE ws2.team_id = new.team_id
     ORDER BY ws2.sort_order ASC, ws2.id ASC LIMIT 1),
    new.status_id);

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."enforce_action_status_team"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_action_status_team"() IS 'BEFORE trigger on actions: when an insert/update would leave status_id pointing at another team''s workflow state, remap it onto the action''s own team by name, then category, then the team default (the same ladder the cross-workspace move engine uses). Consistent writes are untouched.';


CREATE OR REPLACE FUNCTION "public"."enforce_eval_capture_participant_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_eval boolean;
  v_capture_user uuid;
  v_member_user uuid;
BEGIN
  IF new.contact_id IS NULL AND new.member_id IS NULL THEN
    RETURN new;
  END IF;

  SELECT c.is_eval, c.user_id
  INTO v_is_eval, v_capture_user
  FROM public.captures c
  WHERE c.id = new.capture_id;

  IF v_is_eval IS NOT TRUE THEN
    RETURN new;
  END IF;

  IF new.contact_id IS NOT NULL THEN
    RAISE EXCEPTION
      'capture_participant.contact_id must be NULL on an eval capture (capture %)', new.capture_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF new.member_id IS NOT NULL THEN
    IF NOT new.is_self THEN
      RAISE EXCEPTION
        'capture_participant.member_id is allowed on an eval capture only for the self participant (capture %)', new.capture_id
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT m.user_id INTO v_member_user
    FROM public.member m
    WHERE m.id = new.member_id;

    IF v_member_user IS NULL OR v_member_user IS DISTINCT FROM v_capture_user THEN
      RAISE EXCEPTION
        'the self participant on an eval capture must be the capture owner (capture %)', new.capture_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."enforce_eval_capture_participant_links"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."environment_check_chat_ref"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.environment_id is null or public._wsmerge_active() then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.environment_id is not distinct from old.environment_id
     and new.workspace_id is not distinct from old.workspace_id
     and new.user_id is not distinct from old.user_id then
    return new;
  end if;
  if public._environment_usable(new.environment_id, new.user_id, new.workspace_id, false) then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.environment_id is not distinct from old.environment_id then
    new.environment_id := null;
    return new;
  end if;
  raise exception 'a chat''s environment must be its owner''s Mac or a cloud environment of its workspace they can use'
    using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."environment_check_chat_ref"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."environment_check_default_ref"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if public._wsmerge_active() then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.environment_id is not distinct from old.environment_id
     and new.workspace_id is not distinct from old.workspace_id
     and new.user_id is not distinct from old.user_id
     and new.project_id is not distinct from old.project_id then
    return new;
  end if;
  if new.project_id is not null and not exists (
    select 1 from public.projects p where p.id = new.project_id and p.workspace_id = new.workspace_id
  ) then
    raise exception 'a project default must name a project of its workspace' using errcode = '42501';
  end if;
  if public._environment_usable(new.environment_id, new.user_id, new.workspace_id, new.project_id is not null) then
    return new;
  end if;
  raise exception 'a default environment must be your own Mac, or (for a workspace) a cloud environment of it you can use'
    using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."environment_check_default_ref"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."environment_check_project_ref"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.environment_id is null or public._wsmerge_active() then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.environment_id is not distinct from old.environment_id
     and new.workspace_id is not distinct from old.workspace_id then
    return new;
  end if;
  if public._environment_shared_in(new.environment_id, new.workspace_id) then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.environment_id is not distinct from old.environment_id then
    new.environment_id := null;
    return new;
  end if;
  raise exception 'a project''s environment must be a shared cloud environment of its own workspace'
    using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."environment_check_project_ref"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."environment_check_run_ref"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.environment_id is null or public._wsmerge_active() then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.environment_id is not distinct from old.environment_id then
    return new;
  end if;
  if exists (
    select 1 from public.environment e
    where e.id = new.environment_id and e.kind = 'cloud' and e.archived_at is null
      and e.workspace_id = new.workspace_id
  ) then
    return new;
  end if;
  raise exception 'a run''s environment must be a live cloud environment of its own workspace' using errcode = '42501';
end;
$$;


