CREATE OR REPLACE FUNCTION "public"."environment_drop_moved_project_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if public._wsmerge_active() or new.workspace_id is not distinct from old.workspace_id then
    return null;
  end if;
  delete from public.environment_default d
  where d.project_id = new.id and d.workspace_id is distinct from new.workspace_id;
  return null;
end;
$$;


ALTER FUNCTION "public"."environment_drop_moved_project_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."environment_guard_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if public._wsmerge_active() then
    return new;
  end if;
  if new.kind is distinct from old.kind
     or new.owner_user_id is distinct from old.owner_user_id
     or new.device_id is distinct from old.device_id
     or new.workspace_id is distinct from old.workspace_id then
    raise exception 'an environment''s kind, owner, Mac and workspace are fixed' using errcode = '42501';
  end if;
  if old.shared and not new.shared and (
    exists (select 1 from public.projects p where p.environment_id = old.id)
    or exists (select 1 from public.workspace w where w.default_cloud_environment_id = old.id)
  ) then
    raise exception 'a cloud environment a project or the workspace default uses must stay shared' using errcode = '42501';
  end if;
  if old.archived_at is null and new.archived_at is not null and (
    exists (select 1 from public.projects p where p.environment_id = old.id)
    or exists (select 1 from public.workspace w where w.default_cloud_environment_id = old.id)
  ) then
    raise exception 'a cloud environment a project or the workspace default uses can''t be archived' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."environment_guard_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eval_case_refresh_suite_summary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- The suite is mid-cascade: refreshing it would read three indexes to
    -- UPDATE zero rows, once per cascaded case.
    IF NOT EXISTS (SELECT 1 FROM public.eval_suite WHERE id = OLD.suite_id) THEN
      RETURN OLD;
    END IF;
    PERFORM public.eval_suite_refresh_summary(OLD.suite_id);
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.suite_id IS DISTINCT FROM OLD.suite_id THEN
    PERFORM public.eval_suite_refresh_summary(OLD.suite_id);
  END IF;
  PERFORM public.eval_suite_refresh_summary(NEW.suite_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."eval_case_refresh_suite_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eval_case_refresh_summary"("p_case_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_outcome text;
  v_last_run_at  timestamptz;
BEGIN
  IF p_case_id IS NULL THEN RETURN; END IF;

  SELECT t.started_at INTO v_last_run_at
  FROM public.eval_trial t
  WHERE t.case_id = p_case_id
  ORDER BY t.started_at DESC, t.id DESC
  LIMIT 1;

  SELECT CASE
           WHEN t.status IN ('errored', 'cancelled') THEN 'errored'
           ELSE t.outcome
         END
  INTO v_last_outcome
  FROM public.eval_trial t
  WHERE t.case_id = p_case_id
    AND t.status IN ('completed', 'errored', 'cancelled')
  ORDER BY t.started_at DESC, t.id DESC
  LIMIT 1;

  UPDATE public.eval_case
  SET last_outcome = v_last_outcome,
      last_run_at  = v_last_run_at
  WHERE id = p_case_id;
END;
$$;


ALTER FUNCTION "public"."eval_case_refresh_summary"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eval_run_refresh_suite_summary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM public.eval_suite WHERE id = OLD.suite_id) THEN
      RETURN OLD;
    END IF;
    PERFORM public.eval_suite_refresh_summary(OLD.suite_id);
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.suite_id IS DISTINCT FROM OLD.suite_id THEN
    PERFORM public.eval_suite_refresh_summary(OLD.suite_id);
  END IF;
  PERFORM public.eval_suite_refresh_summary(NEW.suite_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."eval_run_refresh_suite_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eval_suite_refresh_summary"("p_suite_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_case_count    integer;
  v_last_run_at   timestamptz;
  v_last_run_mode text;
  v_last_outcome  text;
BEGIN
  IF p_suite_id IS NULL THEN RETURN; END IF;

  SELECT count(*) INTO v_case_count
  FROM public.eval_case
  WHERE suite_id = p_suite_id;

  SELECT r.started_at, r.mode INTO v_last_run_at, v_last_run_mode
  FROM public.eval_run r
  WHERE r.suite_id = p_suite_id
  ORDER BY r.started_at DESC, r.id DESC
  LIMIT 1;

  SELECT CASE
           WHEN r.status IN ('failed', 'cancelled') THEN 'errored'
           ELSE r.outcome
         END
  INTO v_last_outcome
  FROM public.eval_run r
  WHERE r.suite_id = p_suite_id
    AND r.status IN ('completed', 'failed', 'cancelled')
  ORDER BY r.started_at DESC, r.id DESC
  LIMIT 1;

  UPDATE public.eval_suite
  SET case_count    = COALESCE(v_case_count, 0),
      last_run_at   = v_last_run_at,
      last_run_mode = v_last_run_mode,
      last_outcome  = v_last_outcome
  WHERE id = p_suite_id;
END;
$$;


ALTER FUNCTION "public"."eval_suite_refresh_summary"("p_suite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eval_trial_refresh_case_summary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Same shape as above: eval_trial cascades from eval_run and eval_case, so
    -- a suite delete drags every trial through here too.
    IF NOT EXISTS (SELECT 1 FROM public.eval_case WHERE id = OLD.case_id) THEN
      RETURN OLD;
    END IF;
    PERFORM public.eval_case_refresh_summary(OLD.case_id);
    RETURN OLD;
  END IF;
  PERFORM public.eval_case_refresh_summary(NEW.case_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."eval_trial_refresh_case_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_stale_suggestions"("p_now" timestamp with time zone, "p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "expire_reason" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH stale AS (
    SELECT pc.id,
           CASE
             WHEN pc.document_id IS NULL AND pc.conversation_id IS NULL
               THEN 'run_undelivered'
             ELSE 'ttl'
           END AS reason
    FROM proposed_change pc
    WHERE pc.status = 'pending'
      AND pc.capture_id IS NULL
      AND pc.applied_at IS NULL
      AND pc.result_entity_id IS NULL
      AND (pc.extra ->> 'applied_at') IS NULL
      AND (
        pc.expires_at < p_now
        OR (pc.document_id IS NULL AND pc.conversation_id IS NULL
            AND pc.created_at < p_now - interval '24 hours')
      )
    ORDER BY pc.expires_at ASC NULLS LAST
    LIMIT greatest(coalesce(p_limit, 500), 1)
  )
  UPDATE proposed_change pc SET
    status = 'expired',
    expire_reason = stale.reason
  FROM stale
  WHERE pc.id = stale.id
    -- Re-assert at write time: a row accepted since the scan is left alone.
    AND pc.status = 'pending'
    AND pc.capture_id IS NULL
    AND pc.applied_at IS NULL
    AND pc.result_entity_id IS NULL
    AND (pc.extra ->> 'applied_at') IS NULL
  RETURNING pc.id, pc.workspace_id, pc.expire_reason;
$$;


ALTER FUNCTION "public"."expire_stale_suggestions"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."export_workspace_manifest"("p_workspace" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record; n bigint; v_out jsonb := '[]'::jsonb;
BEGIN
  FOR r IN SELECT * FROM public._wsmerge_export_tables() ORDER BY table_name LOOP
    IF to_regclass('public.' || quote_ident(r.table_name)) IS NULL THEN
      CONTINUE;
    END IF;
    EXECUTE format('SELECT count(*) FROM public.%I x WHERE %s', r.table_name, r.predicate) INTO n USING p_workspace;
    IF n > 0 THEN
      v_out := v_out || jsonb_build_object('table', r.table_name, 'rows', n);
    END IF;
  END LOOP;
  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."export_workspace_manifest"("p_workspace" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."export_workspace_rows"("p_workspace" "uuid", "p_table" "text", "p_after" "jsonb" DEFAULT NULL::"jsonb", "p_max_bytes" integer DEFAULT 20971520) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_pred text; v_cols text; v_keys text[]; v_types text[];
  v_order text; v_cursor text; v_after_vals text; v_after_pred text := 'TRUE';
  v_out jsonb;
BEGIN
  SELECT predicate INTO v_pred FROM public._wsmerge_export_tables() WHERE table_name = p_table;
  IF v_pred IS NULL OR to_regclass('public.' || quote_ident(p_table)) IS NULL THEN
    RAISE EXCEPTION 'table % is not exported', p_table USING ERRCODE = '22023';
  END IF;
  IF p_max_bytes IS NULL OR p_max_bytes < 1024 OR p_max_bytes > 52428800 THEN
    RAISE EXCEPTION 'max bytes must be between 1 KB and 50 MB' USING ERRCODE = '22023';
  END IF;

  -- the columns: no vectors, no search vectors, no credential material
  SELECT string_agg(format('%I', c.column_name), ', ' ORDER BY c.ordinal_position) INTO v_cols
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = p_table
    AND c.udt_name NOT IN ('vector', 'halfvec', 'tsvector')
    AND NOT (c.table_name = 'cloud_environment' AND c.column_name = 'env_vars')
    AND NOT (c.table_name = 'connected_mcp_server' AND c.column_name IN ('access_token_encrypted', 'refresh_token_encrypted'))
    AND NOT (c.table_name = 'task_sync_state' AND c.column_name = 'webhook_secret')
    AND c.column_name !~* '(secret|password|passwd|api_key|private_key|_encrypted$|^token$|_token$|^env_vars$)';

  -- the key: the primary key, in index order
  SELECT array_agg(a.attname::text ORDER BY k.ord), array_agg(format_type(a.atttypid, a.atttypmod) ORDER BY k.ord)
  INTO v_keys, v_types
  FROM pg_index i
  CROSS JOIN LATERAL unnest(i.indkey::smallint[]) WITH ORDINALITY AS k(attnum, ord)
  JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum
  WHERE i.indrelid = ('public.' || quote_ident(p_table))::regclass AND i.indisprimary;
  IF v_keys IS NULL THEN
    RAISE EXCEPTION 'table % has no primary key to page by', p_table USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(format('x.%I', k), ', ') INTO v_order FROM unnest(v_keys) AS k;
  SELECT string_agg(format('%L, x.%I', k, k), ', ') INTO v_cursor FROM unnest(v_keys) AS k;
  IF p_after IS NOT NULL THEN
    SELECT string_agg(format('($2->>%L)::%s', u.k, u.t), ', ' ORDER BY u.ord) INTO v_after_vals
    FROM unnest(v_keys, v_types) WITH ORDINALITY AS u(k, t, ord);
    v_after_pred := format('(%s) > (%s)', v_order, v_after_vals);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT %1$s FROM public.%2$I x WHERE (%3$s) AND (%4$s) ORDER BY %5$s LIMIT 5000
    ),
    sized AS (
      SELECT x.*, octet_length(to_jsonb(x)::text) AS __bytes FROM page x
    ),
    running AS (
      SELECT x.*, sum(x.__bytes) OVER (ORDER BY %5$s) AS __running FROM sized x
    ),
    kept AS (
      SELECT x.* FROM running x WHERE x.__running - x.__bytes < $3
    )
    SELECT jsonb_build_object(
      'rows',   COALESCE((SELECT jsonb_agg(to_jsonb(x) - '__bytes' - '__running' ORDER BY %5$s) FROM kept x), '[]'::jsonb),
      'count',  (SELECT count(*) FROM kept),
      'bytes',  COALESCE((SELECT sum(x.__bytes) FROM kept x), 0),
      'cursor', (SELECT jsonb_build_object(%6$s) FROM kept x ORDER BY %5$s DESC LIMIT 1),
      'done',   (SELECT count(*) FROM page) < 5000 AND (SELECT count(*) FROM kept) = (SELECT count(*) FROM page)
    )
  $q$, v_cols, p_table, v_pred, v_after_pred, v_order, v_cursor)
  INTO v_out USING p_workspace, p_after, p_max_bytes;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION "public"."export_workspace_rows"("p_workspace" "uuid", "p_table" "text", "p_after" "jsonb", "p_max_bytes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flow_check_ai_team_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_mate record;
  v_editor uuid := auth.uid();
  v_run_as uuid;
  v_seed_key text;
begin
  if new.ai_team_member_id is null then
    return new;
  end if;
  if public._wsmerge_active() then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    -- A loop moved to another workspace leaves its bot behind (never a
    -- pointer across workspaces): its editor there asks for one.
    if new.workspace_id is distinct from old.workspace_id
       and new.ai_team_member_id is not distinct from old.ai_team_member_id then
      new.ai_team_member_id := null;
      return new;
    end if;
    -- Nothing the checks read changed: the bot, the workspace, the seed key.
    if new.ai_team_member_id is not distinct from old.ai_team_member_id
       and new.seed_key is not distinct from old.seed_key then
      return new;
    end if;
  end if;

  select atm.workspace_id, atm.team_id, atm.is_system, atm.system_key, t.is_private
    into v_mate
  from public.ai_team_member atm
  left join public.team t on t.id = atm.team_id
  where atm.id = new.ai_team_member_id;
  if not found then
    -- The FK reports a missing row too; this only keeps the message readable.
    raise exception 'that bot no longer exists' using errcode = 'check_violation';
  end if;

  if v_mate.workspace_id is distinct from new.workspace_id then
    raise exception 'a loop''s bot must be one of its own workspace''s teammates'
      using errcode = 'check_violation';
  end if;

  if v_mate.is_system then
    if v_mate.system_key is null or v_mate.system_key not in ('captures') then
      raise exception 'this built-in teammate does not front loops'
        using errcode = 'check_violation';
    end if;
    v_seed_key := case new.seed_key
      when 'seed:triage' then 'captures'
      when 'seed:reconcile' then 'captures'
    end;
    if v_seed_key is not null and v_seed_key <> v_mate.system_key then
      raise exception 'a built-in loop keeps its own teammate'
        using errcode = 'check_violation';
    end if;
    -- A system teammate is readable across private teams (280): everyone reaches it.
    return new;
  end if;

  -- Only an explicit false is public (callerCanReachTeammate's rule).
  if v_mate.is_private is false then
    return new;
  end if;

  if v_editor is not null and not exists (
    select 1
    from public.team_member tm
    join public.member m on m.id = tm.member_id
    where tm.team_id = v_mate.team_id
      and m.user_id = v_editor
      and m.workspace_id = new.workspace_id
  ) then
    raise exception 'that bot is on a private team you are not on'
      using errcode = 'check_violation';
  end if;

  -- The run-as member (run-as-member.ts): the creator while still a member,
  -- else the workspace owner.
  select m.id into v_run_as
  from public.member m
  where m.workspace_id = new.workspace_id
    and m.user_id = new.created_by
  limit 1;
  if v_run_as is null then
    select m.id into v_run_as
    from public.member m
    where m.workspace_id = new.workspace_id
      and m.role = 'owner'
    order by m.created_at asc
    limit 1;
  end if;
  if v_run_as is null or not exists (
    select 1 from public.team_member tm
    where tm.team_id = v_mate.team_id
      and tm.member_id = v_run_as
  ) then
    raise exception 'the person this loop runs as can''t see that bot (it is on a private team they are not on)'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."flow_check_ai_team_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."free_bot_character"("p_workspace_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select f.face
  from unnest(array[
    'research', 'reconciler', 'sprout', 'writer', 'extraction', 'berry',
    'dev', 'nova', 'live', 'flows', 'notes', 'ember', 'dew',
    'mail', 'knowledge', 'calendar', 'acorn', 'browser', 'shroom'
  ]) with ordinality as f(face, ord)
  where not exists (
    select 1 from public.ai_team_member a
    where a.workspace_id = p_workspace_id and a.bot_character = f.face
  )
  order by f.ord
  limit 1
$$;


