CREATE OR REPLACE FUNCTION "public"."generate_action_identifier"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  prefix text;
  counter integer;
BEGIN
  LOOP
    UPDATE public.team
    SET issue_counter = issue_counter + 1
    WHERE id = new.team_id
    RETURNING issue_prefix, issue_counter INTO prefix, counter;

    IF prefix IS NULL THEN
      RETURN new;  -- no team row; let the NOT NULL constraint speak
    END IF;

    new.identifier := prefix || '-' || counter;

    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.actions a
      WHERE a.workspace_id = new.workspace_id
        AND a.identifier = new.identifier
    );
  END LOOP;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."generate_action_identifier"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_cycle_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  next_number integer;
BEGIN
  SELECT coalesce(max(number), 0) + 1
  INTO next_number
  FROM public.cycle
  WHERE team_id = new.team_id;

  new.number := next_number;

  IF new.name IS NULL OR new.name = '' THEN
    new.name := 'Cycle ' || next_number;
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."generate_cycle_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_view_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INT := 0;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := lower(regexp_replace(trim(NEW.name), '[^a-zA-Z0-9]+', '-', 'g'));
    base_slug := trim(both '-' from base_slug);
    final_slug := base_slug;

    LOOP
      EXIT WHEN NOT EXISTS (
        SELECT 1 FROM public.view
        WHERE workspace_id = NEW.workspace_id AND slug = final_slug AND id IS DISTINCT FROM NEW.id
      );
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;

    NEW.slug := final_slug;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_view_slug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_full"("p_user_id" "uuid", "p_contact_id" "uuid") RETURNS TABLE("contact_data" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT jsonb_build_object(
        'id', c.id,
        'user_id', c.user_id,
        'apple_contact_id', c.apple_contact_id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'middle_name', c.middle_name,
        'prefix', c.prefix,
        'suffix', c.suffix,
        'nickname', c.nickname,
        'phonetic_first_name', c.phonetic_first_name,
        'phonetic_last_name', c.phonetic_last_name,
        'maiden_name', c.maiden_name,
        'company', c.company,
        'department', c.department,
        'job_title', c.job_title,
        'phonetic_company', c.phonetic_company,
        'pronouns', c.pronouns,
        'birthday', c.birthday,
        'notes', c.notes,
        'image_url', c.image_url,
        'is_favorite', c.is_favorite,
        'last_synced_at', c.last_synced_at,
        'created_at', c.created_at,
        'updated_at', c.updated_at,
        'phones', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', p.id, 'label', p.label, 'custom_label', p.custom_label,
                'phone_number', p.phone_number, 'is_primary', p.is_primary, 'sort_order', p.sort_order
            ) ORDER BY p.sort_order)
            FROM contact_phones p WHERE p.contact_id = c.id
        ), '[]'::jsonb),
        'emails', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', e.id, 'label', e.label, 'custom_label', e.custom_label,
                'email', e.email, 'is_primary', e.is_primary, 'sort_order', e.sort_order
            ) ORDER BY e.sort_order)
            FROM contact_emails e WHERE e.contact_id = c.id
        ), '[]'::jsonb),
        'addresses', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', a.id, 'label', a.label, 'custom_label', a.custom_label,
                'street', a.street, 'city', a.city, 'state', a.state,
                'postal_code', a.postal_code, 'country', a.country,
                'is_primary', a.is_primary, 'sort_order', a.sort_order
            ) ORDER BY a.sort_order)
            FROM contact_addresses a WHERE a.contact_id = c.id
        ), '[]'::jsonb),
        'urls', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', u.id, 'label', u.label, 'custom_label', u.custom_label,
                'url', u.url, 'sort_order', u.sort_order
            ) ORDER BY u.sort_order)
            FROM contact_urls u WHERE u.contact_id = c.id
        ), '[]'::jsonb),
        'dates', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', d.id, 'label', d.label, 'custom_label', d.custom_label,
                'date', d.date, 'sort_order', d.sort_order
            ) ORDER BY d.sort_order)
            FROM contact_dates d WHERE d.contact_id = c.id
        ), '[]'::jsonb),
        'social_profiles', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', sp.id, 'service', sp.service, 'username', sp.username,
                'url', sp.url, 'sort_order', sp.sort_order
            ) ORDER BY sp.sort_order)
            FROM contact_social_profiles sp WHERE sp.contact_id = c.id
        ), '[]'::jsonb),
        'instant_messages', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', im.id, 'service', im.service, 'username', im.username,
                'sort_order', im.sort_order
            ) ORDER BY im.sort_order)
            FROM contact_instant_messages im WHERE im.contact_id = c.id
        ), '[]'::jsonb),
        'related_names', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', rn.id, 'label', rn.label, 'custom_label', rn.custom_label,
                'name', rn.name, 'related_contact_id', rn.related_contact_id,
                'sort_order', rn.sort_order
            ) ORDER BY rn.sort_order)
            FROM contact_related_names rn WHERE rn.contact_id = c.id
        ), '[]'::jsonb),
        'custom_fields', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', cf.id, 'field_type', cf.field_type, 'label', cf.label,
                'value', cf.value, 'sort_order', cf.sort_order
            ) ORDER BY cf.sort_order)
            FROM contact_custom_fields cf WHERE cf.contact_id = c.id
        ), '[]'::jsonb),
        'groups', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', cg.id, 'name', cg.name, 'color', cg.color, 'icon', cg.icon
            ))
            FROM contact_groups cg
            INNER JOIN contact_group_members cgm ON cgm.group_id = cg.id
            WHERE cgm.contact_id = c.id
        ), '[]'::jsonb)
    ) AS contact_data
    FROM contacts c
    WHERE c.id = p_contact_id AND c.user_id = p_user_id;
END;
$$;


