CREATE OR REPLACE FUNCTION "public"."get_decisions_by_participant_emails"("p_workspace_id" "uuid", "p_emails" "text"[], "p_limit" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "content" "text", "capture_title" "text", "confirmation" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT d.id, d.content, cap.title as capture_title, d.confirmation, d.created_at
  FROM public.decision d
  JOIN public.captures cap ON cap.id = d.capture_id
  JOIN public.capture_participant cp ON cp.capture_id = cap.id
  WHERE cap.workspace_id = p_workspace_id
    AND cp.external_email = ANY(p_emails)
    AND d.confirmation = 'confirmed'
  ORDER BY d.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_decisions_by_participant_emails"("p_workspace_id" "uuid", "p_emails" "text"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_due_actions"("p_user_id" "uuid", "p_window_minutes" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "due_at" timestamp with time zone, "priority" integer, "notification_identifier" "text")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        a.id,
        a.title,
        a.description,
        a.due_at,
        a.priority,
        a.notification_identifier
    FROM actions a
    WHERE a.user_id = p_user_id
      AND a.status IN ('confirmed', 'in_progress')
      AND (a.snoozed_until IS NULL OR a.snoozed_until <= NOW())  -- Not currently snoozed
      AND a.due_at IS NOT NULL
      AND a.due_at <= NOW() + (p_window_minutes || ' minutes')::INTERVAL
      AND a.due_at >= NOW() - INTERVAL '1 minute'
    ORDER BY a.due_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_due_actions"("p_user_id" "uuid", "p_window_minutes" integer) OWNER TO "postgres";


