CREATE OR REPLACE FUNCTION "public"."get_goal_progress"("p_goal_id" "uuid") RETURNS TABLE("total_milestones" integer, "completed_milestones" integer, "total_tasks" integer, "completed_tasks" integer, "progress_percent" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_total_milestones INTEGER;
    v_completed_milestones INTEGER;
    v_total_tasks INTEGER;
    v_completed_tasks INTEGER;
    v_progress NUMERIC := 0;
    v_milestone_weight NUMERIC;
    milestone_record RECORD;
BEGIN
    -- Get milestone counts
    SELECT COUNT(*)::INTEGER INTO v_total_milestones
    FROM milestones WHERE goal_id = p_goal_id;

    SELECT COUNT(*)::INTEGER INTO v_completed_milestones
    FROM milestones WHERE goal_id = p_goal_id AND status = 'completed';

    -- Get total task counts
    SELECT COUNT(*)::INTEGER INTO v_total_tasks
    FROM actions a
    JOIN milestones m ON a.milestone_id = m.id
    WHERE m.goal_id = p_goal_id;

    SELECT COUNT(*)::INTEGER INTO v_completed_tasks
    FROM actions a
    JOIN milestones m ON a.milestone_id = m.id
    WHERE m.goal_id = p_goal_id AND a.status = 'completed';

    -- Calculate cascading progress
    IF v_total_milestones = 0 THEN
        v_progress := 0;
    ELSE
        v_milestone_weight := 100.0 / v_total_milestones;

        FOR milestone_record IN
            SELECT
                m.id,
                m.status,
                COUNT(a.id)::INTEGER as task_count,
                COUNT(a.id) FILTER (WHERE a.status = 'completed')::INTEGER as completed_count
            FROM milestones m
            LEFT JOIN actions a ON a.milestone_id = m.id
            WHERE m.goal_id = p_goal_id
            GROUP BY m.id, m.status
        LOOP
            IF milestone_record.status = 'completed' THEN
                -- Completed milestone = full weight
                v_progress := v_progress + v_milestone_weight;
            ELSIF milestone_record.task_count = 0 THEN
                -- No tasks and not completed = 0%
                v_progress := v_progress + 0;
            ELSE
                -- Calculate task completion within this milestone
                v_progress := v_progress + (v_milestone_weight * milestone_record.completed_count::NUMERIC / milestone_record.task_count::NUMERIC);
            END IF;
        END LOOP;
    END IF;

    RETURN QUERY SELECT
        v_total_milestones,
        v_completed_milestones,
        v_total_tasks,
        v_completed_tasks,
        ROUND(v_progress, 1);
END;
$$;


ALTER FUNCTION "public"."get_goal_progress"("p_goal_id" "uuid") OWNER TO "postgres";


