    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        a.id,
        a.title,
        a.description,
        a.due_at,
        a.source_note_id,
        n.title as note_title,
        a.ai_confidence,
        a.created_at
    FROM actions a
    LEFT JOIN notes n ON n.id = a.source_note_id
    WHERE a.user_id = p_user_id
      AND a.status = 'suggested'
      AND a.source_type = 'meeting_extraction'
      AND a.is_dismissed = FALSE
    ORDER BY a.ai_confidence DESC, a.created_at DESC
    LIMIT p_limit;
END;
