CREATE OR REPLACE FUNCTION "public"."get_milestone_progress"("p_milestone_id" "uuid") RETURNS TABLE("total_tasks" integer, "completed_tasks" integer, "progress_percent" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::INTEGER as total_tasks,
        COUNT(*) FILTER (WHERE a.status = 'completed')::INTEGER as completed_tasks,
        CASE
            WHEN COUNT(*) = 0 THEN 0
            ELSE ROUND((COUNT(*) FILTER (WHERE a.status = 'completed')::NUMERIC / COUNT(*)::NUMERIC) * 100, 1)
        END as progress_percent
    FROM actions a
    WHERE a.milestone_id = p_milestone_id;
END;
$$;


