    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(n.id) as total_notes,
        COUNT(n.id) FILTER (WHERE n.type = 'meeting') as meeting_count,
        COUNT(n.id) FILTER (WHERE n.type = 'journal') as journal_count,
        COUNT(n.id) FILTER (WHERE n.type = 'idea') as idea_count,
        COUNT(n.id) FILTER (WHERE n.type = 'webpage') as webpage_count,
        (SELECT COUNT(*) FROM note_chunks nc WHERE nc.project_id = p_project_id AND nc.user_id = p_user_id) as total_chunks,
        MAX(n.updated_at) as last_updated
    FROM notes n
    WHERE n.project_id = p_project_id
      AND n.user_id = p_user_id
      AND n.status = 'active';
END;
