CREATE OR REPLACE FUNCTION "public"."grant_credits"("p_user_id" "uuid", "p_amount_usd" numeric, "p_kind" "text", "p_idempotency_key" "text", "p_stripe_ref" "text" DEFAULT NULL::"text", "p_stripe_customer_id" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("applied" boolean, "new_balance_usd" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_inserted boolean := false;
  v_balance numeric;
  v_signed numeric;        -- signed ledger delta (refunds reduce the wallet)
  v_granted_delta numeric; -- only positive grants move lifetime_granted
BEGIN
  -- Callers always pass a POSITIVE amount; the RPC applies the sign by kind.
  IF p_amount_usd IS NULL OR p_amount_usd <= 0 THEN
    RAISE EXCEPTION 'grant_credits: amount must be positive, got %', p_amount_usd;
  END IF;
  IF p_kind NOT IN ('topup','admin_grant','refund','adjustment','migration_seed') THEN
    RAISE EXCEPTION 'grant_credits: invalid kind %', p_kind;
  END IF;

  -- refund claws credits back (negative); everything else adds.
  v_signed := CASE WHEN p_kind = 'refund' THEN -p_amount_usd ELSE p_amount_usd END;
  v_granted_delta := CASE WHEN p_kind = 'refund' THEN 0 ELSE p_amount_usd END;

  -- Idempotent insert. A webhook retry / double-click with the same key is a no-op.
  INSERT INTO ai_credit_ledger (user_id, amount_usd, kind, idempotency_key, stripe_ref, note)
  VALUES (p_user_id, v_signed, p_kind, p_idempotency_key, p_stripe_ref, p_note)
  ON CONFLICT (idempotency_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- Ensure a credits row exists and (only when we actually inserted) move the
  -- cached balance + lifetime_granted in the SAME statement/transaction.
  INSERT INTO ai_user_credits (user_id, stripe_customer_id, balance_usd, lifetime_granted_usd, updated_at)
  VALUES (
    p_user_id,
    p_stripe_customer_id,
    CASE WHEN v_inserted THEN v_signed ELSE 0 END,
    CASE WHEN v_inserted THEN v_granted_delta ELSE 0 END,
    now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    balance_usd = ai_user_credits.balance_usd + CASE WHEN v_inserted THEN v_signed ELSE 0 END,
    lifetime_granted_usd = ai_user_credits.lifetime_granted_usd + CASE WHEN v_inserted THEN v_granted_delta ELSE 0 END,
    -- Never clobber an existing customer id with NULL; adopt a provided one.
    stripe_customer_id = COALESCE(p_stripe_customer_id, ai_user_credits.stripe_customer_id),
    updated_at = now()
  RETURNING ai_user_credits.balance_usd INTO v_balance;

  applied := v_inserted;
  new_balance_usd := v_balance;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."grant_credits"("p_user_id" "uuid", "p_amount_usd" numeric, "p_kind" "text", "p_idempotency_key" "text", "p_stripe_ref" "text", "p_stripe_customer_id" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_free_bundle"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
  DECLARE
    v_granted INTEGER := 0;
  BEGIN
    -- Insert speech-to-text if doesn't exist
    IF NOT EXISTS (
      SELECT 1 FROM purchases
      WHERE user_id = p_user_id
        AND feature_id = 'speech_to_text'
        AND status = 'completed'
    ) THEN
      INSERT INTO purchases (user_id, feature_id, purchase_option, price_paid, status, metadata)
      VALUES (p_user_id, 'speech_to_text', 'complete_bundle', 0.00, 'completed',
              '{"promotional": true, "campaign": "first_100_users"}');
      v_granted := v_granted + 1;
    END IF;

    -- Insert text-to-speech if doesn't exist
    IF NOT EXISTS (
      SELECT 1 FROM purchases
      WHERE user_id = p_user_id
        AND feature_id = 'text_to_speech'
        AND status = 'completed'
    ) THEN
      INSERT INTO purchases (user_id, feature_id, purchase_option, price_paid, status, metadata)
      VALUES (p_user_id, 'text_to_speech', 'complete_bundle', 0.00, 'completed',
              '{"promotional": true, "campaign": "first_100_users"}');
      v_granted := v_granted + 1;
    END IF;

    IF v_granted = 2 THEN
      RETURN 'Successfully granted both features';
    ELSIF v_granted = 1 THEN
      RETURN 'Granted 1 feature (user already had the other)';
    ELSE
      RETURN 'User already has both features';
    END IF;
  END;
  $$;


ALTER FUNCTION "public"."grant_free_bundle"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_owner_team_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  default_team_id UUID;
BEGIN
  IF NEW.role = 'owner' THEN
    SELECT id INTO default_team_id
    FROM public.team
    WHERE workspace_id = NEW.workspace_id
    ORDER BY created_at ASC
    LIMIT 1;

    IF default_team_id IS NOT NULL THEN
      INSERT INTO public.team_member (team_id, member_id, team_role)
      VALUES (default_team_id, NEW.id, 'lead')
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


