CREATE OR REPLACE FUNCTION "public"."handle_new_team_creator"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  creator_member_id UUID;
BEGIN
  SELECT id INTO creator_member_id
  FROM public.member
  WHERE user_id = auth.uid()
    AND workspace_id = NEW.workspace_id
  LIMIT 1;

  IF creator_member_id IS NOT NULL THEN
    INSERT INTO public.team_member (team_id, member_id, team_role)
    VALUES (NEW.id, creator_member_id, 'lead')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_team_creator"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_team_workflow_states"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO public.workflow_state (team_id, name, category, color, sort_order, is_default) VALUES
    (NEW.id, 'Backlog',     'backlog',    '#6b7280', 0, false),
    (NEW.id, 'Todo',        'unstarted',  '#3b82f6', 1, true),
    (NEW.id, 'In Progress', 'started',    '#a855f7', 2, false),
    (NEW.id, 'Done',        'completed',  '#22c55e', 3, false),
    (NEW.id, 'Canceled',    'canceled',   '#6b7280', 4, false);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_team_workflow_states"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_workspace_id UUID;
  new_member_id UUID;
  user_name TEXT;
BEGIN
  user_name := coalesce(
    NEW.raw_user_meta_data ->> 'full_name',
    NEW.raw_user_meta_data ->> 'name',
    split_part(NEW.email, '@', 1)
  );

  INSERT INTO public.workspace (name, slug)
  VALUES (
    user_name || '''s Workspace',
    lower(replace(user_name, ' ', '-')) || '-' || substr(NEW.id::text, 1, 8)
  )
  RETURNING id INTO new_workspace_id;

  INSERT INTO public.member (user_id, workspace_id, role, display_name)
  VALUES (NEW.id, new_workspace_id, 'owner', user_name)
  RETURNING id INTO new_member_id;

  INSERT INTO public.contact (
    workspace_id, member_id, email, full_name, first_name, last_name,
    avatar_url, relationship_type, relationship_strength, visibility, source
  ) VALUES (
    new_workspace_id,
    new_member_id,
    lower(NEW.email),
    user_name,
    split_part(user_name, ' ', 1),
    CASE
      WHEN position(' ' in user_name) > 0
      THEN substring(user_name from position(' ' in user_name) + 1)
      ELSE NULL
    END,
    NEW.raw_user_meta_data ->> 'avatar_url',
    'internal',
    'strong',
    'workspace',
    'member'
  );

  UPDATE public.early_access
  SET
    user_id = NEW.id,
    converted_at = now(),
    status = 'signed_up'
  WHERE email = lower(trim(NEW.email))
    AND user_id IS NULL;

  RETURN NEW;
END;
$$;


