    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE early_access
  SET
    user_id = NEW.id,
    converted_at = NOW(),
    status = 'signed_up'
  WHERE email = lower(trim(NEW.email))
    AND user_id IS NULL;

  RETURN NEW;
END;
$$;


