CREATE OR REPLACE FUNCTION "public"."list_companies_with_stats"("p_workspace_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "name" "text", "domain" "text", "logo_url" "text", "industry" "text", "contact_count" bigint, "capture_count" bigint, "last_interaction_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_admin boolean := false;
BEGIN
  IF p_user_id IS NOT NULL THEN
    SELECT m.role IN ('owner','admin') INTO v_is_admin
      FROM public.member m
     WHERE m.user_id = p_user_id AND m.workspace_id = p_workspace_id
     LIMIT 1;
    IF NOT FOUND THEN RETURN; END IF;
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.name,
    c.domain,
    c.logo_url,
    c.industry,
    COUNT(DISTINCT ct.id)          AS contact_count,
    COUNT(DISTINCT cp.capture_id)  AS capture_count,
    MAX(ct.last_interaction_at)    AS last_interaction_at
  FROM public.company c
  LEFT JOIN public.contact ct
    ON ct.company_id = c.id
   AND ct.merged_into_contact_id IS NULL
   AND public.contact_visible_to(ct.id, p_user_id)
  LEFT JOIN public.capture_participant cp
    ON cp.contact_id = ct.id
  WHERE c.workspace_id = p_workspace_id
    AND (p_search IS NULL
         OR c.name   ILIKE '%' || p_search || '%'
         OR c.domain ILIKE '%' || p_search || '%')
  GROUP BY c.id
  HAVING v_is_admin OR COUNT(DISTINCT ct.id) > 0
  ORDER BY MAX(ct.last_interaction_at) DESC NULLS LAST, c.name ASC
  LIMIT p_limit OFFSET p_offset;
END
$$;


ALTER FUNCTION "public"."list_companies_with_stats"("p_workspace_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."local_agent_relay_acquire"("p_user_id" "uuid", "p_session_id" "uuid", "p_max" integer, "p_ttl_seconds" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_live integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('local_agent_relay:' || p_user_id::text, 0));
  delete from public.local_agent_relay_slot where user_id = p_user_id and expires_at < now();
  select count(*) into v_live from public.local_agent_relay_slot where user_id = p_user_id;
  if v_live >= p_max then
    return null;
  end if;
  insert into public.local_agent_relay_slot (user_id, session_id, expires_at)
  values (p_user_id, p_session_id, now() + make_interval(secs => p_ttl_seconds))
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."local_agent_relay_acquire"("p_user_id" "uuid", "p_session_id" "uuid", "p_max" integer, "p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."local_agent_teammate_ask"("p_session_id" "uuid", "p_user_id" "uuid", "p_key" "text", "p_question" "text", "p_per_hour" integer, "p_per_job" integer, "p_per_day" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id bigint;
  v_hour integer;
  v_job integer;
  v_day integer;
begin
  if p_per_hour is null or p_per_job is null or p_per_day is null then
    raise exception 'local_agent_teammate_ask: every cap is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('local_agent_teammate:' || p_user_id::text, 0));

  perform 1
  from public.local_agent_session
  where id = p_session_id and user_id = p_user_id
    and status not in ('cancelled', 'failed', 'expired');
  if not found then
    return jsonb_build_object('status', 'ended');
  end if;

  select id into v_id
  from public.local_agent_event
  where session_id = p_session_id and user_id = p_user_id
    and source = 'server' and kind = 'ask' and payload->>'key' = p_key
  order by id desc
  limit 1;
  if v_id is not null then
    return jsonb_build_object('status', 'duplicate', 'id', v_id);
  end if;

  select
    count(*) filter (where session_id = p_session_id and created_at >= now() - interval '1 hour'),
    count(*) filter (where session_id = p_session_id),
    count(*) filter (where created_at >= now() - interval '24 hours')
  into v_hour, v_job, v_day
  from public.local_agent_event
  where user_id = p_user_id and source = 'server' and kind = 'ask'
    and payload->>'via' = 'message_teammate'
    and (session_id = p_session_id or created_at >= now() - interval '24 hours');
  if v_hour >= p_per_hour then
    return jsonb_build_object('status', 'capped', 'cap', 'hour');
  end if;
  if v_job >= p_per_job then
    return jsonb_build_object('status', 'capped', 'cap', 'job');
  end if;
  if v_day >= p_per_day then
    return jsonb_build_object('status', 'capped', 'cap', 'day');
  end if;

  insert into public.local_agent_event (session_id, user_id, source, kind, payload)
  values (
    p_session_id, p_user_id, 'server', 'ask',
    jsonb_build_object('question', p_question, 'via', 'message_teammate', 'key', p_key)
  )
  returning id into v_id;
  return jsonb_build_object('status', 'recorded', 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."local_agent_teammate_ask"("p_session_id" "uuid", "p_user_id" "uuid", "p_key" "text", "p_question" "text", "p_per_hour" integer, "p_per_job" integer, "p_per_day" integer) OWNER TO "postgres";


