CREATE OR REPLACE FUNCTION "public"."mcp_server_slug"("name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select substring(
    regexp_replace(
      regexp_replace(lower(coalesce(name, '')), '[^a-z0-9]+', '_', 'g'),
      '^_+|_+$', '', 'g'
    ),
    1, 32
  );
$_$;


ALTER FUNCTION "public"."mcp_server_slug"("name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."member_departure_keeps_work"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.workspace w WHERE w.id = OLD.workspace_id)
     OR NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = OLD.user_id) THEN
    DELETE FROM public.comment WHERE author_id = OLD.id;
  ELSE
    UPDATE public.comment
       SET author_id = NULL,
           author_name = OLD.display_name,
           author_avatar_url = OLD.avatar_url
     WHERE author_id = OLD.id;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."member_departure_keeps_work"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."member_guard_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_caller_role text;
begin
  -- The server: the service role, or no request at all.
  if coalesce(auth.role(), '') in ('', 'service_role') then
    return new;
  end if;

  -- A member row is one user in one workspace. It never changes hands.
  if new.id is distinct from old.id
     or new.user_id is distinct from old.user_id
     or new.workspace_id is distinct from old.workspace_id then
    raise exception 'A member row cannot move to another user or workspace'
      using errcode = 'insufficient_privilege';
  end if;

  if new.role is not distinct from old.role then
    return new;
  end if;

  select m.role into v_caller_role
  from public.member m
  where m.workspace_id = old.workspace_id
    and m.user_id = v_uid;

  if v_uid is null or v_caller_role is null then
    raise exception 'Only the workspace owner or an admin can change a role'
      using errcode = 'insufficient_privilege';
  end if;

  -- Your own row: only the owner steps down, and only while another owner
  -- remains. transfer-owner promotes the new owner first, then demotes itself.
  if old.user_id = v_uid then
    if old.role <> 'owner' then
      raise exception 'You cannot change your own role'
        using errcode = 'insufficient_privilege';
    end if;
    if not exists (
      select 1
      from public.member o
      where o.workspace_id = old.workspace_id
        and o.role = 'owner'
        and o.id <> old.id
    ) then
      raise exception 'A workspace needs an owner: transfer ownership before stepping down'
        using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;

  -- The owner sets anyone else's role, owner included.
  if v_caller_role = 'owner' then
    return new;
  end if;

  -- An admin moves a non-owner among admin, member and guest.
  if v_caller_role = 'admin' and old.role <> 'owner' and new.role <> 'owner' then
    return new;
  end if;

  raise exception 'Only the owner can make someone owner or change the owner''s role'
    using errcode = 'insufficient_privilege';
end;
$$;


ALTER FUNCTION "public"."member_guard_update"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."member_guard_update"() IS 'BEFORE UPDATE on member (306). Unless the caller is the service role or has no request context: id, user_id and workspace_id never change; the owner sets other roles (owner included); an admin moves non-owners among admin/member/guest; your own role only goes down, and only an owner''s while another owner remains.';


