    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.document
     set canon_key = null
   where workspace_id = old.workspace_id
     and created_by = old.id
     and canon_key ~ '^(person|content-brief):';
  return old;
end
