CREATE OR REPLACE FUNCTION "public"."merge_contacts"("p_target" "uuid", "p_source" "uuid", "p_match_type" "text" DEFAULT 'manual'::"text", "p_score" numeric DEFAULT NULL::numeric, "p_reasons" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "text" DEFAULT 'system'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target public.contact%ROWTYPE;
  v_source public.contact%ROWTYPE;
  v_moved jsonb;
  v_emails text[];
BEGIN
  IF p_target = p_source THEN
    RAISE EXCEPTION 'Cannot merge a contact into itself';
  END IF;

  IF p_target < p_source THEN
    SELECT * INTO v_target FROM public.contact WHERE id = p_target FOR UPDATE;
    SELECT * INTO v_source FROM public.contact WHERE id = p_source FOR UPDATE;
  ELSE
    SELECT * INTO v_source FROM public.contact WHERE id = p_source FOR UPDATE;
    SELECT * INTO v_target FROM public.contact WHERE id = p_target FOR UPDATE;
  END IF;

  IF v_target.id IS NULL OR v_source.id IS NULL THEN
    RAISE EXCEPTION 'Both contacts must exist';
  END IF;
  IF v_target.workspace_id <> v_source.workspace_id THEN
    RAISE EXCEPTION 'Contacts must be in the same workspace';
  END IF;
  IF v_source.merged_into_contact_id IS NOT NULL THEN
    RAISE EXCEPTION 'Source contact % is already merged', p_source;
  END IF;
  IF v_target.merged_into_contact_id IS NOT NULL THEN
    RAISE EXCEPTION 'Target contact % is already merged', p_target;
  END IF;

  v_moved := jsonb_build_object(
    'capture_participant_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.capture_participant WHERE contact_id = p_source), '[]'::jsonb),
    'contact_interaction_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.contact_interaction WHERE contact_id = p_source), '[]'::jsonb),
    'email_thread_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.email_thread_index WHERE linked_contact_id = p_source), '[]'::jsonb),
    'voice_enrollment_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.voice_enrollment WHERE contact_id = p_source), '[]'::jsonb),
    'comment_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.comment WHERE commentable_type = 'contact' AND commentable_id = p_source), '[]'::jsonb),
    'contact_share_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.contact_share WHERE contact_id = p_source), '[]'::jsonb),
    'prospect_list_entry_ids',
      COALESCE((SELECT jsonb_agg(id) FROM public.prospect_list_entry WHERE contact_id = p_source), '[]'::jsonb)
  );

  UPDATE public.capture_participant SET contact_id = p_target WHERE contact_id = p_source;
  UPDATE public.contact_interaction SET contact_id = p_target WHERE contact_id = p_source;
  UPDATE public.email_thread_index SET linked_contact_id = p_target WHERE linked_contact_id = p_source;
  UPDATE public.voice_enrollment SET contact_id = p_target WHERE contact_id = p_source;
  UPDATE public.comment SET commentable_id = p_target
    WHERE commentable_type = 'contact' AND commentable_id = p_source;
  UPDATE public.contact_share SET contact_id = p_target WHERE contact_id = p_source;

  UPDATE public.sequence_enrollment se
  SET status = 'exited', exit_reason = 'removed', next_send_at = NULL
  WHERE se.contact_id = p_source
    AND se.status = 'active'
    AND (
      EXISTS (
        SELECT 1 FROM public.sequence_enrollment t
        WHERE t.sequence_id = se.sequence_id AND t.contact_id = p_target
      )
      OR EXISTS (
        SELECT 1 FROM public.sequence_enrollment t
        WHERE t.workspace_id = se.workspace_id
          AND t.status = 'active'
          AND (
            t.contact_id = p_target
            OR (v_target.email IS NOT NULL AND lower(t.contact_email) = lower(v_target.email))
          )
      )
    );

  UPDATE public.sequence_enrollment se
  SET contact_id = p_target
  WHERE se.contact_id = p_source
    AND NOT EXISTS (
      SELECT 1 FROM public.sequence_enrollment t
      WHERE t.sequence_id = se.sequence_id AND t.contact_id = p_target
    );

  UPDATE public.prospect_list_entry t
  SET stage            = 'dismissed',
      dismissed_reason = COALESCE(t.dismissed_reason, s.dismissed_reason, 'other'),
      dismissed_by     = COALESCE(t.dismissed_by, s.dismissed_by),
      dismissed_at     = COALESCE(t.dismissed_at, s.dismissed_at, now()),
      updated_at       = now()
  FROM public.prospect_list_entry s
  WHERE t.contact_id = p_target
    AND s.contact_id = p_source
    AND s.list_id = t.list_id
    AND s.stage = 'dismissed'
    AND t.stage <> 'dismissed';

  UPDATE public.prospect_list_entry
  SET contact_id = p_target,
      updated_at = now()
  WHERE contact_id = p_source
    AND NOT EXISTS (
      SELECT 1 FROM public.prospect_list_entry e2
      WHERE e2.list_id = prospect_list_entry.list_id
        AND e2.contact_id = p_target
    );

  DELETE FROM public.prospect_list_entry WHERE contact_id = p_source;

  v_emails := (
    SELECT COALESCE(array_agg(DISTINCT e), '{}')
    FROM unnest(
      COALESCE(v_target.secondary_emails, '{}')
        || COALESCE(v_source.secondary_emails, '{}')
        || ARRAY[v_source.email]
        || ARRAY[v_target.email]
    ) AS e
    WHERE e IS NOT NULL AND e <> '' AND e IS DISTINCT FROM v_target.email
  );

  UPDATE public.contact SET
    secondary_emails    = v_emails,
    first_name          = COALESCE(v_target.first_name, v_source.first_name),
    last_name           = COALESCE(v_target.last_name, v_source.last_name),
    phone               = COALESCE(v_target.phone, v_source.phone),
    avatar_url          = COALESCE(v_target.avatar_url, v_source.avatar_url),
    job_title           = COALESCE(v_target.job_title, v_source.job_title),
    department          = COALESCE(v_target.department, v_source.department),
    linkedin_url        = COALESCE(v_target.linkedin_url, v_source.linkedin_url),
    company_id          = COALESCE(v_target.company_id, v_source.company_id),
    member_id           = COALESCE(v_target.member_id, v_source.member_id),
    notes               = CASE
                            WHEN COALESCE(NULLIF(trim(v_source.notes), ''), '') = '' THEN v_target.notes
                            WHEN COALESCE(NULLIF(trim(v_target.notes), ''), '') = '' THEN v_source.notes
                            ELSE v_target.notes || E'\n\n' || v_source.notes
                          END,
    tags                = (
                            SELECT COALESCE(array_agg(DISTINCT t), '{}')
                            FROM unnest(COALESCE(v_target.tags, '{}') || COALESCE(v_source.tags, '{}')) AS t
                          ),
    interaction_count   = COALESCE(v_target.interaction_count, 0) + COALESCE(v_source.interaction_count, 0),
    last_interaction_at = GREATEST(v_target.last_interaction_at, v_source.last_interaction_at),
    next_followup_at    = COALESCE(v_target.next_followup_at, v_source.next_followup_at),
    updated_at          = now()
  WHERE id = p_target;

  UPDATE public.contact SET
    merged_into_contact_id = p_target,
    email                  = NULL,
    secondary_emails       = '{}',
    updated_at             = now()
  WHERE id = p_source;

  INSERT INTO public.contact_merge (
    workspace_id, target_contact_id, source_contact_id,
    source_snapshot, moved, match_type, score, reasons, performed_by
  ) VALUES (
    v_target.workspace_id, p_target, p_source,
    to_jsonb(v_source), v_moved, p_match_type, p_score, p_reasons, p_performed_by
  );

  RETURN p_target;
END;
$$;


ALTER FUNCTION "public"."merge_contacts"("p_target" "uuid", "p_source" "uuid", "p_match_type" "text", "p_score" numeric, "p_reasons" "jsonb", "p_performed_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_onboarding_progress"("p_workspace_id" "uuid", "p_patch" "jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid := public._resolve_requester(p_user_id);
  v_result jsonb;
BEGIN
  UPDATE public.member m
     SET onboarding_progress =
       (coalesce(m.onboarding_progress, '{}'::jsonb) || p_patch)
       || (
         CASE
           WHEN jsonb_typeof(p_patch -> 'tutorial') = 'object' THEN
             jsonb_build_object(
               'tutorial',
               coalesce(m.onboarding_progress -> 'tutorial', '{}'::jsonb)
                 || (p_patch -> 'tutorial')
             )
           ELSE '{}'::jsonb
         END
       )
   WHERE m.user_id = v_uid
     AND m.workspace_id = p_workspace_id
  RETURNING m.onboarding_progress INTO v_result;
  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."merge_onboarding_progress"("p_workspace_id" "uuid", "p_patch" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_workspace"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid := gen_random_uuid();
  v_t0 timestamptz := clock_timestamp();
  v_src public.workspace%ROWTYPE;
  v_dst public.workspace%ROWTYPE;
  v_plan jsonb; v_busy jsonb; v_drift text; v_before jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_ms int;
BEGIN
  -- the merge setting: transaction-local, read by the guard exemptions
  PERFORM set_config('dial8.workspace_merge', v_id::text, true);

  PERFORM public._wsmerge_gate(p_source, p_destination, p_actor);

  -- both workspace rows locked, lowest id first (serialises with chat
  -- admission's FOR NO KEY UPDATE and with a concurrent merge either way)
  IF p_source < p_destination THEN
    SELECT * INTO v_src FROM public.workspace WHERE id = p_source FOR UPDATE;
    SELECT * INTO v_dst FROM public.workspace WHERE id = p_destination FOR UPDATE;
  ELSE
    SELECT * INTO v_dst FROM public.workspace WHERE id = p_destination FOR UPDATE;
    SELECT * INTO v_src FROM public.workspace WHERE id = p_source FOR UPDATE;
  END IF;
  IF v_src.id IS NULL OR v_dst.id IS NULL THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;

  v_plan := public._wsmerge_plan(p_source, p_destination, COALESCE(p_plan, '{}'::jsonb));

  -- refusals: a busy source, drift on either side
  v_busy := public._wsmerge_busy(p_source);
  IF jsonb_array_length(v_busy->'live_captures') > 0
     OR (v_busy->>'agent_runs')::int > 0 OR (v_busy->>'flow_runs')::int > 0 OR (v_busy->>'tracked_jobs')::int > 0 THEN
    RAISE EXCEPTION 'the source workspace is busy: %', v_busy::text USING ERRCODE = 'P0007';
  END IF;
  SELECT string_agg(check_name || '=' || violations, ', ') INTO v_drift FROM public.workspace_integrity_sweep(p_source);
  IF v_drift IS NOT NULL THEN
    RAISE EXCEPTION 'the source workspace fails the integrity sweep: %', v_drift USING ERRCODE = 'P0009';
  END IF;
  SELECT string_agg(check_name || '=' || violations, ', ') INTO v_drift FROM public.workspace_integrity_sweep(p_destination);
  IF v_drift IS NOT NULL THEN
    RAISE EXCEPTION 'the destination workspace fails the integrity sweep: %', v_drift USING ERRCODE = 'P0009';
  END IF;

  v_before := public._wsmerge_counts(p_source);
  PERFORM public._wsmerge_build_maps(p_source, p_destination, v_plan);

  v_counts := v_counts || public._wsmerge_members(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_system_teammates(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_teams_begin(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_labels(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_integrations(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_environments(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_default_projects(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_actions(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_documents(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_captures(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_contacts(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_companies(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_mail(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_agents_flows(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_knowledge(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_chat(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_views(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_singletons(p_source, p_destination);
  v_counts := v_counts || public._wsmerge_teams_finish(p_source, p_destination);
  v_counts := v_counts || jsonb_build_object('restamped', public._wsmerge_generic_restamp(p_source, p_destination));
  v_counts := v_counts || public._wsmerge_pointers(p_source, p_destination);

  PERFORM public._wsmerge_assert(p_source, p_destination);

  v_ms := (extract(epoch FROM clock_timestamp() - v_t0) * 1000)::int;
  INSERT INTO public.workspace_merge (
    id, source_workspace_id, source_name, source_slug, source_settings, source_created_at,
    destination_workspace_id, actor_user_id, plan, counts, snapshot, started_at, finished_at, duration_ms
  ) VALUES (
    v_id, v_src.id, v_src.name, v_src.slug, COALESCE(v_src.settings, '{}'::jsonb), v_src.created_at,
    p_destination, p_actor, v_plan - 'snapshot', v_counts || jsonb_build_object('rows_before', v_before),
    v_plan->'snapshot', v_t0, clock_timestamp(), v_ms
  );

  -- the empty shell; nothing cascades from it any more
  DELETE FROM public.workspace WHERE id = p_source;

  RETURN jsonb_build_object(
    'merge_id', v_id,
    'source', jsonb_build_object('id', v_src.id, 'name', v_src.name, 'slug', v_src.slug),
    'destination', jsonb_build_object('id', v_dst.id, 'name', v_dst.name, 'slug', v_dst.slug),
    'counts', v_counts,
    'rows_before', v_before,
    'duration_ms', v_ms
  );
END;
$$;


ALTER FUNCTION "public"."merge_workspace"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_workspace_enqueue"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  PERFORM public._wsmerge_gate(p_source, p_destination, p_actor);
  PERFORM pg_advisory_xact_lock(hashtext('workspace_merge_runner'));

  UPDATE public.workspace_merge_job
  SET status = 'failed', finished_at = now(),
      error_code = CASE WHEN attempts > 0 THEN 'P0012' ELSE 'P0011' END,
      error_message = CASE WHEN attempts > 0 THEN 'the merge was interrupted before it finished' ELSE 'the merge job expired before it ran' END
  WHERE source_workspace_id = p_source AND status = 'queued' AND created_at < now() - public._wsmerge_job_expiry();

  IF EXISTS (SELECT 1 FROM public.workspace_merge_job WHERE source_workspace_id = p_source AND status = 'queued') THEN
    RAISE EXCEPTION 'a merge of this workspace is already waiting to run' USING ERRCODE = 'P0010';
  END IF;

  INSERT INTO public.workspace_merge_job (source_workspace_id, destination_workspace_id, actor_user_id, plan)
  VALUES (p_source, p_destination, p_actor, COALESCE(p_plan, '{}'::jsonb))
  RETURNING id INTO v_id;

  BEGIN
    PERFORM cron.schedule('workspace-merge-runner', '2 seconds', public._wsmerge_runner_command());
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'the merge runner could not be started: %', SQLERRM USING ERRCODE = 'P0013';
  END;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."merge_workspace_enqueue"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_workspace_preflight"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_src public.workspace%ROWTYPE;
  v_dst public.workspace%ROWTYPE;
  v_plan jsonb;
  v_busy jsonb;
  v_drift_src jsonb; v_drift_dst jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_people jsonb; v_teams jsonb := '[]'::jsonb; v_labels jsonb; v_integrations jsonb; v_collisions jsonb;
  tm record;
  v_reprefixed bigint; v_renumbered bigint; v_states jsonb; v_cycle_conflict boolean;
BEGIN
  PERFORM public._wsmerge_gate(p_source, p_destination, p_actor);
  SELECT * INTO v_src FROM public.workspace WHERE id = p_source;
  SELECT * INTO v_dst FROM public.workspace WHERE id = p_destination;

  v_plan := public._wsmerge_plan(p_source, p_destination, COALESCE(p_plan, '{}'::jsonb));
  PERFORM public._wsmerge_build_maps(p_source, p_destination, v_plan);

  -- blockers: the source is busy, or either side fails the sweep
  v_busy := public._wsmerge_busy(p_source);
  IF jsonb_array_length(v_busy->'live_captures') > 0
     OR (v_busy->>'agent_runs')::int > 0 OR (v_busy->>'flow_runs')::int > 0 OR (v_busy->>'tracked_jobs')::int > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'source_busy', 'detail', v_busy);
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('check', check_name, 'violations', violations)), '[]'::jsonb)
    INTO v_drift_src FROM public.workspace_integrity_sweep(p_source);
  SELECT COALESCE(jsonb_agg(jsonb_build_object('check', check_name, 'violations', violations)), '[]'::jsonb)
    INTO v_drift_dst FROM public.workspace_integrity_sweep(p_destination);
  IF jsonb_array_length(v_drift_src) > 0 OR jsonb_array_length(v_drift_dst) > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'drift', 'source', v_drift_src, 'destination', v_drift_dst);
  END IF;

  -- people
  v_people := jsonb_build_object(
    'joining', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'member_id', m.id, 'user_id', m.user_id, 'display_name', m.display_name,
               'role', CASE WHEN m.role = 'owner' THEN 'admin' ELSE m.role END) ORDER BY m.created_at), '[]'::jsonb)
      FROM public.member m
      WHERE m.workspace_id = p_source AND NOT EXISTS (SELECT 1 FROM pg_temp._wsmerge_members x WHERE x.src = m.id)),
    'in_both', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'user_id', x.user_id, 'display_name', d.display_name,
               'source_role', s.role, 'destination_role', d.role,
               'role_after', CASE WHEN d.role = 'owner' THEN 'owner'
                                  WHEN s.role = 'owner' THEN 'admin'
                                  WHEN public._wsmerge_role_rank(s.role) > public._wsmerge_role_rank(d.role) THEN s.role
                                  ELSE d.role END) ORDER BY d.created_at), '[]'::jsonb)
      FROM pg_temp._wsmerge_members x
      JOIN public.member s ON s.id = x.src
      JOIN public.member d ON d.id = x.dst),
    'destination_members', (SELECT count(*) FROM public.member WHERE workspace_id = p_destination),
    'invites_moving', (
      SELECT count(*) FROM public.invite i
      WHERE i.workspace_id = p_source AND i.accepted_at IS NULL AND i.expires_at > now()
        AND NOT EXISTS (SELECT 1 FROM public.member dm JOIN auth.users u ON u.id = dm.user_id
                        WHERE dm.workspace_id = p_destination AND lower(u.email) = lower(i.email))
        AND NOT EXISTS (SELECT 1 FROM public.invite di WHERE di.workspace_id = p_destination AND di.accepted_at IS NULL
                        AND di.expires_at > now() AND lower(di.email) = lower(i.email))),
    'invites_dropped', (
      SELECT count(*) FROM public.invite i
      WHERE i.workspace_id = p_source AND (
        i.accepted_at IS NOT NULL OR i.expires_at <= now()
        OR EXISTS (SELECT 1 FROM public.member dm JOIN auth.users u ON u.id = dm.user_id
                   WHERE dm.workspace_id = p_destination AND lower(u.email) = lower(i.email))
        OR EXISTS (SELECT 1 FROM public.invite di WHERE di.workspace_id = p_destination AND di.accepted_at IS NULL
                   AND di.expires_at > now() AND lower(di.email) = lower(i.email))))
  );

  -- teams: the plan's rows plus what each choice does to identifiers,
  -- states and cycles
  FOR tm IN SELECT * FROM pg_temp._wsmerge_teams ORDER BY ord LOOP
    IF tm.mode = 'own' THEN
      SELECT count(*) FILTER (WHERE left(a.identifier, length(tm.old_prefix) + 1) = tm.old_prefix || '-' AND tm.new_prefix <> tm.old_prefix),
             count(*) FILTER (WHERE EXISTS (
               SELECT 1 FROM public.actions d WHERE d.workspace_id = p_destination
               AND d.identifier = CASE WHEN tm.new_prefix <> tm.old_prefix AND left(a.identifier, length(tm.old_prefix) + 1) = tm.old_prefix || '-'
                                       THEN tm.new_prefix || substring(a.identifier FROM length(tm.old_prefix) + 1)
                                       ELSE a.identifier END))
      INTO v_reprefixed, v_renumbered
      FROM public.actions a WHERE a.workspace_id = p_source AND a.team_id = tm.src;
      v_states := '[]'::jsonb;
      v_cycle_conflict := false;
    ELSE
      v_reprefixed := 0;
      SELECT count(*) INTO v_renumbered
      FROM public.actions a WHERE a.workspace_id = p_source AND a.team_id = tm.src
        AND EXISTS (SELECT 1 FROM public.actions d WHERE d.workspace_id = p_destination AND d.identifier = a.identifier);
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'from', s.name, 'to', d.name,
               'actions', (SELECT count(*) FROM public.actions a WHERE a.status_id = s.id AND a.workspace_id = p_source)
             ) ORDER BY s.sort_order), '[]'::jsonb)
      INTO v_states
      FROM pg_temp._wsmerge_states sm
      JOIN public.workflow_state s ON s.id = sm.src
      LEFT JOIN public.workflow_state d ON d.id = sm.dst
      WHERE s.team_id = tm.src AND (d.id IS NULL OR lower(d.name) <> lower(s.name));
      v_cycle_conflict := EXISTS (SELECT 1 FROM public.cycle c WHERE c.team_id = tm.src AND c.status = 'active')
                      AND EXISTS (SELECT 1 FROM public.cycle c WHERE c.team_id = tm.dst AND c.status = 'active');
    END IF;

    v_teams := v_teams || (
      (SELECT e.value FROM jsonb_array_elements(v_plan->'teams') e WHERE (e.value->>'source_team_id')::uuid = tm.src)
      || jsonb_build_object(
           'identifiers', jsonb_build_object('reprefixed', v_reprefixed, 'renumbered', v_renumbered),
           'states_remapped', v_states,
           'active_cycle_conflict', v_cycle_conflict,
           'destination_team', CASE WHEN tm.mode = 'fold'
             THEN (SELECT jsonb_build_object('id', d.id, 'name', d.name, 'prefix', d.issue_prefix) FROM public.team d WHERE d.id = tm.dst)
             ELSE NULL END));
  END LOOP;

  v_labels := jsonb_build_object(
    'matched', (SELECT count(*) FROM pg_temp._wsmerge_labels),
    'created', (SELECT count(*) FROM public.label l WHERE l.workspace_id = p_source
                AND NOT EXISTS (SELECT 1 FROM pg_temp._wsmerge_labels x WHERE x.src = l.id)));

  v_integrations := jsonb_build_object(
    'tasks', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'provider', p.provider,
        'source', EXISTS (SELECT 1 FROM public.task_sync_state s WHERE s.workspace_id = p_source AND s.provider = p.provider),
        'destination', EXISTS (SELECT 1 FROM public.task_sync_state d WHERE d.workspace_id = p_destination AND d.provider = p.provider),
        'outcome', CASE WHEN EXISTS (SELECT 1 FROM pg_temp._wsmerge_shared_providers sp WHERE sp.kind = 'tasks' AND sp.provider = p.provider)
                        THEN 'destination_wins' ELSE 'moves' END,
        'links_severed', CASE WHEN EXISTS (SELECT 1 FROM pg_temp._wsmerge_shared_providers sp WHERE sp.kind = 'tasks' AND sp.provider = p.provider)
                              THEN (SELECT count(*) FROM public.action_external_task x WHERE x.workspace_id = p_source AND x.provider = p.provider)
                              ELSE 0 END) ORDER BY p.provider), '[]'::jsonb)
      FROM (SELECT provider FROM public.task_sync_state WHERE workspace_id IN (p_source, p_destination) GROUP BY provider) p),
    'crm', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'provider', p.provider,
        'source', EXISTS (SELECT 1 FROM public.crm_sync_state s WHERE s.workspace_id = p_source AND s.provider = p.provider),
        'destination', EXISTS (SELECT 1 FROM public.crm_sync_state d WHERE d.workspace_id = p_destination AND d.provider = p.provider),
        'outcome', CASE WHEN EXISTS (SELECT 1 FROM pg_temp._wsmerge_shared_providers sp WHERE sp.kind = 'crm' AND sp.provider = p.provider)
                        THEN 'destination_wins' ELSE 'moves' END,
        'provider_ids_cleared', CASE WHEN EXISTS (SELECT 1 FROM pg_temp._wsmerge_shared_providers sp WHERE sp.kind = 'crm' AND sp.provider = p.provider)
                                     THEN (SELECT count(*) FROM public.contact c WHERE c.workspace_id = p_source AND c.source_provider = p.provider AND c.provider_contact_id IS NOT NULL)
                                        + (SELECT count(*) FROM public.company c WHERE c.workspace_id = p_source AND c.source_provider = p.provider AND c.provider_company_id IS NOT NULL)
                                     ELSE 0 END) ORDER BY p.provider), '[]'::jsonb)
      FROM (SELECT provider FROM public.crm_sync_state WHERE workspace_id IN (p_source, p_destination) GROUP BY provider) p),
    'connected_accounts', (SELECT count(*) FROM public.connected_account a WHERE a.workspace_id = p_source),
    'account_links', (SELECT count(*) FROM public.connected_account_workspace j WHERE j.workspace_id = p_source),
    'mcp_servers', (SELECT count(*) FROM public.connected_mcp_server s WHERE s.workspace_id = p_source),
    'cloud_environments', (SELECT count(*) FROM public.environment e WHERE e.workspace_id = p_source AND e.kind = 'cloud'),
    'default_cloud_environment', jsonb_build_object(
      'outcome', CASE WHEN v_src.default_cloud_environment_id IS NULL THEN 'none'
                      WHEN v_dst.default_cloud_environment_id IS NULL THEN 'source_adopted'
                      ELSE 'destination_keeps' END,
      'source', (SELECT jsonb_build_object('name', e.name, 'network_access', e.network_access) FROM public.environment e WHERE e.id = v_src.default_cloud_environment_id),
      'destination', (SELECT jsonb_build_object('name', e.name, 'network_access', e.network_access) FROM public.environment e WHERE e.id = v_dst.default_cloud_environment_id),
      'source_loops', (SELECT count(*) FROM public.flow f WHERE f.workspace_id = p_source AND f.actions @> '[{"type": "run_agent"}]'::jsonb),
      'projects_pinned', CASE WHEN v_src.default_cloud_environment_id IS NULL THEN 0
                              ELSE (SELECT count(*) FROM public.projects p WHERE p.workspace_id = p_source AND p.environment_id IS NULL
                                    AND NOT EXISTS (SELECT 1 FROM pg_temp._wsmerge_projects m WHERE m.src = p.id)) END),
    'github_prs', (SELECT count(*) FROM public.action_github_pr x WHERE x.workspace_id = p_source));

  v_collisions := jsonb_build_object(
    'contacts_folded', (SELECT count(*) FROM pg_temp._wsmerge_contacts),
    'companies_folded', (SELECT count(*) FROM pg_temp._wsmerge_companies),
    'workspace_company_demoted', EXISTS (
      SELECT 1 FROM public.company s WHERE s.workspace_id = p_source AND s.is_workspace_company
        AND NOT EXISTS (SELECT 1 FROM pg_temp._wsmerge_companies x WHERE x.src = s.id)
        AND EXISTS (SELECT 1 FROM public.company d WHERE d.workspace_id = p_destination AND d.is_workspace_company)),
    'documents_canon_demoted', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', s.id, 'title', s.title, 'canon_key', s.canon_key) ORDER BY s.title), '[]'::jsonb)
      FROM public.document s
      WHERE s.workspace_id = p_source AND s.canon_key IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.document d WHERE d.workspace_id = p_destination AND d.canon_key = s.canon_key
          AND (s.canon_key !~ '^(person|content-brief):'
               OR d.created_by IS NOT DISTINCT FROM COALESCE((SELECT x.dst FROM pg_temp._wsmerge_members x WHERE x.src = s.created_by), s.created_by)))),
    'documents_reslugged', (SELECT count(*) FROM public.document s WHERE s.workspace_id = p_source AND s.slug IS NOT NULL
                            AND EXISTS (SELECT 1 FROM public.document d WHERE d.workspace_id = p_destination AND d.slug = s.slug)),
    'views_reslugged', (SELECT count(*) FROM public.view s WHERE s.workspace_id = p_source AND s.slug IS NOT NULL
                        AND EXISTS (SELECT 1 FROM public.view d WHERE d.workspace_id = p_destination AND d.slug = s.slug)),
    'recipes_reslugged', (SELECT count(*) FROM public.recipe s WHERE s.workspace_id = p_source AND s.slug IS NOT NULL
                          AND EXISTS (SELECT 1 FROM public.recipe d WHERE d.workspace_id = p_destination AND d.slug = s.slug)),
    'packages_reslugged', (SELECT count(*) FROM public.knowledge_package s WHERE s.workspace_id = p_source
                           AND EXISTS (SELECT 1 FROM public.knowledge_package d WHERE d.workspace_id = p_destination AND d.slug = s.slug)),
    'prospect_lists_renamed', (SELECT count(*) FROM public.prospect_list s WHERE s.workspace_id = p_source
                               AND EXISTS (SELECT 1 FROM public.prospect_list d WHERE d.workspace_id = p_destination AND lower(d.name) = lower(s.name))),
    'home_threads_demoted', (SELECT count(*) FROM public.chat_conversations s WHERE s.workspace_id = p_source AND s.is_home
                             AND EXISTS (SELECT 1 FROM public.chat_conversations d WHERE d.workspace_id = p_destination AND d.is_home AND d.user_id = s.user_id)),
    'teammate_threads_demoted', (SELECT count(*) FROM public.chat_conversations s JOIN pg_temp._wsmerge_teammates t ON t.src = s.ai_team_member_id
                                 WHERE s.workspace_id = p_source
                                 AND EXISTS (SELECT 1 FROM public.chat_conversations d WHERE d.user_id = s.user_id AND d.ai_team_member_id = t.dst)),
    'system_teammates_folded', (SELECT count(*) FROM pg_temp._wsmerge_teammates),
    'seeded_flows_dropped', (SELECT count(*) FROM pg_temp._wsmerge_flows),
    'default_projects_folded', (SELECT count(*) FROM pg_temp._wsmerge_projects),
    'thread_copies_folded', (SELECT count(*) FROM public.email_thread_index s WHERE s.workspace_id = p_source
                             AND EXISTS (SELECT 1 FROM public.email_thread_index d WHERE d.workspace_id = p_destination
                                         AND COALESCE(d.account_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(s.account_id, '00000000-0000-0000-0000-000000000000'::uuid)
                                         AND d.provider_thread_id = s.provider_thread_id)),
    'account_links_deduped', (SELECT count(*) FROM public.connected_account_workspace s WHERE s.workspace_id = p_source
                              AND EXISTS (SELECT 1 FROM public.connected_account_workspace d WHERE d.workspace_id = p_destination AND d.account_id = s.account_id)),
    'sequence_enrollments_exited', (
      SELECT count(*) FROM public.sequence_enrollment s WHERE s.workspace_id = p_source AND s.status = 'active'
        AND EXISTS (SELECT 1 FROM public.sequence_enrollment d WHERE d.workspace_id = p_destination AND d.status = 'active'
                    AND (d.contact_id = COALESCE((SELECT c.dst FROM pg_temp._wsmerge_contacts c WHERE c.src = s.contact_id), s.contact_id)
                         OR lower(d.contact_email) = lower(s.contact_email)))),
    'singletons_dropped', jsonb_build_object(
      'mail_review_activity', (SELECT count(*) FROM public.mail_review_activity s WHERE s.workspace_id = p_source
                               AND EXISTS (SELECT 1 FROM public.mail_review_activity d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id)),
      'meeting_goal', (SELECT count(*) FROM public.meeting_goal s WHERE s.workspace_id = p_source
                       AND EXISTS (SELECT 1 FROM public.meeting_goal d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id
                                   AND d.calendar_event_id = s.calendar_event_id AND d.starts_at = s.starts_at)),
      'agent_log', (SELECT count(*) FROM public.agent_log s WHERE s.workspace_id = p_source
                    AND EXISTS (SELECT 1 FROM public.agent_log d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id AND d.dedupe_key = s.dedupe_key)),
      'agent_event', (SELECT count(*) FROM public.agent_event s WHERE s.workspace_id = p_source
                      AND EXISTS (SELECT 1 FROM public.agent_event d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id AND d.dedupe_key = s.dedupe_key)),
      'eval_candidate', (SELECT count(*) FROM public.eval_candidate s WHERE s.workspace_id = p_source
                         AND EXISTS (SELECT 1 FROM public.eval_candidate d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id AND d.dedupe_key = s.dedupe_key)),
      'reminders', (SELECT count(*) FROM public.reminder s WHERE s.workspace_id = p_source AND s.delivered_at IS NULL
                    AND EXISTS (SELECT 1 FROM public.reminder d WHERE d.workspace_id = p_destination AND d.delivered_at IS NULL
                                AND d.user_id = s.user_id AND d.entity_type = s.entity_type AND d.entity_id = s.entity_id)),
      'environment_default', (SELECT count(*) FROM public.environment_default s WHERE s.workspace_id = p_source
                              AND EXISTS (SELECT 1 FROM public.environment_default d WHERE d.workspace_id = p_destination AND d.user_id = s.user_id
                                          AND d.project_id IS NOT DISTINCT FROM COALESCE((SELECT m.dst FROM pg_temp._wsmerge_projects m WHERE m.src = s.project_id), s.project_id)))));

  RETURN jsonb_build_object(
    'ok', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'source', jsonb_build_object('id', v_src.id, 'name', v_src.name, 'slug', v_src.slug, 'created_at', v_src.created_at),
    'destination', jsonb_build_object('id', v_dst.id, 'name', v_dst.name, 'slug', v_dst.slug),
    'busy', v_busy,
    'drift', jsonb_build_object('source', v_drift_src, 'destination', v_drift_dst),
    'people', v_people,
    'teams', v_teams,
    'labels', v_labels,
    'integrations', v_integrations,
    'collisions', v_collisions,
    'counts', public._wsmerge_counts(p_source),
    'plan', v_plan
  );
END;
$$;


ALTER FUNCTION "public"."merge_workspace_preflight"("p_source" "uuid", "p_destination" "uuid", "p_actor" "uuid", "p_plan" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_actions"("p_action_ids" "uuid"[], "p_destination_workspace_id" "uuid", "p_destination_team_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_ids uuid[];
  v_source uuid;
  v_found int;
  v_owns_all boolean;
  v_dest_team uuid;
  v_dest_default_status uuid;
  v_core jsonb;
  v_links jsonb;
  v_residue jsonb;
  v_moving jsonb;
  v_counts jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT x), '{}') INTO v_ids
  FROM unnest(COALESCE(p_action_ids, '{}')) x;

  IF cardinality(v_ids) = 0 THEN
    RAISE EXCEPTION 'no action ids supplied' USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_ids) > 500 THEN
    RAISE EXCEPTION 'too many action ids' USING ERRCODE = '22023';
  END IF;

  -- Lock the rows and pin the single source workspace. Every id must exist
  -- and share it — SECURITY DEFINER + a raw id array would otherwise let a
  -- member of workspaces A and B drag workspace C's rows along.
  SELECT min(workspace_id::text)::uuid, count(*)
  INTO v_source, v_found
  FROM (
    SELECT workspace_id
    FROM public.actions
    WHERE id = ANY(v_ids)
    FOR UPDATE
  ) locked;

  IF v_found = 0 THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_found <> cardinality(v_ids)
     OR EXISTS (
       SELECT 1 FROM public.actions
       WHERE id = ANY(v_ids) AND workspace_id <> v_source
     ) THEN
    RAISE EXCEPTION 'action ids must all exist in one workspace'
      USING ERRCODE = 'P0004';
  END IF;

  -- Plain members may move only actions they created. IS NOT DISTINCT FROM:
  -- bool_and skips NULL inputs, so a NULL user_id row would otherwise slip
  -- past the ownership gate instead of failing it closed.
  SELECT bool_and(user_id IS NOT DISTINCT FROM v_user_id) INTO v_owns_all
  FROM public.actions
  WHERE id = ANY(v_ids);

  PERFORM public._wsmove_gate(
    v_user_id, v_source, p_destination_workspace_id, COALESCE(v_owns_all, false));

  SELECT team_id, default_status_id
  INTO v_dest_team, v_dest_default_status
  FROM public._wsmove_dest_team(p_destination_workspace_id, p_destination_team_id);

  v_core := public._wsmove_actions_core(
    v_ids, v_source, p_destination_workspace_id,
    v_dest_team, v_dest_default_status,
    false,  -- standalone moves leave the project behind
    true    -- the capture is not moving
  );

  SELECT COALESCE(jsonb_agg(jsonb_build_object('t', 'action', 'i', x)), '[]'::jsonb)
  INTO v_moving
  FROM unnest(v_ids) x;
  v_moving := v_moving || COALESCE(
    (SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', a))
     FROM jsonb_array_elements_text(v_core->'attachment_ids') a),
    '[]'::jsonb);

  v_links := public._wsmove_entity_links(v_source, p_destination_workspace_id, v_moving);
  v_residue := public._wsmove_residue(v_source, p_destination_workspace_id, v_moving);

  v_counts := jsonb_build_object(
    'moved_actions', v_core->'moved',
    'identifier_map', v_core->'identifier_map',
    'renumbered', v_core->'renumbered',
    'assignees_translated', v_core->'assignees_translated',
    'assignees_dropped', v_core->'assignees_dropped',
    'labels_remapped', v_core->'labels'->'remapped',
    'labels_removed', v_core->'labels'->'deleted',
    'external_tasks_severed', v_core->'external_tasks_severed',
    'agent_runs_removed', v_core->'agent_runs_removed',
    'comments_translated', v_core->'comments_translated',
    'attachments_moved', jsonb_array_length(v_core->'attachment_ids'),
    'links_moved', v_links->'moved',
    'links_severed', v_links->'severed'
  ) || v_residue;

  INSERT INTO public.workspace_move_log
    (entity_type, entity_id, source_workspace_id, destination_workspace_id, moved_by, counts)
  SELECT 'action', x, v_source, p_destination_workspace_id, v_user_id, v_counts
  FROM unnest(v_ids) x;

  RETURN jsonb_build_object(
    'action_ids', (SELECT jsonb_agg(x) FROM unnest(v_ids) x),
    'source_workspace_id', v_source,
    'destination_workspace_id', p_destination_workspace_id,
    'destination_team_id', v_dest_team,
    'counts', v_counts
  );
END;
$$;


ALTER FUNCTION "public"."move_actions"("p_action_ids" "uuid"[], "p_destination_workspace_id" "uuid", "p_destination_team_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_actions"("p_action_ids" "uuid"[], "p_destination_workspace_id" "uuid", "p_destination_team_id" "uuid") IS 'Move up to 500 actions (one source workspace) to another workspace. Identifiers are preserved when free in the destination and reissued from a watermark only on collision (old handle kept in previous_identifier); workflow state matches name -> category -> default; assignees translate by user identity; labels remap by name; Jira/Linear/Asana links and PR links are severed (remote URLs appended to actions.links); agent runs are deleted; action-parented attachments follow.';


CREATE OR REPLACE FUNCTION "public"."move_capture"("p_capture_id" "uuid", "p_destination_workspace_id" "uuid", "p_confirmed_action_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_move_claims" boolean DEFAULT true, "p_move_contacts" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source_workspace_id UUID;
  v_user_id UUID := auth.uid();
  v_owns boolean;
  v_visibility text;
  v_confirmed_ids UUID[] := COALESCE(p_confirmed_action_ids, '{}');
  v_suggested_action_ids UUID[] := '{}';
  v_moved_action_ids UUID[] := '{}';
  v_attachment_ids UUID[] := '{}';
  v_unlinked_actions INT := 0;
  v_moved_decisions INT := 0;
  v_moved_proposed_changes INT := 0;
  v_copied_contacts INT := 0;
  v_shares_deactivated INT := 0;
  v_threads_unlinked INT := 0;
  v_comments_translated INT := 0;
  v_dest_team_id UUID;
  v_dest_default_status_id UUID;
  v_core jsonb;
  v_claims jsonb := jsonb_build_object('moved', 0, 'left', 0, 'moved_ids', '[]'::jsonb);
  v_labels jsonb;
  v_links jsonb;
  v_residue jsonb;
  v_moving jsonb;
  v_counts jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Lock the capture row and read its source workspace + ownership
  SELECT workspace_id, (user_id = v_user_id), visibility
  INTO v_source_workspace_id, v_owns, v_visibility
  FROM public.captures
  WHERE id = p_capture_id
  FOR UPDATE;

  IF v_source_workspace_id IS NULL THEN
    RAISE EXCEPTION 'capture not found' USING ERRCODE = 'P0002';
  END IF;

  -- 223: a private capture is only ever the creator's to relocate. The role
  -- gate below would let a workspace admin move it, which would republish it
  -- into a workspace where it reads as 'workspace'.
  IF v_visibility = 'private' AND NOT COALESCE(v_owns, false) THEN
    RAISE EXCEPTION 'capture not found' USING ERRCODE = 'P0002';
  END IF;

  -- v3 adds the role gate: plain members may move only their own captures;
  -- guests and non-members are refused (non-members as 'not found').
  PERFORM public._wsmove_gate(
    v_user_id, v_source_workspace_id, p_destination_workspace_id, COALESCE(v_owns, false));

  -- Every requested confirmed-action id must be a confirmed action extracted
  -- from THIS capture, still living in the source workspace (v2 contract).
  IF EXISTS (
    SELECT 1 FROM unnest(v_confirmed_ids) AS req(id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.actions a
      WHERE a.id = req.id
        AND a.source_capture_id = p_capture_id
        AND a.confirmation = 'confirmed'
        AND a.workspace_id = v_source_workspace_id
    )
  ) THEN
    RAISE EXCEPTION 'confirmed_action_ids contains an id that is not a confirmed action of this capture'
      USING ERRCODE = 'P0004';
  END IF;

  SELECT team_id, default_status_id
  INTO v_dest_team_id, v_dest_default_status_id
  FROM public._wsmove_dest_team(p_destination_workspace_id, NULL);

  -- Collect the id sets everything below works from.
  SELECT COALESCE(array_agg(id), '{}') INTO v_suggested_action_ids
  FROM public.actions
  WHERE source_capture_id = p_capture_id
    AND confirmation = 'suggested'
    AND workspace_id = v_source_workspace_id;

  v_moved_action_ids := v_suggested_action_ids || v_confirmed_ids;

  SELECT COALESCE(array_agg(id), '{}') INTO v_attachment_ids
  FROM public.attachments
  WHERE note_id = p_capture_id;

  -- ── confirmed actions the caller chose to LEAVE BEHIND: unlink only ──
  UPDATE public.actions
  SET source_capture_id = NULL
  WHERE source_capture_id = p_capture_id
    AND confirmation = 'confirmed'
    AND NOT (id = ANY(v_confirmed_ids));

  GET DIAGNOSTICS v_unlinked_actions = ROW_COUNT;

  -- ── attention cards for this capture's proposals die with the source
  --    context (member-scoped rows can't follow) ──
  DELETE FROM public.attention_item ai
  USING public.proposed_change pc
  WHERE ai.proposal_id = pc.id
    AND pc.capture_id = p_capture_id
    AND ai.workspace_id = v_source_workspace_id;

  -- ── the capture subtree ──
  UPDATE public.captures
  SET workspace_id = p_destination_workspace_id,
      project_id = NULL,
      team_id = NULL
  WHERE id = p_capture_id;

  UPDATE public.capture_chunks
  SET workspace_id = p_destination_workspace_id,
      project_id = NULL
  WHERE capture_id = p_capture_id;

  -- v3: reference rows + the extraction ledger carry workspace ids too
  UPDATE public.capture_references
  SET workspace_id = p_destination_workspace_id,
      project_id = NULL
  WHERE capture_id = p_capture_id;

  UPDATE public.extraction_pass
  SET workspace_id = p_destination_workspace_id
  WHERE capture_id = p_capture_id;

  -- v3: the capture's AI thread is UNLINKED, not moved. Re-stamping would
  -- strand threads the mover doesn't own (personal RLS + foreign workspace
  -- filter) and let claim extraction replay pre-move source content into
  -- destination-visible claims. Severing frees the unique capture index so
  -- the destination can mint a fresh thread.
  WITH unlinked AS (
    UPDATE public.chat_conversations
    SET capture_id = NULL
    WHERE capture_id = p_capture_id
    RETURNING 1
  )
  SELECT count(*) INTO v_threads_unlinked FROM unlinked;

  -- v3: labels remap by name instead of vanishing
  v_labels := public._wsmove_remap_labels(
    'capture_label', 'capture_id', ARRAY[p_capture_id],
    v_source_workspace_id, p_destination_workspace_id);

  -- v3: comment authors translate (see _wsmove_comments)
  v_comments_translated := public._wsmove_comments(
    'capture', ARRAY[p_capture_id], v_source_workspace_id, p_destination_workspace_id);

  -- capture-parented attachments (storage authz follows the row); the
  -- capture's project stays behind, so the attachments' project link does too
  UPDATE public.attachments
  SET workspace_id = p_destination_workspace_id,
      project_id = NULL
  WHERE note_id = p_capture_id;

  UPDATE public.attachment_chunks
  SET workspace_id = p_destination_workspace_id,
      project_id = NULL
  WHERE attachment_id = ANY(v_attachment_ids);

  -- staged proposals follow; their workspace-scoped fields reset
  UPDATE public.proposed_change
  SET workspace_id = p_destination_workspace_id,
      assignee_member_id = NULL,
      assignee_contact_id = NULL,
      team_id = NULL,
      project_id = NULL,
      labels = ARRAY[]::text[]
  WHERE capture_id = p_capture_id;

  GET DIAGNOSTICS v_moved_proposed_changes = ROW_COUNT;

  -- ── extracted actions: all suggestions + the selected confirmed ids ──
  v_core := public._wsmove_actions_core(
    v_moved_action_ids, v_source_workspace_id, p_destination_workspace_id,
    v_dest_team_id, v_dest_default_status_id,
    false,  -- their project stays behind
    false   -- the capture moves WITH them: keep source_capture_id
  );

  -- ── decisions follow by construction; suggested ones let go of the
  --    project, and v3 translates the decider ──
  UPDATE public.decision
  SET project_id = NULL
  WHERE capture_id = p_capture_id
    AND confirmation = 'suggested';

  UPDATE public.decision d
  SET decided_by = public._wsmove_member_in(d.decided_by, p_destination_workspace_id)
  WHERE d.capture_id = p_capture_id
    AND d.decided_by IS NOT NULL;

  SELECT count(*) INTO v_moved_decisions
  FROM public.decision
  WHERE capture_id = p_capture_id;

  -- ── public links die in place (v3): share + share_comment stay in the
  --    SOURCE workspace, deactivated ──
  WITH deactivated AS (
    UPDATE public.share
    SET is_active = false
    WHERE shareable_type = 'capture'
      AND shareable_id = p_capture_id
      AND workspace_id = v_source_workspace_id
      AND is_active
    RETURNING 1
  )
  SELECT count(*) INTO v_shares_deactivated FROM deactivated;

  -- ── knowledge claims (sole-sourced by this capture/its attachments) ──
  IF p_move_claims THEN
    v_claims := public._wsmove_claims(
      v_source_workspace_id, p_destination_workspace_id,
      jsonb_build_array(jsonb_build_object('t', 'capture', 'i', p_capture_id))
        || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', a))
                     FROM unnest(v_attachment_ids) a), '[]'::jsonb)
    );
  END IF;

  -- ── graph edges ──
  v_moving := jsonb_build_array(jsonb_build_object('t', 'capture', 'i', p_capture_id))
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', a)) FROM unnest(v_attachment_ids) a), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', a)) FROM jsonb_array_elements_text(v_core->'attachment_ids') a), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'action', 'i', x)) FROM unnest(v_moved_action_ids) x), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'claim', 'i', c)) FROM jsonb_array_elements_text(v_claims->'moved_ids') c), '[]'::jsonb);

  v_links := public._wsmove_entity_links(v_source_workspace_id, p_destination_workspace_id, v_moving);

  -- ── participant contacts: copy auto-created ones the mover CAN SEE
  --    (v3 adds the can_view_contact gate — v2 copied private contacts the
  --    mover had no right to read) ──
  IF p_move_contacts THEN
    WITH src_contacts AS (
      SELECT c.*
      FROM public.contact c
      WHERE c.workspace_id = v_source_workspace_id
        AND c.email IS NOT NULL
        AND c.source IN ('capture_participant', 'calendar_sync')
        AND public.can_view_contact(c.id, c.workspace_id, c.visibility, c.created_by_member_id)
        AND c.id IN (
          SELECT cp.contact_id
          FROM public.capture_participant cp
          WHERE cp.capture_id = p_capture_id
            AND cp.contact_id IS NOT NULL
        )
    ), inserted AS (
      INSERT INTO public.contact (
        workspace_id, member_id, company_id, created_by_member_id,
        first_name, last_name, full_name, email, secondary_emails, phone,
        avatar_url, job_title, department, linkedin_url,
        relationship_type, relationship_strength, visibility,
        source, source_provider, notes, tags, metadata
      )
      SELECT
        p_destination_workspace_id,
        public._wsmove_member_in(sc.member_id, p_destination_workspace_id),
        (SELECT dco.id
         FROM public.company dco
         JOIN public.company sco ON sco.id = sc.company_id
         WHERE dco.workspace_id = p_destination_workspace_id
           AND (
             (sco.domain IS NOT NULL AND dco.domain = sco.domain)
             OR lower(dco.name) = lower(sco.name)
           )
         ORDER BY (dco.domain IS NOT DISTINCT FROM sco.domain) DESC, dco.created_at ASC
         LIMIT 1),
        -- Attribute the copy to the mover: the visibility gate above means
        -- they could already read everything being copied.
        (SELECT dm.id FROM public.member dm
         WHERE dm.workspace_id = p_destination_workspace_id
           AND dm.user_id = v_user_id
         LIMIT 1),
        sc.first_name, sc.last_name, sc.full_name, sc.email,
        sc.secondary_emails, sc.phone, sc.avatar_url, sc.job_title,
        sc.department, sc.linkedin_url, sc.relationship_type,
        sc.relationship_strength, sc.visibility, sc.source,
        sc.source_provider, sc.notes, sc.tags, sc.metadata
      FROM src_contacts sc
      WHERE NOT EXISTS (
        SELECT 1 FROM public.contact dc
        WHERE dc.workspace_id = p_destination_workspace_id
          AND (
            dc.email = sc.email
            OR sc.email = ANY(COALESCE(dc.secondary_emails, '{}'))
          )
      )
      RETURNING 1
    )
    SELECT count(*) INTO v_copied_contacts FROM inserted;
  END IF;

  -- ── translate participant member/contact refs (v2 logic) ──
  UPDATE public.capture_participant cp
  SET member_id = public._wsmove_member_in(cp.member_id, p_destination_workspace_id)
  WHERE cp.capture_id = p_capture_id
    AND cp.member_id IS NOT NULL;

  UPDATE public.capture_participant cp
  SET contact_id = (
    SELECT dc.id
    FROM public.contact dc
    JOIN public.contact sc ON sc.id = cp.contact_id
    WHERE dc.workspace_id = p_destination_workspace_id
      AND sc.email IS NOT NULL
      AND (
        dc.email = sc.email
        OR sc.email = ANY(COALESCE(dc.secondary_emails, '{}'))
      )
    ORDER BY (dc.email = sc.email) DESC NULLS LAST, dc.created_at ASC
    LIMIT 1
  )
  WHERE cp.capture_id = p_capture_id
    AND cp.contact_id IS NOT NULL;

  -- ── residue on both sides (decisions included in the moving set so their
  --    notifications/pins clean up) ──
  v_residue := public._wsmove_residue(
    v_source_workspace_id, p_destination_workspace_id,
    v_moving || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'decision', 'i', d.id))
                          FROM public.decision d
                          WHERE d.capture_id = p_capture_id), '[]'::jsonb)
  );

  v_counts := jsonb_build_object(
    -- v2 keys the shipped client reads
    'unlinked_actions', v_unlinked_actions,
    'moved_suggested_actions', cardinality(v_suggested_action_ids),
    'moved_confirmed_actions', cardinality(v_confirmed_ids),
    'moved_decisions', v_moved_decisions,
    'moved_proposed_changes', v_moved_proposed_changes,
    'moved_claims', v_claims->'moved',
    'shared_claims_left', v_claims->'left',
    'copied_contacts', v_copied_contacts,
    -- v3 additions
    'identifier_map', v_core->'identifier_map',
    'renumbered', v_core->'renumbered',
    'external_tasks_severed', v_core->'external_tasks_severed',
    'agent_runs_removed', v_core->'agent_runs_removed',
    'comments_translated', v_comments_translated + (v_core->>'comments_translated')::int,
    'labels_remapped', v_labels->'remapped',
    'labels_removed', v_labels->'deleted',
    'shares_deactivated', v_shares_deactivated,
    'ai_threads_unlinked', v_threads_unlinked,
    'attachments', cardinality(v_attachment_ids),
    'links_moved', v_links->'moved',
    'links_severed', v_links->'severed'
  ) || v_residue;

  INSERT INTO public.workspace_move_log
    (entity_type, entity_id, source_workspace_id, destination_workspace_id, moved_by, counts)
  VALUES ('capture', p_capture_id, v_source_workspace_id, p_destination_workspace_id, v_user_id, v_counts);

  RETURN jsonb_build_object(
    'capture_id', p_capture_id,
    'source_workspace_id', v_source_workspace_id,
    'destination_workspace_id', p_destination_workspace_id,
    'counts', v_counts
  );
END;
$$;


ALTER FUNCTION "public"."move_capture"("p_capture_id" "uuid", "p_destination_workspace_id" "uuid", "p_confirmed_action_ids" "uuid"[], "p_move_claims" boolean, "p_move_contacts" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_capture"("p_capture_id" "uuid", "p_destination_workspace_id" "uuid", "p_confirmed_action_ids" "uuid"[], "p_move_claims" boolean, "p_move_contacts" boolean) IS 'Move a capture (v3 + 223 visibility guard): v2 semantics plus — delete-parity role gate, private captures movable only by their creator, identifier preserve-or-renumber, external task links severed, claim_source evidence re-stamped, contact copies visibility-gated, AI thread unlinked, extraction ledger follows, labels remap by name, shares deactivate in place, residue cleaned. The caller no longer needs to copy storage objects.';


CREATE OR REPLACE FUNCTION "public"."move_document"("p_document_id" "uuid", "p_destination_workspace_id" "uuid", "p_move_claims" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_source uuid;
  v_owns boolean;
  v_core jsonb;
  v_claims jsonb := jsonb_build_object('moved', 0, 'left', 0, 'moved_ids', '[]'::jsonb);
  v_links jsonb;
  v_residue jsonb;
  v_moving jsonb;
  v_counts jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT d.workspace_id,
         EXISTS (
           SELECT 1 FROM public.member m
           WHERE m.id = d.created_by AND m.user_id = v_user_id
         )
  INTO v_source, v_owns
  FROM public.document d
  WHERE d.id = p_document_id
  FOR UPDATE OF d;

  IF v_source IS NULL THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public._wsmove_gate(
    v_user_id, v_source, p_destination_workspace_id, COALESCE(v_owns, false));

  -- 360: the workspace product doc moves only for an owner or admin of the
  -- source workspace (359's rule: the creator, except the product doc).
  IF COALESCE((SELECT m.role FROM public.member m
                WHERE m.workspace_id = v_source AND m.user_id = v_user_id), '')
       NOT IN ('owner', 'admin')
     AND public.is_product_doc(v_source, p_document_id) THEN
    RAISE EXCEPTION 'only an owner or admin can move the workspace product doc'
      USING ERRCODE = '42501';
  END IF;

  -- 369: a private document moves only with its creator (move_capture's
  -- rule): someone who can't read it can't carry it somewhere they can.
  IF EXISTS (
       SELECT 1 FROM public.document d
        WHERE d.id = p_document_id
          AND d.visibility = 'private'
          AND NOT COALESCE(v_owns, false)
     ) THEN
    RAISE EXCEPTION 'only its creator can move a private document'
      USING ERRCODE = '42501';
  END IF;

  v_core := public._wsmove_documents_core(
    ARRAY[p_document_id], v_source, p_destination_workspace_id,
    false  -- the project (if any) stays behind
  );

  IF p_move_claims THEN
    v_claims := public._wsmove_claims(
      v_source, p_destination_workspace_id,
      jsonb_build_array(jsonb_build_object('t', 'document', 'i', p_document_id))
    );
  END IF;

  v_moving := jsonb_build_array(jsonb_build_object('t', 'document', 'i', p_document_id))
    || COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('t', 'claim', 'i', c))
       FROM jsonb_array_elements_text(v_claims->'moved_ids') c),
      '[]'::jsonb);

  v_links := public._wsmove_entity_links(v_source, p_destination_workspace_id, v_moving);
  v_residue := public._wsmove_residue(v_source, p_destination_workspace_id, v_moving);

  v_counts := jsonb_build_object(
    'slugs_cleared', v_core->'slugs_cleared',
    'shares_deactivated', v_core->'shares_deactivated',
    'drafts_translated', v_core->'drafts_translated',
    'drafts_discarded', v_core->'drafts_discarded',
    'comments_translated', v_core->'comments_translated',
    'moved_claims', v_claims->'moved',
    'shared_claims_left', v_claims->'left',
    'links_moved', v_links->'moved',
    'links_severed', v_links->'severed'
  ) || v_residue;

  INSERT INTO public.workspace_move_log
    (entity_type, entity_id, source_workspace_id, destination_workspace_id, moved_by, counts)
  VALUES ('document', p_document_id, v_source, p_destination_workspace_id, v_user_id, v_counts);

  RETURN jsonb_build_object(
    'document_id', p_document_id,
    'source_workspace_id', v_source,
    'destination_workspace_id', p_destination_workspace_id,
    'counts', v_counts
  );
END;
$$;


ALTER FUNCTION "public"."move_document"("p_document_id" "uuid", "p_destination_workspace_id" "uuid", "p_move_claims" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_document"("p_document_id" "uuid", "p_destination_workspace_id" "uuid", "p_move_claims" boolean) IS 'Move a document (chunks, revisions; drafts translate by user identity, discarded only for non-members; slug cleared on destination collision; shares deactivated in place) plus claims solely evidenced by it when p_move_claims.';


CREATE OR REPLACE FUNCTION "public"."move_initiative"("p_initiative_id" "uuid", "p_destination_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_source uuid;
  v_owns boolean;
  v_projects_unlinked int := 0;
  v_views_deleted int := 0;
  v_labels jsonb;
  v_links jsonb;
  v_residue jsonb;
  v_moving jsonb;
  v_counts jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT i.workspace_id,
         EXISTS (
           SELECT 1 FROM public.member m
           WHERE m.id = i.owner_id AND m.user_id = v_user_id
         )
  INTO v_source, v_owns
  FROM public.initiative i
  WHERE i.id = p_initiative_id
  FOR UPDATE OF i;

  IF v_source IS NULL THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public._wsmove_gate(
    v_user_id, v_source, p_destination_workspace_id, COALESCE(v_owns, false));

  UPDATE public.initiative i
  SET workspace_id = p_destination_workspace_id,
      owner_id = public._wsmove_member_in(i.owner_id, p_destination_workspace_id)
  WHERE i.id = p_initiative_id;

  WITH unlinked AS (
    UPDATE public.projects
    SET initiative_id = NULL
    WHERE workspace_id = v_source AND initiative_id = p_initiative_id
    RETURNING 1
  )
  SELECT count(*) INTO v_projects_unlinked FROM unlinked;

  v_labels := public._wsmove_remap_labels(
    'initiative_label', 'initiative_id', ARRAY[p_initiative_id],
    v_source, p_destination_workspace_id);

  WITH gone AS (
    DELETE FROM public.view
    WHERE workspace_id = v_source
      AND scope_type = 'initiative'
      AND scope_id = p_initiative_id
    RETURNING 1
  )
  SELECT count(*) INTO v_views_deleted FROM gone;

  v_moving := jsonb_build_array(jsonb_build_object('t', 'initiative', 'i', p_initiative_id));
  v_links := public._wsmove_entity_links(v_source, p_destination_workspace_id, v_moving);
  v_residue := public._wsmove_residue(v_source, p_destination_workspace_id, v_moving);

  v_counts := jsonb_build_object(
    'projects_unlinked', v_projects_unlinked,
    'labels_remapped', v_labels->'remapped',
    'labels_removed', v_labels->'deleted',
    'views_deleted', v_views_deleted,
    'links_moved', v_links->'moved',
    'links_severed', v_links->'severed'
  ) || v_residue;

  INSERT INTO public.workspace_move_log
    (entity_type, entity_id, source_workspace_id, destination_workspace_id, moved_by, counts)
  VALUES ('initiative', p_initiative_id, v_source, p_destination_workspace_id, v_user_id, v_counts);

  RETURN jsonb_build_object(
    'initiative_id', p_initiative_id,
    'source_workspace_id', v_source,
    'destination_workspace_id', p_destination_workspace_id,
    'counts', v_counts
  );
END;
$$;


ALTER FUNCTION "public"."move_initiative"("p_initiative_id" "uuid", "p_destination_workspace_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_initiative"("p_initiative_id" "uuid", "p_destination_workspace_id" "uuid") IS 'Move an initiative row to another workspace; its projects stay behind with initiative_id cleared.';


CREATE OR REPLACE FUNCTION "public"."move_note_to_project"("p_user_id" "uuid", "p_note_id" "uuid", "p_new_project_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_note_exists BOOLEAN;
    v_project_exists BOOLEAN;
BEGIN
    -- Verify note belongs to user
    SELECT EXISTS(
        SELECT 1 FROM notes WHERE id = p_note_id AND user_id = p_user_id
    ) INTO v_note_exists;

    IF NOT v_note_exists THEN
        RAISE EXCEPTION 'Note not found or access denied';
    END IF;

    -- Verify new project belongs to user
    SELECT EXISTS(
        SELECT 1 FROM projects WHERE id = p_new_project_id AND user_id = p_user_id
    ) INTO v_project_exists;

    IF NOT v_project_exists THEN
        RAISE EXCEPTION 'Target project not found or access denied';
    END IF;

    -- Update note
    UPDATE notes
    SET project_id = p_new_project_id, updated_at = NOW()
    WHERE id = p_note_id AND user_id = p_user_id;

    -- Update all chunks
    UPDATE note_chunks
    SET project_id = p_new_project_id
    WHERE note_id = p_note_id AND user_id = p_user_id;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."move_note_to_project"("p_user_id" "uuid", "p_note_id" "uuid", "p_new_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_project"("p_project_id" "uuid", "p_destination_workspace_id" "uuid", "p_destination_team_id" "uuid" DEFAULT NULL::"uuid", "p_move_documents" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_source uuid;
  v_name text;
  v_owns boolean;
  v_dest_team uuid;
  v_dest_default_status uuid;
  v_action_ids uuid[] := '{}';
  v_doc_ids uuid[] := '{}';
  v_milestone_ids uuid[] := '{}';
  v_attachment_ids uuid[] := '{}';
  v_captures_unlinked int := 0;
  v_docs_unlinked int := 0;
  v_views_deleted int := 0;
  v_core jsonb;
  v_doc_core jsonb := jsonb_build_object(
    'moved', 0, 'slugs_cleared', 0, 'shares_deactivated', 0,
    'drafts_translated', 0, 'drafts_discarded', 0, 'comments_translated', 0);
  v_claims jsonb := jsonb_build_object('moved', 0, 'left', 0, 'moved_ids', '[]'::jsonb);
  v_labels jsonb;
  v_comments_translated int := 0;
  v_links jsonb;
  v_residue jsonb;
  v_moving jsonb;
  v_counts jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT p.workspace_id, p.name,
         (p.user_id = v_user_id) OR EXISTS (
           SELECT 1 FROM public.member m
           WHERE m.id = p.lead_id AND m.user_id = v_user_id
         )
  INTO v_source, v_name, v_owns
  FROM public.projects p
  WHERE p.id = p_project_id
  FOR UPDATE OF p;

  IF v_source IS NULL THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public._wsmove_gate(
    v_user_id, v_source, p_destination_workspace_id, COALESCE(v_owns, false));

  -- 360: a project whose documents move along may not carry the workspace
  -- product doc away unless the caller is an owner or admin of the source
  -- workspace (359's rule: the creator, except the product doc).
  IF p_move_documents
     AND COALESCE((SELECT m.role FROM public.member m
                    WHERE m.workspace_id = v_source AND m.user_id = v_user_id), '')
           NOT IN ('owner', 'admin')
     AND EXISTS (
       SELECT 1 FROM public.document d
        WHERE d.project_id = p_project_id
          AND d.workspace_id = v_source
          AND public.is_product_doc(d.workspace_id, d.id)
     ) THEN
    RAISE EXCEPTION 'only an owner or admin can move a project holding the workspace product doc'
      USING ERRCODE = '42501';
  END IF;

  -- 369: documents moving along may not carry someone else's private
  -- document (the caller can't read it, so can't carry it somewhere they can).
  IF p_move_documents AND EXISTS (
       SELECT 1 FROM public.document d
        WHERE d.project_id = p_project_id
          AND d.workspace_id = v_source
          AND d.visibility = 'private'
          AND NOT EXISTS (
            SELECT 1 FROM public.member m
             WHERE m.id = d.created_by AND m.user_id = v_user_id
          )
     ) THEN
    RAISE EXCEPTION 'the project holds someone else''s private document'
      USING ERRCODE = '42501';
  END IF;

  -- After the gate: a P0005 before it would tell a non-member whether a
  -- guessed project id is a workspace's default bucket (existence oracle).
  IF v_name = '__default__' THEN
    RAISE EXCEPTION 'the default project cannot be moved' USING ERRCODE = 'P0005';
  END IF;

  SELECT team_id, default_status_id
  INTO v_dest_team, v_dest_default_status
  FROM public._wsmove_dest_team(p_destination_workspace_id, p_destination_team_id);

  -- ── the closure sets ──
  SELECT COALESCE(array_agg(id), '{}') INTO v_action_ids
  FROM public.actions
  WHERE project_id = p_project_id AND workspace_id = v_source;

  SELECT COALESCE(array_agg(id), '{}') INTO v_milestone_ids
  FROM public.milestone
  WHERE project_id = p_project_id;

  IF p_move_documents THEN
    SELECT COALESCE(array_agg(id), '{}') INTO v_doc_ids
    FROM public.document
    WHERE project_id = p_project_id AND workspace_id = v_source;
  END IF;

  -- ── captures stay; unlink them ──
  WITH unlinked AS (
    UPDATE public.captures
    SET project_id = NULL
    WHERE project_id = p_project_id AND workspace_id = v_source
    RETURNING id
  ),
  chunks AS (
    UPDATE public.capture_chunks cc
    SET project_id = NULL
    FROM unlinked u
    WHERE cc.capture_id = u.id
    RETURNING 1
  )
  SELECT count(*) INTO v_captures_unlinked FROM unlinked;

  -- ── documents: move or unlink ──
  IF p_move_documents THEN
    v_doc_core := public._wsmove_documents_core(
      v_doc_ids, v_source, p_destination_workspace_id,
      true,          -- the project moves with them
      v_action_ids   -- action_document rows to moved actions survive
    );
    IF cardinality(v_doc_ids) > 0 THEN
      v_claims := public._wsmove_claims(
        v_source, p_destination_workspace_id,
        (SELECT jsonb_agg(jsonb_build_object('t', 'document', 'i', d))
         FROM unnest(v_doc_ids) d)
      );
    END IF;
  ELSE
    WITH unlinked AS (
      UPDATE public.document
      SET project_id = NULL
      WHERE project_id = p_project_id AND workspace_id = v_source
      RETURNING id
    ),
    chunks AS (
      UPDATE public.document_chunks dc
      SET project_id = NULL
      FROM unlinked u
      WHERE dc.document_id = u.id
      RETURNING 1
    )
    SELECT count(*) INTO v_docs_unlinked FROM unlinked;
  END IF;

  -- ── all the project's actions move with it ──
  v_core := public._wsmove_actions_core(
    v_action_ids, v_source, p_destination_workspace_id,
    v_dest_team, v_dest_default_status,
    true,   -- keep project/milestone links: they move in this transaction
    true,   -- source captures stay behind
    v_doc_ids
  );

  -- ── the project row itself ──
  UPDATE public.projects p
  SET workspace_id = p_destination_workspace_id,
      initiative_id = NULL,
      lead_id = public._wsmove_member_in(p.lead_id, p_destination_workspace_id),
      parent_project_id = NULL
  WHERE p.id = p_project_id;

  -- sub-projects that stay lose their parent pointer
  UPDATE public.projects
  SET parent_project_id = NULL
  WHERE workspace_id = v_source AND parent_project_id = p_project_id;

  -- milestones travel by construction (project_id NOT NULL, no workspace
  -- column); actions in OTHER projects that pointed at them must let go
  UPDATE public.actions
  SET milestone_id = NULL
  WHERE workspace_id = v_source
    AND milestone_id = ANY(v_milestone_ids)
    AND NOT (id = ANY(v_action_ids));

  v_labels := public._wsmove_remap_labels(
    'project_label', 'project_id', ARRAY[p_project_id], v_source, p_destination_workspace_id);

  v_comments_translated := public._wsmove_comments(
    'project', ARRAY[p_project_id], v_source, p_destination_workspace_id);

  UPDATE public.project_embedding
  SET workspace_id = p_destination_workspace_id
  WHERE project_id = p_project_id;

  -- decisions never move (capture-owned): suggested ones let go of the
  -- project, confirmed ones keep the user-set attribution (v2 precedent)
  UPDATE public.decision
  SET project_id = NULL
  WHERE project_id = p_project_id
    AND confirmation = 'suggested';

  -- project-parented attachments follow
  SELECT COALESCE(array_agg(id), '{}') INTO v_attachment_ids
  FROM public.attachments
  WHERE project_id = p_project_id AND workspace_id = v_source;

  UPDATE public.attachments
  SET workspace_id = p_destination_workspace_id
  WHERE id = ANY(v_attachment_ids);

  UPDATE public.attachment_chunks
  SET workspace_id = p_destination_workspace_id
  WHERE attachment_id = ANY(v_attachment_ids);

  -- project-scoped saved views reference workspace-scoped filter ids that
  -- don't translate; deleted (counted, disclosed in preflight)
  WITH gone AS (
    DELETE FROM public.view
    WHERE workspace_id = v_source
      AND scope_type = 'project'
      AND scope_id = p_project_id
    RETURNING 1
  )
  SELECT count(*) INTO v_views_deleted FROM gone;

  -- packages that curated by this project stop doing so
  UPDATE public.knowledge_package kp
  SET rules = jsonb_set(
    kp.rules, '{projects}',
    COALESCE((
      SELECT jsonb_agg(x)
      FROM jsonb_array_elements(kp.rules->'projects') x
      WHERE x <> to_jsonb(p_project_id::text)
    ), '[]'::jsonb))
  WHERE kp.workspace_id = v_source
    AND jsonb_typeof(kp.rules->'projects') = 'array'
    AND kp.rules->'projects' @> to_jsonb(p_project_id::text);

  -- ── graph + residue ──
  v_moving := jsonb_build_array(jsonb_build_object('t', 'project', 'i', p_project_id))
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'action', 'i', x)) FROM unnest(v_action_ids) x), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'document', 'i', x)) FROM unnest(v_doc_ids) x), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'milestone', 'i', x)) FROM unnest(v_milestone_ids) x), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', x)) FROM unnest(v_attachment_ids) x), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'attachment', 'i', a)) FROM jsonb_array_elements_text(v_core->'attachment_ids') a), '[]'::jsonb)
    || COALESCE((SELECT jsonb_agg(jsonb_build_object('t', 'claim', 'i', c)) FROM jsonb_array_elements_text(v_claims->'moved_ids') c), '[]'::jsonb);

  v_links := public._wsmove_entity_links(v_source, p_destination_workspace_id, v_moving);
  v_residue := public._wsmove_residue(v_source, p_destination_workspace_id, v_moving);

  v_counts := jsonb_build_object(
    'moved_actions', v_core->'moved',
    'identifier_map', v_core->'identifier_map',
    'renumbered', v_core->'renumbered',
    'moved_documents', v_doc_core->'moved',
    'documents_unlinked', v_docs_unlinked,
    'moved_milestones', cardinality(v_milestone_ids),
    'captures_unlinked', v_captures_unlinked,
    'moved_claims', v_claims->'moved',
    'shared_claims_left', v_claims->'left',
    'labels_remapped', v_labels->'remapped',
    'labels_removed', v_labels->'deleted',
    'action_labels_remapped', v_core->'labels'->'remapped',
    'action_labels_removed', v_core->'labels'->'deleted',
    'assignees_translated', v_core->'assignees_translated',
    'assignees_dropped', v_core->'assignees_dropped',
    'external_tasks_severed', v_core->'external_tasks_severed',
    'agent_runs_removed', v_core->'agent_runs_removed',
    'comments_translated',
      (v_core->>'comments_translated')::int
      + (v_doc_core->>'comments_translated')::int
      + v_comments_translated,
    'drafts_translated', v_doc_core->'drafts_translated',
    'drafts_discarded', v_doc_core->'drafts_discarded',
    'attachments_moved',
      cardinality(v_attachment_ids) + jsonb_array_length(v_core->'attachment_ids'),
    'slugs_cleared', v_doc_core->'slugs_cleared',
    'shares_deactivated', v_doc_core->'shares_deactivated',
    'views_deleted', v_views_deleted,
    'links_moved', v_links->'moved',
    'links_severed', v_links->'severed'
  ) || v_residue;

  INSERT INTO public.workspace_move_log
    (entity_type, entity_id, source_workspace_id, destination_workspace_id, moved_by, counts)
  VALUES ('project', p_project_id, v_source, p_destination_workspace_id, v_user_id, v_counts);

  RETURN jsonb_build_object(
    'project_id', p_project_id,
    'source_workspace_id', v_source,
    'destination_workspace_id', p_destination_workspace_id,
    'destination_team_id', v_dest_team,
    'counts', v_counts
  );
END;
$$;


