CREATE OR REPLACE FUNCTION "public"."prevent_transcript_edit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF old.is_transcript_locked = true
     AND new.transcript IS DISTINCT FROM old.transcript THEN
    RAISE EXCEPTION 'Transcript is locked after capture has ended';
  END IF;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."prevent_transcript_edit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profile_fact_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- The server: the service role, or no request at all.
  if coalesce(auth.role(), '') in ('', 'service_role') then
    new.updated_at := now();
    return new;
  end if;

  if tg_op = 'INSERT' then
    -- A fact a person adds is theirs, told or typed, active. Learning and
    -- supersession are the server's.
    if new.user_id is distinct from auth.uid() or new.source = 'learned' then
      raise exception 'A fact you add is yours, told or edited, never learned'
        using errcode = 'insufficient_privilege';
    end if;
    if new.superseded_by is not null or new.retired_at is not null then
      raise exception 'Only the server supersedes or retires a fact'
        using errcode = 'insufficient_privilege';
    end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  -- A foreign key's ON DELETE SET NULL is an UPDATE run inside the delete
  -- (trigger depth > 1), under the deleting caller's role: the newer fact
  -- deleted clears superseded_by, the workspace deleted clears
  -- source_workspace_id. Those are allowed, and nothing else may change with
  -- them. The fact stays retired (retired_at), so it never comes back.
  if pg_trigger_depth() > 1
     and new.id = old.id
     and new.user_id = old.user_id
     and new.text = old.text
     and new.status = old.status
     and new.source = old.source
     and new.importance = old.importance
     and new.created_at = old.created_at
     and new.retired_at is not distinct from old.retired_at
     and (new.superseded_by is not distinct from old.superseded_by or new.superseded_by is null)
     and (new.source_workspace_id is not distinct from old.source_workspace_id or new.source_workspace_id is null) then
    return new;
  end if;

  -- A fact never moves to another person, and keeps where and when it began.
  if new.id is distinct from old.id
     or new.user_id is distinct from old.user_id
     or new.created_at is distinct from old.created_at
     or new.source_workspace_id is distinct from old.source_workspace_id
     or new.superseded_by is distinct from old.superseded_by
     or new.retired_at is distinct from old.retired_at then
    raise exception 'A fact cannot move or change where it came from: delete it and add a new one'
      using errcode = 'insufficient_privilege';
  end if;

  -- An accepted fact can't go back to waiting, and a person's change is an edit.
  if old.status = 'active' and new.status = 'proposed' then
    raise exception 'An active fact cannot go back to proposed'
      using errcode = 'check_violation';
  end if;
  if new.source is distinct from old.source and new.source <> 'edited' then
    raise exception 'A changed fact is edited, never told or learned'
      using errcode = 'insufficient_privilege';
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."profile_fact_guard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_fact_guard"() IS 'BEFORE INSERT OR UPDATE on profile_fact (328). Unless the caller is the service role or has no request context: a new fact is the caller''s, never learned, superseded or retired; a fact never changes user, created_at, source_workspace_id, superseded_by or retired_at, never goes from active back to proposed, and a changed source can only become edited. A foreign key''s SET NULL (trigger depth > 1) may clear superseded_by or source_workspace_id, and nothing else.';


CREATE OR REPLACE FUNCTION "public"."proposed_change_track_resolution"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' AND NEW.resolved_at IS NULL THEN
      NEW.resolved_at = now();
    END IF;
    IF NEW.status = 'pending' AND NEW.expires_at IS NULL AND NEW.capture_id IS NULL THEN
      NEW.expires_at = now() + interval '30 days';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'pending' THEN
      NEW.resolved_at = NULL;
    ELSE
      NEW.resolved_at = now();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."proposed_change_track_resolution"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prospect_list_mark_published"("p_workspace" "uuid", "p_list" "uuid", "p_company_ids" "uuid"[], "p_contact_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.is_workspace_member(p_workspace) THEN
    RAISE EXCEPTION 'not a member of workspace %', p_workspace USING ERRCODE = '42501';
  END IF;

  UPDATE public.company
     SET prospect_list_ids = array_append(prospect_list_ids, p_list)
   WHERE workspace_id = p_workspace
     AND id = ANY (COALESCE(p_company_ids, '{}'::uuid[]))
     AND NOT (prospect_list_ids @> ARRAY[p_list]);

  UPDATE public.contact
     SET prospect_list_ids = array_append(prospect_list_ids, p_list)
   WHERE workspace_id = p_workspace
     AND id = ANY (COALESCE(p_contact_ids, '{}'::uuid[]))
     AND NOT (prospect_list_ids @> ARRAY[p_list]);
END;
$$;


