CREATE OR REPLACE FUNCTION "public"."resolve_effective_plan"("p_user_id" "uuid") RETURNS TABLE("plan_def" "public"."ai_plan_definitions", "user_plan" "public"."ai_user_plans")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE v_plan_def ai_plan_definitions; v_user_plan ai_user_plans;
BEGIN
  SELECT * INTO v_user_plan FROM ai_user_plans WHERE ai_user_plans.user_id = p_user_id AND ai_user_plans.is_active = true;
  IF v_user_plan.user_id IS NOT NULL AND v_user_plan.admin_override = true THEN
    SELECT * INTO v_plan_def FROM ai_plan_definitions WHERE id = v_user_plan.plan_id;
  END IF;
  IF v_plan_def IS NULL THEN
    IF EXISTS (SELECT 1 FROM subscriptions s WHERE s.user_id = p_user_id AND s.status IN ('active','trialing')
        AND (s.current_period_end IS NULL OR s.current_period_end > now() - interval '3 days')) THEN
      SELECT * INTO v_plan_def FROM ai_plan_definitions WHERE purchase_action = 'subscription' LIMIT 1;
    END IF;
  END IF;
  IF v_plan_def IS NULL AND v_user_plan.user_id IS NOT NULL THEN SELECT * INTO v_plan_def FROM ai_plan_definitions WHERE id = v_user_plan.plan_id; END IF;
  IF v_plan_def IS NULL THEN SELECT * INTO v_plan_def FROM ai_plan_definitions WHERE is_default = true LIMIT 1; END IF;
  plan_def := v_plan_def; user_plan := v_user_plan; RETURN NEXT;
END; $$;


ALTER FUNCTION "public"."resolve_effective_plan"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_actions_by_embedding"("p_user_id" "uuid", "p_embedding" "public"."vector", "p_limit" integer DEFAULT 10, "p_threshold" real DEFAULT 0.7) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "due_at" timestamp with time zone, "status" "text", "similarity" real)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        a.id,
        a.title,
        a.description,
        a.due_at,
        a.status,
        1 - (a.embedding <=> p_embedding) AS similarity
    FROM actions a
    WHERE a.user_id = p_user_id
      AND a.embedding IS NOT NULL
      AND 1 - (a.embedding <=> p_embedding) >= p_threshold
    ORDER BY a.embedding <=> p_embedding
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_actions_by_embedding"("p_user_id" "uuid", "p_embedding" "public"."vector", "p_limit" integer, "p_threshold" real) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_actions_by_title"("p_user_id" "uuid", "p_search_term" "text") RETURNS TABLE("id" "uuid", "title" "text", "similarity" real)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT a.id, a.title, similarity(a.title, p_search_term) AS sim
    FROM actions a
    WHERE a.user_id = p_user_id
    AND a.status IN ('confirmed', 'in_progress')
    AND (a.title ILIKE '%' || p_search_term || '%' OR similarity(a.title, p_search_term) > 0.3)
    ORDER BY similarity(a.title, p_search_term) DESC
    LIMIT 5;
END;
$$;


ALTER FUNCTION "public"."search_actions_by_title"("p_user_id" "uuid", "p_search_term" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_contacts"("p_user_id" "uuid", "p_search_term" "text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "first_name" "text", "last_name" "text", "nickname" "text", "company" "text", "job_title" "text", "image_url" "text", "is_favorite" boolean, "primary_email" "text", "primary_phone" "text", "relevance" real)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (c.id)
        c.id,
        c.first_name,
        c.last_name,
        c.nickname,
        c.company,
        c.job_title,
        c.image_url,
        c.is_favorite,
        (SELECT ce.email FROM contact_emails ce WHERE ce.contact_id = c.id AND ce.is_primary = TRUE LIMIT 1) AS primary_email,
        (SELECT cp.phone_number FROM contact_phones cp WHERE cp.contact_id = c.id AND cp.is_primary = TRUE LIMIT 1) AS primary_phone,
        (ts_rank(
            to_tsvector('english', COALESCE(c.first_name, '') || ' ' || COALESCE(c.last_name, '') || ' ' || COALESCE(c.nickname, '') || ' ' || COALESCE(c.company, '')),
            plainto_tsquery('english', p_search_term)
        ) +
        CASE
            WHEN LOWER(c.first_name) = LOWER(p_search_term) THEN 1.0
            WHEN LOWER(c.last_name) = LOWER(p_search_term) THEN 1.0
            WHEN LOWER(c.nickname) = LOWER(p_search_term) THEN 1.0
            WHEN LOWER(c.first_name) LIKE LOWER(p_search_term) || '%' THEN 0.8
            WHEN LOWER(c.last_name) LIKE LOWER(p_search_term) || '%' THEN 0.8
            WHEN LOWER(c.nickname) LIKE LOWER(p_search_term) || '%' THEN 0.8
            ELSE 0
        END)::REAL AS relevance
    FROM contacts c
    LEFT JOIN contact_emails ce ON ce.contact_id = c.id
    WHERE c.user_id = p_user_id
    AND (
        c.first_name ILIKE '%' || p_search_term || '%'
        OR c.last_name ILIKE '%' || p_search_term || '%'
        OR c.nickname ILIKE '%' || p_search_term || '%'
        OR c.company ILIKE '%' || p_search_term || '%'
        OR ce.email ILIKE '%' || p_search_term || '%'
        OR to_tsvector('english', COALESCE(c.first_name, '') || ' ' || COALESCE(c.last_name, '') || ' ' || COALESCE(c.nickname, '') || ' ' || COALESCE(c.company, '')) @@ plainto_tsquery('english', p_search_term)
    )
    ORDER BY c.id, relevance DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_contacts"("p_user_id" "uuid", "p_search_term" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_role_teammates"("p_workspace_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_team uuid;
  v_by uuid;
  v_recipe uuid;
  v_face text;
  v_count integer := 0;
  s record;
begin
  perform pg_advisory_xact_lock(hashtext('seed_role_teammates:' || p_workspace_id::text));

  select t.id into v_team
  from public.team t
  where t.workspace_id = p_workspace_id
  order by t.is_private asc, t.created_at asc, t.id asc
  limit 1;
  if v_team is null then
    return 0;
  end if;

  -- Who the rows are "created by": the person who flipped the switch, else the
  -- workspace's first owner.
  v_by := p_created_by;
  if v_by is null then
    select m.user_id into v_by
    from public.member m
    where m.workspace_id = p_workspace_id and m.role = 'owner'
    order by m.created_at asc
    limit 1;
  end if;

  for s in
    select * from (values
      (
        1, 'researcher', 'Researcher', 'role-researcher', '🔎', '#0ea5e9',
        'Finds out what is true and writes it down, with sources.',
        'You are the workspace''s Researcher. You find out what is actually true and write it down so a person can act on it. Prefer primary sources over summaries of them, cite the URL of every fact you take from the web, and keep what you found separate from what you infer. When you could not establish something, say so plainly instead of guessing. Deliver a document: the answer first, in a few sentences, then the evidence behind it.',
        'attempt', array['read', 'internal-write'], array[]::text[]
      ),
      (
        2, 'writer', 'Writer', 'role-writer', '✍️', '#3b82f6',
        'Drafts documents people can use as they are.',
        'You are the workspace''s Writer. You draft documents people can use with light edits: lead with the point, match the workspace''s tone, and keep it as short as the job allows. Every specific (a name, a date, a number, a commitment) comes from the workspace or the brief; never invent one, and mark anything you had to assume.',
        'attempt', array['read', 'internal-write'], array['researcher']
      ),
      (
        3, 'correspondent', 'Correspondent', 'role-correspondent', '✉️', '#10b981',
        'Drafts emails for a person to review and send.',
        'You are the workspace''s Correspondent. You draft emails for a person to review and send; you never send one yourself. Open with what the recipient needs to know, make one clear ask, and keep paragraphs short. Promise nothing the workspace has not agreed to, and ground every name, date and figure in the workspace or the brief.',
        'attempt', array['read', 'internal-write'], array['researcher']
      ),
      (
        4, 'developer', 'Developer', 'role-developer', '🛠️', '#6366f1',
        'Scopes code changes into a plan an engineer or a coding run can pick up.',
        'You are the workspace''s Developer. You turn a request into a change someone can build: read the linked project, action and discussion, then write down what should change, the files and systems likely involved, how to verify it, and the risks. Be concrete and brief, and say what you could not confirm from the workspace.',
        'propose', array['read'], array['researcher']
      )
    ) as v(ord, role, name, slug, icon, color, description, prompt, autonomy, classes, delegates)
    order by ord
  loop
    if exists (
      select 1 from public.ai_team_member a
      where a.workspace_id = p_workspace_id and a.role = s.role
    ) then
      continue;
    end if;

    select r.id into v_recipe
    from public.recipe r
    where r.workspace_id = p_workspace_id and r.slug = s.slug
    limit 1;
    if v_recipe is null then
      insert into public.recipe (
        workspace_id, name, slug, icon, color, description, system_prompt,
        category, is_system, visibility, created_by
      )
      values (
        p_workspace_id, s.name, s.slug, s.icon, s.color, s.description, s.prompt,
        'agent', false, 'workspace', v_by
      )
      returning id into v_recipe;
    end if;

    v_face := public.default_bot_character(null, s.role);
    -- The one email face moves to the Correspondent: off Mail (Email drafts
    -- before 318), only while Mail still wears it.
    if s.role = 'correspondent' then
      update public.ai_team_member
      set bot_character = null
      where workspace_id = p_workspace_id
        and system_key = 'mail'
        and bot_character = v_face;
    end if;

    insert into public.ai_team_member (
      workspace_id, team_id, name, agent_recipe_id, role, autonomy, allowed_side_effects, can_delegate_to, created_by, bot_character
    )
    values (
      p_workspace_id, v_team, s.name, v_recipe, s.role, s.autonomy, s.classes, s.delegates, v_by, v_face
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."seed_role_teammates"("p_workspace_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_system_teammates"("p_workspace_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_team uuid;
  v_count integer;
begin
  select t.id into v_team
  from public.team t
  where t.workspace_id = p_workspace_id
  order by t.created_at asc, t.id asc
  limit 1;
  if v_team is null then
    return 0;
  end if;

  insert into public.ai_team_member (workspace_id, team_id, name, agent_recipe_id, is_system, system_key, bot_character)
  select p_workspace_id, v_team, s.name, r.id, true, s.system_key,
    case
      when s.system_key = 'mail' and exists (
        select 1 from public.ai_team_member a
        where a.workspace_id = p_workspace_id and a.role = 'correspondent'
      ) then null
      when exists (
        select 1 from public.ai_team_member a
        where a.workspace_id = p_workspace_id
          and a.bot_character = public.default_bot_character(s.system_key, null)
      ) then public.free_bot_character(p_workspace_id)
      else public.default_bot_character(s.system_key, null)
    end
  from (values
    ('captures', 'Captures', 'loop-captures', 1),
    ('mail', 'Mail', 'loop-mail', 2),
    ('prospecting', 'Prospecting', 'loop-prospecting', 3),
    ('evals', 'Evals', 'loop-evals', 4),
    ('crm', 'CRM', 'loop-crm', 5),
    ('assistant', 'Assistant', 'loop-assistant', 6)
  ) as s(system_key, name, slug, ord)
  join public.recipe r
    on r.slug = s.slug
   and r.workspace_id is null
   and r.category = 'agent'
  order by s.ord
  on conflict (workspace_id, system_key) do nothing;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."seed_system_teammates"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sequence_sending_account_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF new.sending_account_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.connected_account_workspace caw
       WHERE caw.account_id = new.sending_account_id
         AND caw.workspace_id = new.workspace_id
     )
     AND NOT EXISTS (
       SELECT 1
       FROM public.connected_account ca
       JOIN public.member m
         ON m.user_id = ca.user_id
        AND m.workspace_id = new.workspace_id
       WHERE ca.id = new.sending_account_id
     ) THEN
    RAISE EXCEPTION 'sending_account_id is not reachable from this workspace'
      USING ERRCODE = '42501';
  END IF;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."sequence_sending_account_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_comment_edited_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF new.body IS DISTINCT FROM old.body THEN
    new.edited_at := now();
  END IF;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."set_comment_edited_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."share_identity_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF (new.workspace_id, new.shareable_type, new.shareable_id, new.share_type, new.share_token,
        new.created_by, new.shared_with_email, new.shared_with_user_id, new.created_at)
       IS DISTINCT FROM
       (old.workspace_id, old.shareable_type, old.shareable_id, old.share_type, old.share_token,
        old.created_by, old.shared_with_email, old.shared_with_user_id, old.created_at) THEN
      RAISE EXCEPTION 'a share link''s item, owner, token and recipient never change: revoke it and make a new one'
        USING ERRCODE = '42501';
    END IF;
    IF new.is_active AND NOT old.is_active THEN
      RAISE EXCEPTION 'a switched-off share link stays off: make a new one'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN new;
END
$$;


ALTER FUNCTION "public"."share_identity_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."share_target_visible"("p_shareable_type" "text", "p_shareable_id" "uuid", "p_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.is_workspace_member(p_workspace_id)
    AND CASE p_shareable_type
      WHEN 'document' THEN EXISTS (
        SELECT 1 FROM public.document d
        WHERE d.id = p_shareable_id
          AND d.workspace_id = p_workspace_id
          AND (d.visibility = 'workspace' OR d.created_by = public.current_member_id(p_workspace_id))
      )
      WHEN 'capture' THEN EXISTS (
        SELECT 1 FROM public.captures c
        WHERE c.id = p_shareable_id
          AND c.workspace_id = p_workspace_id
          AND (c.visibility = 'workspace' OR c.user_id = auth.uid())
      )
      ELSE false
    END;
$$;


ALTER FUNCTION "public"."share_target_visible"("p_shareable_type" "text", "p_shareable_id" "uuid", "p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snooze_action"("p_user_id" "uuid", "p_action_id" "uuid", "p_snooze_minutes" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET
        snoozed_until = NOW() + (p_snooze_minutes || ' minutes')::INTERVAL,
        notification_scheduled = FALSE,
        updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."snooze_action"("p_user_id" "uuid", "p_action_id" "uuid", "p_snooze_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_action"("p_user_id" "uuid", "p_action_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET status = 'in_progress', updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id AND status = 'confirmed';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."start_action"("p_user_id" "uuid", "p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_chat_helper"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_turn_id" "text", "p_call_id" "text", "p_teammate_id" "uuid", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb", "p_chat_ceiling" "text"[], "p_areas" "text"[], "p_server_helper" "text" DEFAULT NULL::"text", "p_server_helper_item" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_policy jsonb;
  v_daily integer := 10;
  v_live integer := 3;
  v_server_live integer := 1;
  v_server_daily integer := 6;
  v_check_in_daily integer := 3;
  v_member uuid;
  v_key text;
  v_target uuid;
  v_target_name text;
  v_run public.agent_run;
  v_fingerprint text;
  v_usage boolean;
  v_field text;
  v_value jsonb;
begin
  -- The workspace row lock serializes every chat admission in the workspace
  -- (helpers and the legacy delegations alike) and settings writes. NO KEY:
  -- foreign-key inserts into the workspace's tables proceed while it is held.
  select coalesce(settings->'agent_autonomy', '{}'::jsonb) into v_policy
    from public.workspace where id = p_workspace_id for no key update;
  if not found then return jsonb_build_object('code', 'POLICY_UNAVAILABLE'); end if;
  select id into v_member from public.member
    where workspace_id = p_workspace_id and user_id = p_user_id for share;
  if not found then return jsonb_build_object('code', 'NOT_A_MEMBER'); end if;
  perform 1 from public.chat_conversations
    where id = p_conversation_id and user_id = p_user_id and workspace_id = p_workspace_id for share;
  if not found then return jsonb_build_object('code', 'CONVERSATION_UNAVAILABLE'); end if;

  -- The key: eve's durable session, turn and call ids, each 1-200 characters
  -- without ':' (p_turn_id is '<session>:<turn>'), so it parses one way.
  if p_turn_id is not null and p_turn_id ~ '^[^:]{1,200}:[^:]{1,200}$'
     and p_call_id is not null and length(p_call_id) between 1 and 200 then
    v_key := 'chat-helper:' || p_conversation_id::text
      || ':session:' || split_part(p_turn_id, ':', 1)
      || ':turn:' || split_part(p_turn_id, ':', 2) || ':call:' || p_call_id;
  end if;
  if v_key is null
     or p_task_prompt is null or length(trim(p_task_prompt)) not between 1 and 10000
     or jsonb_typeof(p_resources) is distinct from 'array'
     or jsonb_typeof(p_request_resources) is distinct from 'array'
     or jsonb_typeof(p_expects) is distinct from 'array'
     or p_chat_ceiling is null
     or cardinality(p_chat_ceiling) > 1000
     or exists (select 1 from unnest(p_chat_ceiling) as n(name) where n.name is null or length(n.name) not between 1 and 100)
     or (p_areas is not null and (
       cardinality(p_areas) not between 1 and 2
       or exists (select 1 from unnest(p_areas) as a(area) where a.area is null or a.area !~ '^[a-z][a-z_]{0,39}$')
     )) then
    return jsonb_build_object('code', 'INVALID_BRIEF');
  end if;
  -- A server-started helper (337, widened by 340 and 443): a known kind, never as a named custom agent.
  if p_server_helper is not null and (p_server_helper not in ('meeting_prep', 'home_turn', 'check_in') or p_teammate_id is not null) then
    return jsonb_build_object('code', 'INVALID_BRIEF');
  end if;
  -- 443: a check-in's helper names the tracked item it retries ('<kind>:<id>',
  -- the Now file's track); no other start names one.
  if (p_server_helper = 'check_in' and (p_server_helper_item is null
        or p_server_helper_item !~ '^(work|action|pr|ask):[A-Za-z0-9][A-Za-z0-9._#/-]{0,199}$'))
     or (p_server_helper is distinct from 'check_in' and p_server_helper_item is not null) then
    return jsonb_build_object('code', 'INVALID_BRIEF');
  end if;

  if jsonb_typeof(v_policy) <> 'object'
     or coalesce(v_policy->>'mode', 'propose') not in ('off', 'propose', 'attempt') then
    return jsonb_build_object('code', 'POLICY_UNAVAILABLE');
  end if;
  if v_policy->>'mode' = 'off' then return jsonb_build_object('code', 'AUTONOMY_OFF'); end if;
  foreach v_field in array array['max_chat_delegations_per_day', 'max_chat_delegations_per_conversation'] loop
    v_value := v_policy->v_field;
    if v_value is not null then
      if jsonb_typeof(v_value) <> 'number' then return jsonb_build_object('code', 'POLICY_UNAVAILABLE'); end if;
      if (v_value::text)::numeric < 0
         or (v_value::text)::numeric > 500 or trunc((v_value::text)::numeric) <> (v_value::text)::numeric then
        return jsonb_build_object('code', 'POLICY_UNAVAILABLE');
      end if;
      if v_field = 'max_chat_delegations_per_day' then v_daily := (v_value::text)::integer;
      else v_live := (v_value::text)::integer; end if;
    end if;
  end loop;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'teammate', p_teammate_id, 'task', p_task_prompt, 'resources', p_request_resources,
    'expects', p_expects, 'areas', to_jsonb(p_areas))::text, 'UTF8')), 'hex');
  select * into v_run from public.agent_run where workspace_id = p_workspace_id and fire_key = v_key;
  if found then
    if v_run.chat_delegation_fingerprint is distinct from v_fingerprint then
      return jsonb_build_object('code', 'CALL_ID_CONFLICT');
    end if;
    return jsonb_build_object('run_id', v_run.id, 'status', v_run.status,
      'teammate_id', v_run.ai_team_member_id, 'reused', true);
  end if;

  if p_server_helper is null then
    -- Live helpers in this conversation, not every helper it ever had. A
    -- server-started helper (337) never takes one of the person's slots.
    if (select count(*) from public.agent_run where workspace_id = p_workspace_id
        and origin = 'chat' and chat_conversation_id = p_conversation_id and server_helper is null
        and status in ('queued', 'running', 'needs_input')) >= v_live then
      return jsonb_build_object('code', 'LIVE_HELPERS');
    end if;
    if (select count(*) from public.agent_run where workspace_id = p_workspace_id and origin = 'chat'
        and server_helper is null
        and created_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC')) >= v_daily then
      return jsonb_build_object('code', 'DAY_BUDGET');
    end if;
  else
    -- A server-started helper's own budget, per person in this workspace: at
    -- most v_server_live of its kind working at once (queued or running; one
    -- waiting on a question holds no slot) and, for every kind but
    -- meeting_prep (355: no daily cap, every meeting gets its prep),
    -- v_server_daily a UTC day.
    if (select count(*) from public.agent_run where workspace_id = p_workspace_id
        and origin = 'chat' and triggered_by = p_user_id and server_helper = p_server_helper
        and status in ('queued', 'running')) >= v_server_live then
      return jsonb_build_object('code', 'SERVER_LIVE');
    end if;
    -- 443: a check-in's helper, per person in this workspace: one retry per
    -- tracked item, ever; one per check-in (its turn: the key's session and
    -- turn parts); and v_check_in_daily in any 24 hours.
    if p_server_helper = 'check_in' then
      if exists (select 1 from public.agent_run where workspace_id = p_workspace_id
          and triggered_by = p_user_id and server_helper_item = p_server_helper_item) then
        return jsonb_build_object('code', 'SERVER_ITEM_RETRIED');
      end if;
      if exists (select 1 from public.agent_run where workspace_id = p_workspace_id
          and origin = 'chat' and triggered_by = p_user_id and server_helper = 'check_in'
          and created_at > now() - interval '1 day'
          and starts_with(fire_key, 'chat-helper:' || p_conversation_id::text
            || ':session:' || split_part(p_turn_id, ':', 1)
            || ':turn:' || split_part(p_turn_id, ':', 2) || ':call:')) then
        return jsonb_build_object('code', 'SERVER_TURN_BUDGET');
      end if;
      if (select count(*) from public.agent_run where workspace_id = p_workspace_id
          and origin = 'chat' and triggered_by = p_user_id and server_helper = 'check_in'
          and created_at > now() - interval '24 hours') >= v_check_in_daily then
        return jsonb_build_object('code', 'SERVER_DAY_BUDGET');
      end if;
    end if;
    if p_server_helper <> 'meeting_prep' and (select count(*) from public.agent_run where workspace_id = p_workspace_id
        and origin = 'chat' and triggered_by = p_user_id and server_helper = p_server_helper
        and created_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC')) >= v_server_daily then
      return jsonb_build_object('code', 'SERVER_DAY_BUDGET');
    end if;
  end if;

  -- A named custom agent: enabled, not a system teammate (the Assistant and
  -- the area faces are the main agent's own face), on a team the caller can
  -- see (private teams explicitly, on service role), and allowed to draft.
  if p_teammate_id is not null then
    select a.id, a.name into v_target, v_target_name
      from public.ai_team_member a join public.team t on t.id = a.team_id and t.workspace_id = p_workspace_id
      where a.id = p_teammate_id and a.workspace_id = p_workspace_id and a.autonomy <> 'off' and not a.is_system
        and (not t.is_private or exists (select 1 from public.team_member tm where tm.team_id = t.id and tm.member_id = v_member))
      for share of a, t;
    if not found then return jsonb_build_object('code', 'AGENT_NOT_FOUND'); end if;
    perform 1 from public.ai_team_member a
      where a.id = v_target and a.allowed_side_effects @> array['internal-write']::text[];
    if not found then return jsonb_build_object('code', 'AGENT_CANNOT_DRAFT'); end if;
  end if;

  -- 422: opted in to the ChatGPT free tier (409): a helper is a work run, and
  -- a work run for a person on their own ChatGPT plan runs on it.
  select allowed into v_usage from public.check_ai_usage_limit(p_user_id, true) limit 1;
  if v_usage is distinct from true then return jsonb_build_object('code', 'USAGE_LIMIT'); end if;

  insert into public.agent_run (workspace_id, kind, status, task_prompt, resources, triggered_by,
    origin, origin_depth, chat_conversation_id, chat_delegation_fingerprint, chat_ceiling,
    ai_team_member_id, fire_key, expects, helper_areas, server_helper, server_helper_item)
  values (p_workspace_id, 'workspace', 'queued', p_task_prompt, p_resources, p_user_id,
    'chat', 0, p_conversation_id, v_fingerprint, p_chat_ceiling,
    v_target, v_key, p_expects, p_areas, p_server_helper, p_server_helper_item)
  returning * into v_run;
  return jsonb_build_object('run_id', v_run.id, 'status', v_run.status,
    'teammate_id', v_target, 'teammate_name', v_target_name, 'reused', false);
end;
$_$;


ALTER FUNCTION "public"."start_chat_helper"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_turn_id" "text", "p_call_id" "text", "p_teammate_id" "uuid", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb", "p_chat_ceiling" "text"[], "p_areas" "text"[], "p_server_helper" "text", "p_server_helper_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_chat_work_delegation"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_call_id" "text", "p_role" "text", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public._admit_chat_work_delegation(
    p_workspace_id, p_user_id, p_conversation_id,
    'chat-delegate:' || p_conversation_id::text || ':' || p_call_id,
    p_call_id, p_role, p_task_prompt, p_resources, p_expects, p_request_resources, null);
$$;


ALTER FUNCTION "public"."start_chat_work_delegation"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_call_id" "text", "p_role" "text", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_chat_work_delegation"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_turn_id" "text", "p_call_id" "text", "p_role" "text", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb", "p_chat_ceiling" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  select public._admit_chat_work_delegation(
    p_workspace_id, p_user_id, p_conversation_id,
    case
      when p_chat_ceiling is null or p_turn_id is null then null
      when p_turn_id ~ '^[^:]{1,200}:[^:]{1,200}$'
        then 'chat-delegate:' || p_conversation_id::text
          || ':session:' || split_part(p_turn_id, ':', 1)
          || ':turn:' || split_part(p_turn_id, ':', 2) || ':call:' || p_call_id
      when p_turn_id ~ '^[^:]{1,200}$'
        then 'chat-delegate:' || p_conversation_id::text || ':turn:' || p_turn_id || ':call:' || p_call_id
    end,
    p_call_id, p_role, p_task_prompt, p_resources, p_expects, p_request_resources, p_chat_ceiling);
$_$;


ALTER FUNCTION "public"."start_chat_work_delegation"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_turn_id" "text", "p_call_id" "text", "p_role" "text", "p_task_prompt" "text", "p_resources" "jsonb", "p_expects" "jsonb", "p_request_resources" "jsonb", "p_chat_ceiling" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_quote_intake_key"("p_workspace_id" "uuid", "p_key_hash" "text", "p_key_prefix" "text", "p_allowed_origins" "text"[], "p_created_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  -- Already live (a retried swap): nothing to do.
  if exists (select 1 from public.quote_intake_key where key_hash = p_key_hash and revoked_at is null) then
    return;
  end if;
  update public.quote_intake_key set revoked_at = now() where workspace_id = p_workspace_id and revoked_at is null;
  insert into public.quote_intake_key (workspace_id, key_hash, key_prefix, allowed_origins, created_by)
  values (p_workspace_id, p_key_hash, p_key_prefix, coalesce(p_allowed_origins, '{}'), p_created_by);
end;
$$;


ALTER FUNCTION "public"."swap_quote_intake_key"("p_workspace_id" "uuid", "p_key_hash" "text", "p_key_prefix" "text", "p_allowed_origins" "text"[], "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."swap_quote_intake_key"("p_workspace_id" "uuid", "p_key_hash" "text", "p_key_prefix" "text", "p_allowed_origins" "text"[], "p_created_by" "uuid") IS 'A website wiring change merged (463): revoke the workspace''s live quote intake key and make the wiring''s key live, in one transaction.';


CREATE OR REPLACE FUNCTION "public"."team_keep_system_teammates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target uuid;
begin
  -- The workspace is going (its cascade reached this team): let it.
  if not exists (select 1 from public.workspace w where w.id = old.workspace_id) then
    return old;
  end if;

  if not exists (
    select 1 from public.ai_team_member a
    where a.team_id = old.id and a.is_system
  ) then
    return old;
  end if;

  select t.id into v_target
  from public.team t
  where t.workspace_id = old.workspace_id
    and t.id <> old.id
  order by t.created_at asc, t.id asc
  limit 1;

  if v_target is null then
    raise exception 'a workspace keeps one team for its system teammates: create another team before deleting this one (team %)', old.id
      using errcode = 'restrict_violation',
            hint = 'Delete the workspace instead, or create another team first.';
  end if;

  update public.ai_team_member
  set team_id = v_target
  where team_id = old.id and is_system;

  return old;
end;
$$;


ALTER FUNCTION "public"."team_keep_system_teammates"() OWNER TO "postgres";


