CREATE OR REPLACE FUNCTION "public"."track_device_activity"("p_user_id" "uuid", "p_device_id" "text", "p_device_model" "text" DEFAULT NULL::"text", "p_os_version" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- First, ensure device exists in devices table
    INSERT INTO devices (device_id, device_model, os_version, app_version)
    VALUES (p_device_id, p_device_model, p_os_version, p_app_version)
    ON CONFLICT (device_id) DO UPDATE SET
        device_model = COALESCE(EXCLUDED.device_model, devices.device_model),
        os_version = COALESCE(EXCLUDED.os_version, devices.os_version),
        app_version = COALESCE(EXCLUDED.app_version, devices.app_version),
        updated_at = NOW();
    
    -- Then, update or insert user-device association
    INSERT INTO user_devices (user_id, device_id, device_model, os_version, app_version)
    VALUES (p_user_id, p_device_id, p_device_model, p_os_version, p_app_version)
    ON CONFLICT (user_id, device_id) DO UPDATE SET
        last_active_at = NOW(),
        device_model = COALESCE(EXCLUDED.device_model, user_devices.device_model),
        os_version = COALESCE(EXCLUDED.os_version, user_devices.os_version),
        app_version = COALESCE(EXCLUDED.app_version, user_devices.app_version),
        updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."track_device_activity"("p_user_id" "uuid", "p_device_id" "text", "p_device_model" "text", "p_os_version" "text", "p_app_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_device_purchases_to_user"("p_device_id" "text", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Update all device purchases to be associated with the user
    UPDATE purchases 
    SET user_id = p_user_id,
        device_id = NULL
    WHERE device_id = p_device_id
    AND user_id IS NULL;
    
    -- Update the device record
    UPDATE devices 
    SET user_id = p_user_id
    WHERE device_id = p_device_id;
END;
$$;


ALTER FUNCTION "public"."transfer_device_purchases_to_user"("p_device_id" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unified_search"("p_workspace_id" "uuid", "p_query" "text", "p_types" "text"[] DEFAULT ARRAY['action'::"text", 'capture'::"text", 'document'::"text", 'project'::"text", 'decision'::"text", 'claim'::"text"], "p_limit" integer DEFAULT 20, "p_requesting_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("result_type" "text", "result_id" "uuid", "title" "text", "subtitle" "text", "icon" "text", "rank" real, "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_tsquery tsquery;
  v_identifier_pattern text;
  v_is_identifier bool;
  v_requester uuid := public._resolve_visibility_requester(p_requesting_user_id);
  v_requester_member uuid;
BEGIN
  -- Membership gate (275): enforced whenever the requester is KNOWN — whether
  -- it came from the JWT or from an explicit p_requesting_user_id — not only
  -- when a JWT happens to be present. A sessionless caller that asserts no
  -- requester at all sees workspace-visible rows only, and is trusted to
  -- scope itself (service-role already has the whole database).
  IF v_requester IS NOT NULL AND NOT public._is_member_of(v_requester, p_workspace_id) THEN
    RETURN;
  END IF;

  -- 369: the requester's member row here, for the private-document rule
  -- (a private document is its creator's alone; no admin override).
  IF v_requester IS NOT NULL THEN
      SELECT m.id INTO v_requester_member
        FROM public.member m
       WHERE m.workspace_id = p_workspace_id AND m.user_id = v_requester
       LIMIT 1;
  END IF;

  v_is_identifier := p_query ~ '^[A-Za-z]+-[0-9]+$';
  v_identifier_pattern := upper(p_query) || '%';

  BEGIN
    v_tsquery := websearch_to_tsquery('english', p_query);
  EXCEPTION WHEN OTHERS THEN
    v_tsquery := NULL;
  END;

  IF v_tsquery IS NULL AND NOT v_is_identifier THEN
    RETURN;
  END IF;

  RETURN QUERY

  SELECT
    'action'::text AS result_type,
    a.id AS result_id,
    a.title,
    COALESCE(ws.name, '') AS subtitle,
    a.identifier AS icon,
    CASE
      WHEN v_is_identifier AND upper(a.identifier) LIKE v_identifier_pattern THEN 2.0
      WHEN v_tsquery IS NOT NULL THEN ts_rank(a.fts, v_tsquery)
      ELSE 0.0
    END AS rank,
    jsonb_build_object(
      'identifier', a.identifier,
      'status_id', a.status_id,
      'status_name', ws.name,
      'priority', a.priority,
      'assignee_id', a.assignee_id,
      'team_id', a.team_id
    ) AS metadata
  FROM public.actions a
  JOIN public.team t ON t.id = a.team_id
  LEFT JOIN public.workflow_state ws ON ws.id = a.status_id
  WHERE t.workspace_id = p_workspace_id
    AND 'action' = ANY(p_types)
    AND (
      (v_is_identifier AND upper(a.identifier) LIKE v_identifier_pattern)
      OR (v_tsquery IS NOT NULL AND a.fts @@ v_tsquery)
    )

  UNION ALL

  SELECT
    'capture'::text,
    c.id,
    c.title,
    'Capture'::text AS subtitle,
    ''::text AS icon,
    CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(c.fts, v_tsquery) ELSE 0.0 END AS rank,
    jsonb_build_object(
      'started_at', c.started_at,
      'duration_seconds', c.duration_seconds
    ) AS metadata
  FROM public.captures c
  WHERE c.workspace_id = p_workspace_id
    AND 'capture' = ANY(p_types)
    AND NOT c.is_eval
    AND v_tsquery IS NOT NULL
    AND c.fts @@ v_tsquery
    AND (c.visibility = 'workspace' OR (v_requester IS NOT NULL AND c.user_id = v_requester))

  UNION ALL

  SELECT
    'document'::text,
    d.id,
    d.title,
    'Document' AS subtitle,
    '' AS icon,
    CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(d.fts, v_tsquery) ELSE 0.0 END AS rank,
    jsonb_build_object(
      'status', d.status,
      'project_id', d.project_id,
      'is_pinned', d.is_pinned
    ) AS metadata
  FROM public.document d
  WHERE d.workspace_id = p_workspace_id
    AND 'document' = ANY(p_types)
    AND v_tsquery IS NOT NULL
    AND d.fts @@ v_tsquery
    AND (d.visibility = 'workspace' OR (v_requester_member IS NOT NULL AND d.created_by = v_requester_member))

  UNION ALL

  SELECT
    'project'::text,
    p.id,
    p.name AS title,
    COALESCE(p.status::text, 'active') AS subtitle,
    '' AS icon,
    CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(p.fts, v_tsquery) ELSE 0.0 END AS rank,
    jsonb_build_object(
      'status', p.status,
      'lead_id', p.lead_id
    ) AS metadata
  FROM public.projects p
  WHERE p.workspace_id = p_workspace_id
    AND 'project' = ANY(p_types)
    AND v_tsquery IS NOT NULL
    AND p.fts @@ v_tsquery

  UNION ALL

  SELECT
    'decision'::text,
    dec.id,
    LEFT(dec.content, 100) AS title,
    'Decision' AS subtitle,
    '' AS icon,
    CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(dec.fts, v_tsquery) ELSE 0.0 END AS rank,
    jsonb_build_object(
      'capture_id', dec.capture_id,
      'confirmation', dec.confirmation,
      'project_id', dec.project_id
    ) AS metadata
  FROM public.decision dec
  JOIN public.captures c ON c.id = dec.capture_id
  WHERE c.workspace_id = p_workspace_id
    AND 'decision' = ANY(p_types)
    AND NOT c.is_eval
    AND v_tsquery IS NOT NULL
    AND dec.fts @@ v_tsquery
    AND (c.visibility = 'workspace'
         OR (v_requester IS NOT NULL AND c.user_id = v_requester)
         OR dec.confirmation = 'confirmed')

  UNION ALL

  SELECT
    'claim'::text,
    cl.id,
    LEFT(cl.text, 100) AS title,
    'Claim' AS subtitle,
    cl.type AS icon,
    CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(cl.fts, v_tsquery) ELSE 0.0 END AS rank,
    jsonb_build_object(
      'type', cl.type,
      'confirmation', cl.confirmation,
      'status', cl.status,
      'confidence', cl.confidence
    ) AS metadata
  FROM public.claim cl
  WHERE cl.workspace_id = p_workspace_id
    AND 'claim' = ANY(p_types)
    AND cl.status = 'active'
    AND cl.confirmation <> 'dismissed'
    AND v_tsquery IS NOT NULL
    AND cl.fts @@ v_tsquery
    AND public.claim_visible_to(cl.id, v_requester)

  ORDER BY rank DESC
  LIMIT p_limit;
END;
$_$;


ALTER FUNCTION "public"."unified_search"("p_workspace_id" "uuid", "p_query" "text", "p_types" "text"[], "p_limit" integer, "p_requesting_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unmerge_contacts"("p_merge_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_m public.contact_merge%ROWTYPE;
  v_snap jsonb;
  v_moved jsonb;
  v_source_emails text[];
BEGIN
  SELECT * INTO v_m FROM public.contact_merge WHERE id = p_merge_id FOR UPDATE;
  IF v_m.id IS NULL THEN
    RAISE EXCEPTION 'Merge % not found', p_merge_id;
  END IF;
  IF v_m.undone_at IS NOT NULL THEN
    RAISE EXCEPTION 'Merge % was already undone', p_merge_id;
  END IF;
  IF v_m.source_contact_id IS NULL OR v_m.target_contact_id IS NULL THEN
    RAISE EXCEPTION 'Merge % is missing its source or target (deleted contact)', p_merge_id;
  END IF;

  v_snap := v_m.source_snapshot;
  v_moved := v_m.moved;

  v_source_emails := ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_snap->'secondary_emails', '[]'::jsonb))
  );

  UPDATE public.contact SET
    email                  = NULLIF(v_snap->>'email', ''),
    secondary_emails       = v_source_emails,
    merged_into_contact_id = NULL,
    updated_at             = now()
  WHERE id = v_m.source_contact_id;

  UPDATE public.contact t SET
    secondary_emails = (
      SELECT COALESCE(array_agg(e), '{}')
      FROM unnest(COALESCE(t.secondary_emails, '{}')) AS e
      WHERE e IS DISTINCT FROM NULLIF(v_snap->>'email', '')
        AND NOT (e = ANY(v_source_emails))
    ),
    updated_at = now()
  WHERE t.id = v_m.target_contact_id;

  UPDATE public.capture_participant SET contact_id = v_m.source_contact_id
    WHERE id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'capture_participant_ids', '[]'::jsonb)))::uuid));
  UPDATE public.contact_interaction SET contact_id = v_m.source_contact_id
    WHERE id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'contact_interaction_ids', '[]'::jsonb)))::uuid));
  UPDATE public.email_thread_index SET linked_contact_id = v_m.source_contact_id
    WHERE id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'email_thread_ids', '[]'::jsonb)))::uuid));
  UPDATE public.voice_enrollment SET contact_id = v_m.source_contact_id
    WHERE id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'voice_enrollment_ids', '[]'::jsonb)))::uuid));
  UPDATE public.comment SET commentable_id = v_m.source_contact_id
    WHERE commentable_type = 'contact'
      AND id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'comment_ids', '[]'::jsonb)))::uuid));
  UPDATE public.contact_share SET contact_id = v_m.source_contact_id
    WHERE id = ANY(ARRAY(SELECT (jsonb_array_elements_text(COALESCE(v_moved->'contact_share_ids', '[]'::jsonb)))::uuid));

  UPDATE public.contact_merge SET undone_at = now() WHERE id = p_merge_id;

  RETURN v_m.source_contact_id;
END;
$$;


ALTER FUNCTION "public"."unmerge_contacts"("p_merge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unsnooze_action"("p_user_id" "uuid", "p_action_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE actions
    SET
        snoozed_until = NULL,
        updated_at = NOW()
    WHERE id = p_action_id AND user_id = p_user_id;
    RETURN FOUND;
END;
$$;


