    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "device_id" "text",
    "title" "text" NOT NULL,
    "description" "text",
    "due_at" timestamp with time zone,
    "all_day" boolean DEFAULT false,
    "timezone" "text" DEFAULT 'UTC'::"text",
    "recurrence_rule" "text",
    "parent_action_id" "uuid",
    "completed_at" timestamp with time zone,
    "snoozed_until" timestamp with time zone,
    "color" "text",
    "ai_confidence" real DEFAULT 1.0,
    "original_transcript" "text",
    "context_source" "text",
    "context_data" "jsonb" DEFAULT '{}'::"jsonb",
    "embedding" "public"."vector"(1536),
    "notification_identifier" "text",
    "notification_scheduled" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "sort_order" integer DEFAULT 0 NOT NULL,
    "links" "jsonb" DEFAULT '[]'::"jsonb",
    "agent_thread_id" "uuid",
    "agent_status" "text" DEFAULT 'disabled'::"text",
    "last_agent_activity" timestamp with time zone,
    "owner_entity_id" "uuid",
    "assigned_to_user" boolean DEFAULT true,
    "is_dismissed" boolean DEFAULT false,
    "dismissed_reason" "text",
    "dismissed_at" timestamp with time zone,
    "source_type" "text" DEFAULT 'user'::"text",
    "source_capture_id" "uuid",
    "assignee_name" "text",
    "assignee_email" "text",
    "assignee_contact_id" "uuid",
    "assignees" "jsonb" DEFAULT '[]'::"jsonb",
    "urgency_score" integer,
    "importance_score" integer,
    "project_entity_id" "uuid",
    "related_entity_ids" "uuid"[],
    "last_reminder_at" timestamp with time zone,
    "reminder_count" integer DEFAULT 0,
    "source_suggestion_id" "uuid",
    "workspace_id" "uuid" NOT NULL,
    "team_id" "uuid" NOT NULL,
    "status_id" "uuid" NOT NULL,
    "confirmation" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "identifier" "text" NOT NULL,
    "assignee_id" "uuid",
    "parent_id" "uuid",
    "priority" "public"."action_priority" DEFAULT 'none'::"public"."action_priority" NOT NULL,
    "estimate" real,
    "project_id" "uuid",
    "milestone_id" "uuid",
    "cycle_id" "uuid",
    "fts" "tsvector" GENERATED ALWAYS AS ((("setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("identifier", ''::"text")), 'A'::"char") || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("title", ''::"text")), 'A'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("description", ''::"text")), 'B'::"char"))) STORED,
    "dismiss_reason" "text",
    "auto_accepted" boolean DEFAULT false NOT NULL,
    "assignee_ai_member_id" "uuid",
    "agent_run_status" "text" DEFAULT 'idle'::"text" NOT NULL,
    "previous_identifier" "text",
    CONSTRAINT "actions_agent_run_status_check" CHECK (("agent_run_status" = ANY (ARRAY['idle'::"text", 'starting'::"text", 'working'::"text", 'needs_input'::"text", 'pr_open'::"text", 'failed'::"text"]))),
    CONSTRAINT "actions_agent_status_check" CHECK (("agent_status" = ANY (ARRAY['disabled'::"text", 'pending'::"text", 'analyzing'::"text", 'working'::"text", 'awaiting_approval'::"text", 'approved'::"text", 'paused'::"text", 'completed'::"text", 'error'::"text"]))),
    CONSTRAINT "actions_confirmation_check" CHECK (("confirmation" = ANY (ARRAY['suggested'::"text", 'confirmed'::"text", 'dismissed'::"text"]))),
    CONSTRAINT "actions_importance_score_check" CHECK ((("importance_score" >= 0) AND ("importance_score" <= 100))),
    CONSTRAINT "actions_source_type_check" CHECK (("source_type" = ANY (ARRAY['user'::"text", 'meeting_extraction'::"text", 'chat_suggestion'::"text", 'stt_extraction'::"text", 'insight_suggestion'::"text"]))),
    CONSTRAINT "actions_urgency_score_check" CHECK ((("urgency_score" >= 0) AND ("urgency_score" <= 100)))
);

ALTER TABLE ONLY "public"."actions" REPLICA IDENTITY FULL;


ALTER TABLE "public"."actions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."actions"."snoozed_until" IS 'Deferral timestamp (orthogonal to status - action can be in_progress AND snoozed)';


COMMENT ON COLUMN "public"."actions"."owner_entity_id" IS 'Future FK to insights_entities for delegation tracking';


COMMENT ON COLUMN "public"."actions"."assigned_to_user" IS 'TRUE = my action, FALSE = tracking someone else''s action';


COMMENT ON COLUMN "public"."actions"."is_dismissed" IS 'TRUE if user dismissed an AI suggestion as wrong/not relevant';


COMMENT ON COLUMN "public"."actions"."source_type" IS 'Origin: user, meeting_extraction, chat_suggestion, stt_extraction';


COMMENT ON COLUMN "public"."actions"."source_capture_id" IS 'Reference to the note this action was extracted from (for meeting_extraction source_type)';


COMMENT ON COLUMN "public"."actions"."assignee_name" IS 'Display name of the person assigned to this action (from meeting participant or manual entry)';


COMMENT ON COLUMN "public"."actions"."assignee_email" IS 'Email of the person assigned to this action (for identification and deduplication)';


COMMENT ON COLUMN "public"."actions"."assignee_contact_id" IS 'Link to CRM contact if the assignee exists in contacts';


COMMENT ON COLUMN "public"."actions"."assignees" IS 'Array of assignee objects: [{id: UUID, name: string, email?: string, contact_id?: UUID}]';


COMMENT ON COLUMN "public"."actions"."urgency_score" IS 'AI-derived urgency score 0-100 (from context_data.why.urgency_driver)';


COMMENT ON COLUMN "public"."actions"."importance_score" IS 'AI-derived importance score 0-100 (from context_data.why.stakes)';


COMMENT ON COLUMN "public"."actions"."project_entity_id" IS 'Link to insights_entities for project tracking';


COMMENT ON COLUMN "public"."actions"."related_entity_ids" IS 'Array of related entity IDs for cross-referencing';


COMMENT ON COLUMN "public"."actions"."last_reminder_at" IS 'When the last staleness reminder was generated';


COMMENT ON COLUMN "public"."actions"."reminder_count" IS 'Number of staleness reminders generated for this action';


CREATE TABLE IF NOT EXISTS "public"."agent_event" (
    "id" bigint NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "source" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "priority" smallint DEFAULT 1 NOT NULL,
    "occurs_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone,
    "ref_type" "text",
    "ref_id" "text",
    "facts" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "state" "text" DEFAULT 'new'::"text" NOT NULL,
    "outcome" "text",
    "decided_by" "text",
    "jev_shadow" "jsonb",
    "notification_id" "uuid",
    "home_turn_id" "uuid",
    "routed_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "delivered_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "agent_event_decided_by_check" CHECK ((("decided_by" IS NULL) OR ("decided_by" = ANY (ARRAY['rule'::"text", 'jev'::"text"])))),
    CONSTRAINT "agent_event_dedupe_key_check" CHECK ((("char_length"("dedupe_key") >= 1) AND ("char_length"("dedupe_key") <= 300))),
    CONSTRAINT "agent_event_delivered_key_check" CHECK ((("delivered_key" IS NULL) OR (("char_length"("delivered_key") >= 1) AND ("char_length"("delivered_key") <= 200)))),
    CONSTRAINT "agent_event_facts_check" CHECK ((("jsonb_typeof"("facts") = 'object'::"text") AND ("octet_length"(("facts")::"text") <= 4000))),
    CONSTRAINT "agent_event_jev_shadow_check" CHECK ((("jev_shadow" IS NULL) OR (("jsonb_typeof"("jev_shadow") = 'object'::"text") AND ("octet_length"(("jev_shadow")::"text") <= 2000)))),
    CONSTRAINT "agent_event_kind_check" CHECK (("kind" = ANY (ARRAY['email.drafted'::"text", 'email.needs_reply'::"text", 'email.suspicious'::"text", 'capture.processed'::"text", 'meeting.soon'::"text", 'work.needs_input'::"text", 'work.needs_review'::"text", 'work.approval'::"text", 'work.done'::"text", 'work.failed'::"text", 'mention'::"text", 'activity'::"text", 'reminder.due'::"text", 'contact.followup_due'::"text", 'sequence.failed'::"text", 'meeting.changed'::"text", 'email.arrived'::"text", 'pr.changed'::"text", 'connection.needs_reconnect'::"text", 'quote.received'::"text", 'job.paid'::"text"]))),
    CONSTRAINT "agent_event_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['ignore'::"text", 'quiet'::"text", 'turn'::"text", 'notify'::"text"])))),
    CONSTRAINT "agent_event_outcome_state_check" CHECK ((("state" = 'new'::"text") = ("outcome" IS NULL))),
    CONSTRAINT "agent_event_priority_check" CHECK ((("priority" >= 0) AND ("priority" <= 3))),
    CONSTRAINT "agent_event_ref_check" CHECK (((("ref_type" IS NULL) OR ("char_length"("ref_type") <= 40)) AND (("ref_id" IS NULL) OR ("char_length"("ref_id") <= 300)))),
    CONSTRAINT "agent_event_source_check" CHECK (("source" = ANY (ARRAY['email'::"text", 'capture'::"text", 'meeting'::"text", 'work'::"text", 'mention'::"text", 'digest'::"text", 'reminder'::"text", 'crm'::"text"]))),
    CONSTRAINT "agent_event_state_check" CHECK (("state" = ANY (ARRAY['new'::"text", 'routed'::"text", 'delivered'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."agent_event" OWNER TO "postgres";


COMMENT ON TABLE "public"."agent_event" IS 'The agent''s inbox (336, A6): one row per thing that happened for one user in one workspace (a draft, a processed meeting, work waiting on them or failed, a meeting about to start, a mention), routed to ignore, quiet, turn or notify. Server-written only.';


COMMENT ON COLUMN "public"."agent_event"."facts" IS 'Templated facts (a clipped title or subject, counts, flags), never a body.';


COMMENT ON COLUMN "public"."agent_event"."jev_shadow" IS 'Jev event.needs_person in shadow: the pick (now, digest or ignore) and its probability. Stored, never applied.';


COMMENT ON COLUMN "public"."agent_event"."delivered_key" IS 'What delivered the row (away:<message id>, or a digest key): a retried build re-reads the same rows.';


