CREATE TABLE IF NOT EXISTS "public"."agent_guest" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "display_name" "text" NOT NULL,
    "phone_e164" "text",
    "preset" "text" NOT NULL,
    "tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "ask_before" "text"[] DEFAULT '{payments,deletes}'::"text"[] NOT NULL,
    "notes" "text",
    "state" "text" DEFAULT 'invited'::"text" NOT NULL,
    "invite_code_hash" "text",
    "invite_expires_at" timestamp with time zone,
    "requested_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "removed_at" timestamp with time zone,
    "opted_out_at" timestamp with time zone,
    "last_inbound_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ask_tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "channels" "text"[] DEFAULT '{sms}'::"text"[] NOT NULL,
    "phone_bound_at" timestamp with time zone,
    "slack_team_id" "text",
    "slack_user_id" "text",
    "peer_user_id" "uuid",
    "peer_bound_at" timestamp with time zone,
    "calendar_emails" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "business_number_id" "uuid",
    "contact_id" "uuid",
    CONSTRAINT "agent_guest_ask_before_check" CHECK (("ask_before" <@ ARRAY['payments'::"text", 'deletes'::"text", 'changes'::"text"])),
    CONSTRAINT "agent_guest_ask_tools_cap" CHECK (("cardinality"("ask_tools") <= 400)),
    CONSTRAINT "agent_guest_ask_tools_held" CHECK (("ask_tools" <@ "tools")),
    CONSTRAINT "agent_guest_calendar_emails_max" CHECK (("cardinality"("calendar_emails") <= 5)),
    CONSTRAINT "agent_guest_channels_check" CHECK ((("cardinality"("channels") >= 1) AND ("channels" <@ ARRAY['sms'::"text", 'slack'::"text", 'dial8'::"text"]))),
    CONSTRAINT "agent_guest_dial8_has_peer" CHECK ((("peer_user_id" IS NOT NULL) OR ("state" = 'invited'::"text") OR (NOT ('dial8'::"text" = ANY ("channels"))))),
    CONSTRAINT "agent_guest_display_name_length" CHECK ((("char_length"("btrim"("display_name")) >= 1) AND ("char_length"("btrim"("display_name")) <= 80))),
    CONSTRAINT "agent_guest_notes_length" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 2000))),
    CONSTRAINT "agent_guest_phone_shape" CHECK (("phone_e164" ~ '^[+][1-9][0-9]{7,14}$'::"text")),
    CONSTRAINT "agent_guest_preset_check" CHECK (("preset" = ANY (ARRAY['household'::"text", 'colleague'::"text", 'custom'::"text", 'customer'::"text"]))),
    CONSTRAINT "agent_guest_removed_has_no_invite" CHECK ((("state" <> 'removed'::"text") OR ("invite_code_hash" IS NULL))),
    CONSTRAINT "agent_guest_slack_pair" CHECK ((("slack_team_id" IS NULL) = ("slack_user_id" IS NULL))),
    CONSTRAINT "agent_guest_state_check" CHECK (("state" = ANY (ARRAY['invited'::"text", 'requested'::"text", 'active'::"text", 'removed'::"text"]))),
    CONSTRAINT "agent_guest_text_has_phone" CHECK ((("phone_e164" IS NOT NULL) OR (NOT ('sms'::"text" = ANY ("channels"))))),
    CONSTRAINT "agent_guest_tools_size" CHECK (("cardinality"("tools") <= 64))
);


ALTER TABLE "public"."agent_guest" OWNER TO "postgres";


COMMENT ON TABLE "public"."agent_guest" IS 'A person who may text the owner''s agent and the agent made for them (427). The owner reads their own rows; only the service role writes.';


COMMENT ON COLUMN "public"."agent_guest"."preset" IS 'The preset the owner started from: household, colleague, or custom once they changed the tools (src/lib/guests/presets.ts).';


COMMENT ON COLUMN "public"."agent_guest"."tools" IS 'The tools this person''s agent may hold, by name. Read through the guest ceiling, which drops any name it does not offer guests.';


COMMENT ON COLUMN "public"."agent_guest"."ask_before" IS 'What always waits for the owner''s yes: payments, deletes, changes (any write). Outward calls always do.';


COMMENT ON COLUMN "public"."agent_guest"."notes" IS 'The owner''s own notes for this person''s agent (the only thing about the owner it reads beyond its tools).';


COMMENT ON COLUMN "public"."agent_guest"."invite_code_hash" IS 'HMAC of the one-time invite code, bound to this row and phone. Cleared when it is used or the person is removed.';


COMMENT ON COLUMN "public"."agent_guest"."opted_out_at" IS 'Set when the person texted STOP. Nothing is texted to them while set.';


COMMENT ON COLUMN "public"."agent_guest"."ask_tools" IS 'The held tools (a subset of tools) whose every call waits for the owner''s yes: Needs approval (429). A tool in tools and not here is Always allow; a tool not in tools is Blocked.';


COMMENT ON COLUMN "public"."agent_guest"."channels" IS 'Where this person reaches the owner''s agent: sms (Text), slack (Slack), or both (430). A text from their number, or a DM from their Slack account, reaches their agent only on a channel listed here.';


COMMENT ON COLUMN "public"."agent_guest"."slack_user_id" IS 'The Slack account (with slack_team_id) this guest reaches the agent from, bound when they first DM the Dial8 bot with their invite (430).';


COMMENT ON COLUMN "public"."agent_guest"."peer_user_id" IS 'The Dial8 user this person is, for the dial8 channel (their agent, 431). This row is the owner''s half of the link: what that user''s agent may ask the owner''s.';


COMMENT ON COLUMN "public"."agent_guest"."peer_bound_at" IS 'When the link with peer_user_id went active (431). Until then their agent reaches nothing.';


COMMENT ON COLUMN "public"."agent_guest"."calendar_emails" IS 'The addresses this person''s calendar invites come from, as the owner listed them (455): trimmed, lower case, deduped, at most 5. An active guest''s addresses count as the owner''s trusted people for meeting prep and the look-ahead.';


COMMENT ON COLUMN "public"."agent_guest"."business_number_id" IS 'A customer (preset customer, 458): the business number they texted. Their replies go out from it.';


COMMENT ON COLUMN "public"."agent_guest"."contact_id" IS 'A customer (458): their CRM contact, when one is known.';


