    CONSTRAINT "agent_proposals_feedback_type_check" CHECK (("feedback_type" = ANY (ARRAY['too_long'::"text", 'too_short'::"text", 'wrong_tone'::"text", 'missing_info'::"text", 'incorrect_info'::"text", 'other'::"text"]))),
    CONSTRAINT "agent_proposals_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'modified'::"text"]))),
    CONSTRAINT "agent_proposals_type_check" CHECK (("type" = ANY (ARRAY['draft'::"text", 'plan'::"text", 'execution'::"text", 'question'::"text", 'completion'::"text"])))
);


