CREATE TABLE IF NOT EXISTS "public"."agent_run" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "action_id" "uuid",
    "ai_team_member_id" "uuid",
    "triggered_by" "uuid",
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "sandbox_id" "text",
    "repo_full_name" "text",
    "pr_url" "text",
    "branch" "text",
    "error_message" "text",
    "log_tail" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "task_prompt" "text",
    "agent_recipe_id" "uuid",
    "flow_id" "uuid",
    "fire_key" "text",
    "kind" "text" DEFAULT 'coding'::"text" NOT NULL,
    "attention_item_id" "uuid",
    "proposal_id" "uuid",
    "result_summary" "text",
    "deliverables" "jsonb",
    "resources" "jsonb",
    "session_state" "jsonb",
    "pending_input" "jsonb",
    "origin" "text" DEFAULT 'user'::"text" NOT NULL,
    "origin_depth" integer DEFAULT 0 NOT NULL,
    "parent_run_id" "uuid",
    "root_run_id" "uuid",
    "expects" "jsonb",
    "chat_conversation_id" "uuid",
    "chat_delegation_fingerprint" "text",
    "chat_ceiling" "text"[],
    "helper_areas" "text"[],
    "server_helper" "text",
    "model_tier" "text",
    "model_tier_by" "text",
    "outside_reads" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "precheck" "jsonb",
    "acceptance_criteria" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "review_trail" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "ci_fix_of_run_id" "uuid",
    "ci_failure" "jsonb",
    "ci_fix_trail" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "environment_id" "uuid",
    "server_helper_item" "text",
    "base_branch" "text",
    "helper_model" "text",
    CONSTRAINT "agent_run_deliverables_is_array" CHECK ((("deliverables" IS NULL) OR ("jsonb_typeof"("deliverables") = 'array'::"text"))),
    CONSTRAINT "agent_run_expects_is_array" CHECK ((("expects" IS NULL) OR ("jsonb_typeof"("expects") = 'array'::"text"))),
    CONSTRAINT "agent_run_has_origin" CHECK ((("action_id" IS NOT NULL) OR ("flow_id" IS NOT NULL) OR ("parent_run_id" IS NOT NULL) OR (("origin" = 'chat'::"text") AND ("chat_conversation_id" IS NOT NULL)))),
    CONSTRAINT "agent_run_helper_areas_shape" CHECK ((("helper_areas" IS NULL) OR (("cardinality"("helper_areas") >= 1) AND ("cardinality"("helper_areas") <= 2) AND ("origin" = 'chat'::"text")))),
    CONSTRAINT "agent_run_helper_model_check" CHECK (("helper_model" = ANY (ARRAY['flash'::"text", 'flash-thinking'::"text", 'haiku'::"text", 'gpt-luna'::"text", 'sonnet'::"text", 'gpt-terra'::"text", 'opus'::"text"]))),
    CONSTRAINT "agent_run_kind_check" CHECK (("kind" = ANY (ARRAY['coding'::"text", 'workspace'::"text"]))),
    CONSTRAINT "agent_run_model_tier_by_check" CHECK (("model_tier_by" = ANY (ARRAY['rule'::"text", 'jev'::"text", 'timeout'::"text", 'cap'::"text", 'fixed'::"text", 'agent'::"text"]))),
    CONSTRAINT "agent_run_model_tier_check" CHECK (("model_tier" = ANY (ARRAY['fast'::"text", 'think'::"text", 'strong'::"text"]))),
    CONSTRAINT "agent_run_origin_check" CHECK (("origin" = ANY (ARRAY['user'::"text", 'loop'::"text", 'attempt'::"text", 'delegation'::"text", 'chat'::"text"]))),
    CONSTRAINT "agent_run_origin_depth_check" CHECK (("origin_depth" >= 0)),
    CONSTRAINT "agent_run_pending_input_is_object" CHECK ((("pending_input" IS NULL) OR ("jsonb_typeof"("pending_input") = 'object'::"text"))),
    CONSTRAINT "agent_run_resources_is_array" CHECK ((("resources" IS NULL) OR ("jsonb_typeof"("resources") = 'array'::"text"))),
    CONSTRAINT "agent_run_server_helper_item_shape" CHECK (((("server_helper_item" IS NULL) AND ("server_helper" IS DISTINCT FROM 'check_in'::"text")) OR (("server_helper" = 'check_in'::"text") AND ("server_helper_item" IS NOT NULL) AND ("server_helper_item" ~ '^(work|action|pr|ask):[A-Za-z0-9][A-Za-z0-9._#/-]{0,199}$'::"text")))),
    CONSTRAINT "agent_run_server_helper_shape" CHECK ((("server_helper" IS NULL) OR (("server_helper" = ANY (ARRAY['meeting_prep'::"text", 'home_turn'::"text", 'check_in'::"text"])) AND ("origin" = 'chat'::"text")))),
    CONSTRAINT "agent_run_session_state_is_object" CHECK ((("session_state" IS NULL) OR ("jsonb_typeof"("session_state") = 'object'::"text"))),
    CONSTRAINT "agent_run_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'needs_input'::"text", 'canceling'::"text", 'pr_open'::"text", 'completed'::"text", 'failed'::"text", 'canceled'::"text"])))
);

ALTER TABLE ONLY "public"."agent_run" REPLICA IDENTITY FULL;


ALTER TABLE "public"."agent_run" OWNER TO "postgres";


COMMENT ON COLUMN "public"."agent_run"."task_prompt" IS 'Flow-origin runs only (action_id NULL): the fully-rendered task text built by the run_agent flow executor. NULL for action-origin runs, which derive their prompt from the action.';


COMMENT ON COLUMN "public"."agent_run"."agent_recipe_id" IS 'Flow-origin runs only: the config-picked agent recipe (category ''agent'') whose persona the run uses. NULL for action-origin runs, which resolve the persona from ai_team_member_id.';


COMMENT ON COLUMN "public"."agent_run"."fire_key" IS 'Exactly-once flow-dispatch key (`${fireId}:${flowActionId}`); NULL for non-flow runs. Unique — a step-retry insert hits 23505 and reuses the existing run.';


COMMENT ON COLUMN "public"."agent_run"."origin" IS 'user (a person pressed Start) | loop (a flow''s run_agent action) | attempt (the auto-attempt gate, B PR 3) | delegation (delegate_work). Every existing row is user.';


COMMENT ON COLUMN "public"."agent_run"."origin_depth" IS 'Chain depth: 0 for a run a person or loop started; a delegated child is parent + 1. The policy''s max_delegation_depth is enforced against it.';


COMMENT ON COLUMN "public"."agent_run"."parent_run_id" IS 'The delegating run, for a delegated child.';


COMMENT ON COLUMN "public"."agent_run"."root_run_id" IS 'The top of the delegation chain (the run whose budget the whole subtree spends).';


COMMENT ON COLUMN "public"."agent_run"."chat_conversation_id" IS 'Main-chat origin, validated against its owner/workspace when created. Retained after chat deletion.';


COMMENT ON COLUMN "public"."agent_run"."chat_ceiling" IS 'Chat-delegated work: the drafting-ceiling tools the requesting chat could call at admission (sorted). The chat root and its teammate handoffs run on at most these. NULL = no chat bound; a chat-origin row with NULL is treated as an empty bound.';


COMMENT ON COLUMN "public"."agent_run"."helper_areas" IS 'Background helpers (A4): the areas (at most two) the main chat gave this helper. Its spec loads their playbooks and notes first. NULL for every other run.';


COMMENT ON COLUMN "public"."agent_run"."server_helper" IS 'A helper the server started on its own (337, 340, 443; A6): its kind (meeting_prep; home_turn: started by a server turn in the home thread; check_in: started by the main agent''s check-in). It has its own budget in start_chat_helper and never parks on a question. NULL for every other run.';


COMMENT ON COLUMN "public"."agent_run"."model_tier" IS 'Auto model selection tier the run started with (fast, think, strong); NULL is think.';


COMMENT ON COLUMN "public"."agent_run"."model_tier_by" IS 'Who decided model_tier (rule, jev, timeout, cap, fixed, agent); cap means Strong was refused, agent that the main agent chose the model.';


COMMENT ON COLUMN "public"."agent_run"."outside_reads" IS 'Tools that brought untrusted outside text into this run (374, src/lib/safety/outside-text.ts), each once, at most 20. What the run teaches or writes into a canon document is labelled from it.';


COMMENT ON COLUMN "public"."agent_run"."precheck" IS 'The coding pre-check (392, src/lib/coding/precheck.ts): verdict actionable | needs_clarification, questions, kind, size, model, at; answers once the starter replied. NULL until it ran.';


COMMENT ON COLUMN "public"."agent_run"."acceptance_criteria" IS 'What the change must do, written before coding by the pre-check (392); the reviewer checks each one against the real diff.';


COMMENT ON COLUMN "public"."agent_run"."review_trail" IS 'Each review of a coding run before its PR opens (393, src/lib/coding/review.ts): verdict approve | request_changes | reject | error, criteria with evidence, the head sha it read. request_changes sends the coder back at most twice.';


COMMENT ON COLUMN "public"."agent_run"."ci_fix_of_run_id" IS 'On a CI fix run (394, src/lib/coding/ci-fix.ts): the coding run whose open PR it fixes.';


COMMENT ON COLUMN "public"."agent_run"."ci_failure" IS 'On a CI fix run (394): the failing checks as GitHub reported them, bounded. Untrusted text; fenced when read into a task.';


COMMENT ON COLUMN "public"."agent_run"."ci_fix_trail" IS 'On a run that opened a PR (394): each failing head commit it reacted to, fix or gave_up. At most two fix entries.';


COMMENT ON COLUMN "public"."agent_run"."environment_id" IS 'Environments (420): the environment the run started in. Written when it starts, and only then.';


COMMENT ON COLUMN "public"."agent_run"."server_helper_item" IS 'A check-in''s helper (443): the tracked item it retries, <kind>:<id> (the Now file''s track). Unique per person in a workspace: one retry per item. NULL for every other run.';


COMMENT ON COLUMN "public"."agent_run"."base_branch" IS 'Coding runs: the base branch the spec cloned from and the PR must target (set with branch at the first spec build).';


COMMENT ON COLUMN "public"."agent_run"."helper_model" IS 'The helper roster model (src/lib/ai/models.ts HELPER_MODELS) a background helper run started on; NULL is model_tier''s model.';


