CREATE TABLE IF NOT EXISTS "public"."ai_team_member" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "team_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "avatar_url" "text",
    "agent_recipe_id" "uuid" NOT NULL,
    "team_role" "text" DEFAULT 'member'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "role" "text",
    "autonomy" "text" DEFAULT 'propose'::"text" NOT NULL,
    "allowed_side_effects" "text"[] DEFAULT '{read}'::"text"[] NOT NULL,
    "tool_allowlist" "text"[],
    "can_delegate_to" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "is_system" boolean DEFAULT false NOT NULL,
    "system_key" "text",
    "bot_character" "text",
    "fronts_only" boolean DEFAULT false NOT NULL,
    "voice" "text",
    CONSTRAINT "ai_team_member_allowed_side_effects_check" CHECK (("allowed_side_effects" <@ ARRAY['read'::"text", 'internal-write'::"text"])),
    CONSTRAINT "ai_team_member_autonomy_check" CHECK (("autonomy" = ANY (ARRAY['off'::"text", 'propose'::"text", 'attempt'::"text"]))),
    CONSTRAINT "ai_team_member_bot_character_check" CHECK ((("bot_character" IS NULL) OR ("bot_character" = ANY (ARRAY['chat'::"text", 'research'::"text", 'reconciler'::"text", 'sprout'::"text", 'writer'::"text", 'triage'::"text", 'extraction'::"text", 'berry'::"text", 'dev'::"text", 'nova'::"text", 'live'::"text", 'flows'::"text", 'notes'::"text", 'ember'::"text", 'scout'::"text", 'dew'::"text", 'coach'::"text", 'mail'::"text", 'knowledge'::"text", 'calendar'::"text", 'acorn'::"text", 'browser'::"text", 'shroom'::"text", 'deals'::"text"])) OR ("bot_character" ~ '^x[a-z]{7}$'::"text"))),
    CONSTRAINT "ai_team_member_can_delegate_to_check" CHECK (("can_delegate_to" <@ ARRAY['researcher'::"text", 'writer'::"text", 'developer'::"text", 'correspondent'::"text"])),
    CONSTRAINT "ai_team_member_fronts_only_check" CHECK (((NOT "fronts_only") OR (("role" IS NULL) AND (NOT "is_system")))),
    CONSTRAINT "ai_team_member_role_check" CHECK ((("role" IS NULL) OR ("role" = ANY (ARRAY['researcher'::"text", 'writer'::"text", 'developer'::"text", 'correspondent'::"text"])))),
    CONSTRAINT "ai_team_member_system_key_check" CHECK ((("system_key" IS NULL) OR ("is_system" AND ("system_key" = ANY (ARRAY['captures'::"text", 'mail'::"text", 'prospecting'::"text", 'evals'::"text", 'crm'::"text", 'assistant'::"text"]))))),
    CONSTRAINT "ai_team_member_system_not_routable" CHECK (((NOT "is_system") OR ("role" IS NULL))),
    CONSTRAINT "ai_team_member_team_role_check" CHECK (("team_role" = ANY (ARRAY['lead'::"text", 'member'::"text"]))),
    CONSTRAINT "ai_team_member_voice_check" CHECK ((("voice" IS NULL) OR ("voice" ~ '^[a-z0-9][a-z0-9-]{0,31}$'::"text")))
);


ALTER TABLE "public"."ai_team_member" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ai_team_member"."role" IS 'Routing role (researcher | writer | developer | correspondent). NULL = not routable: an attempted run is never assigned to it.';


COMMENT ON COLUMN "public"."ai_team_member"."autonomy" IS 'Per-teammate switch under the workspace policy: off | propose | attempt. attempt only counts when workspace.settings.agent_autonomy.mode is attempt too.';


COMMENT ON COLUMN "public"."ai_team_member"."allowed_side_effects" IS 'What this teammate may change on its own: {read} ("Read only", the default) or {read, internal-write} ("Read, and change Dial8 records"; what Attempt mode needs). Outside writes are never a teammate''s own (migration 305). Set by a workspace owner or admin only.';


COMMENT ON COLUMN "public"."ai_team_member"."tool_allowlist" IS 'Optional per-tool narrowing inside the allowed classes (bare registry tool names). NULL = every tool of the allowed classes.';


COMMENT ON COLUMN "public"."ai_team_member"."can_delegate_to" IS 'Roles this teammate may hand work to via delegate_work (the launch matrix, as data). Empty = may not delegate.';


COMMENT ON COLUMN "public"."ai_team_member"."is_system" IS 'A seeded teammate for a built-in loop (Triage, Extraction, …): readable across private teams, never deletable from the app.';


COMMENT ON COLUMN "public"."ai_team_member"."system_key" IS 'For a system teammate, the area face it is (captures | mail | prospecting | evals | crm) or the Assistant (assistant); the ledger writers look it up by this key. NULL for every other teammate.';


COMMENT ON COLUMN "public"."ai_team_member"."bot_character" IS 'The bot the teammate wears: a character''s id (src/components/bots/bot-characters.ts) or a built bot''s ("x" + seven letters, its recipe: bot-parts.ts). NULL = no bot. Seeded from default_bot_character / free_bot_character, changeable any time; two teammates may wear the same one.';


COMMENT ON COLUMN "public"."ai_team_member"."fronts_only" IS 'A work bot (bots v3): speaks for the loops (or agent) it fronts and takes no assignments. role NULL and not is_system (CHECK). Excluded from every assignment, routing, delegation and auto-attempt read; included on every bot surface.';


COMMENT ON COLUMN "public"."ai_team_member"."voice" IS 'The desktop text-to-speech voice the bot speaks in: a voice id as tts_voices lists it (lowercase letters, digits and hyphens, at most 32). NULL = Automatic, a voice dealt from its face (src/lib/bots/bot-voice.ts). The bot''s own, like its face: never copied across an agent''s bots, and not a limits column (migration 308).';


