CREATE TABLE IF NOT EXISTS "public"."bot_relay" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "call_key" "text" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "conversation_id" "uuid",
    "teammate_id" "uuid",
    "target" "text" NOT NULL,
    "agent_run_id" "uuid",
    "work_item_id" "uuid",
    "thread_conversation_id" "uuid",
    "message" "text" NOT NULL,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "reply" "text",
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    "mode" "text" DEFAULT 'turn'::"text" NOT NULL,
    "applied_at" timestamp with time zone,
    CONSTRAINT "bot_relay_applied_steer_only" CHECK ((("applied_at" IS NULL) OR ("mode" = 'steer'::"text"))),
    CONSTRAINT "bot_relay_call_key_length" CHECK ((("char_length"("call_key") >= 1) AND ("char_length"("call_key") <= 1024))),
    CONSTRAINT "bot_relay_error_length" CHECK ((("error" IS NULL) OR ("char_length"("error") <= 1000))),
    CONSTRAINT "bot_relay_message_length" CHECK ((("char_length"("message") >= 1) AND ("char_length"("message") <= 4000))),
    CONSTRAINT "bot_relay_mode_check" CHECK (("mode" = ANY (ARRAY['turn'::"text", 'steer'::"text"]))),
    CONSTRAINT "bot_relay_reply_length" CHECK ((("reply" IS NULL) OR ("char_length"("reply") <= 4100))),
    CONSTRAINT "bot_relay_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'done'::"text", 'failed'::"text", 'timed_out'::"text"]))),
    CONSTRAINT "bot_relay_target_check" CHECK (("target" = ANY (ARRAY['work_run'::"text", 'loop_run'::"text", 'thread'::"text"])))
);


ALTER TABLE "public"."bot_relay" OWNER TO "postgres";


COMMENT ON TABLE "public"."bot_relay" IS 'The main agent''s messages to the bots (bots v4 Phase A3/A4): one row per send_bot_message call, keyed by eve''s call ids, with the bot''s reply. The person reads their own rows; only the service role writes.';


COMMENT ON COLUMN "public"."bot_relay"."call_key" IS 'relay:<conversation>:session:<s>:turn:<t>:call:<c> (eve''s durable ids). Unique: a retried call finds its row and never sends twice.';


COMMENT ON COLUMN "public"."bot_relay"."target" IS 'work_run (an agent run''s parked session), loop_run (a loop run''s parked session) or thread (the bot''s own thread, A4).';


COMMENT ON COLUMN "public"."bot_relay"."reply" IS 'The bot''s reply, fenced as teammate text (data, never instructions) and capped at 4,000 characters inside the fence.';


COMMENT ON COLUMN "public"."bot_relay"."mode" IS 'turn: one turn in a parked chat (every relay before A4). steer: a message into a running helper''s live turn (turnPolicy steer).';


COMMENT ON COLUMN "public"."bot_relay"."applied_at" IS 'A steer: when the helper''s watcher saw it reach the turn (or drained it as the next turn). NULL for a turn relay and an unapplied steer.';


