    "content" "text",
    "summary" "text",
    "transcript" "text",
    "audio_url" "text",
    "duration_seconds" integer,
    "source_url" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "ai_processed" boolean DEFAULT false,
    "ai_summary" "text",
    "status" "text",
    "is_pinned" boolean DEFAULT false,
    "recorded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "user_notes" "text",
    "calendar_event_id" "text",
    "meeting_url" "text",
    "location" "text",
    "organizer_email" "text",
    "participants" "jsonb" DEFAULT '[]'::"jsonb",
    "project_id" "uuid",
    "workspace_id" "uuid" NOT NULL,
    "team_id" "uuid",
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "is_transcript_locked" boolean DEFAULT false NOT NULL,
    "fts" "tsvector" GENERATED ALWAYS AS ((((("setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("title", ''::"text")), 'A'::"char") || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("content", ''::"text")), 'B'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("user_notes", ''::"text")), 'B'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("transcript", ''::"text")), 'C'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("ai_summary", ''::"text")), 'C'::"char"))) STORED,
    "calendar_provider" "text",
    "scheduled_start" timestamp with time zone,
    "scheduled_end" timestamp with time zone,
    "auto_capture_status" "text",
    "account_id" "uuid",
    "note_attributions" "jsonb",
    "live_mode" boolean DEFAULT false NOT NULL,
    "batch_processed_at" timestamp with time zone,
