    "live_playbook" "text",
    CONSTRAINT "captures_auto_capture_status_check" CHECK ((("auto_capture_status" IS NULL) OR ("auto_capture_status" = ANY (ARRAY['pending'::"text", 'ready'::"text", 'recording'::"text", 'completed'::"text", 'skipped'::"text"])))),
    CONSTRAINT "captures_visibility_check" CHECK (("visibility" = ANY (ARRAY['workspace'::"text", 'private'::"text"])))
);

ALTER TABLE ONLY "public"."captures" REPLICA IDENTITY FULL;


ALTER TABLE "public"."captures" OWNER TO "postgres";


COMMENT ON COLUMN "public"."captures"."user_notes" IS 'Manual notes added by user for context/enrichment during or after recording';


COMMENT ON COLUMN "public"."captures"."calendar_event_id" IS 'EventKit calendar event ID this note is linked to';


COMMENT ON COLUMN "public"."captures"."meeting_url" IS 'Meeting URL (Zoom, Teams, Meet, etc.) from the calendar event';


COMMENT ON COLUMN "public"."captures"."location" IS 'Meeting location from the calendar event';


COMMENT ON COLUMN "public"."captures"."organizer_email" IS 'Email of the meeting organizer from the calendar event';


COMMENT ON COLUMN "public"."captures"."participants" IS 'JSON array of participants: [{"email": "...", "name": "...", "contactId": "...", "isOrganizer": false}]';


COMMENT ON COLUMN "public"."captures"."visibility" IS '''workspace'' (default: every workspace member) or ''private'' (only captures.user_id — no admin override). Derived content inherits this.';


COMMENT ON COLUMN "public"."captures"."package_ids" IS 'Context packages attached to this capture via the + Packages chip. Validated per-id against package_visible_to (mig 238) at write and at injection; empty = no package context.';


COMMENT ON COLUMN "public"."captures"."live_playbook" IS 'The call playbook the live copilot loaded for this capture (load_skill). NULL: none loaded.';


CREATE TABLE IF NOT EXISTS "public"."chat_conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "title" "text" DEFAULT 'New conversation'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "workspace_id" "uuid" NOT NULL,
    "capture_id" "uuid",
    "recipe_id" "uuid",
    "eve_session_id" "text",
    "slack_channel_id" "text",
    "slack_thread_ts" "text",
    "ai_team_member_id" "uuid",
    "agent_teammate_id" "uuid",
    "focus_area" "text",
    "is_home" boolean,
    "checkpoint_summary" "text",
    "checkpoint_at" timestamp with time zone,
    "environment_id" "uuid",
    "outside_channel" "text",
    "agent_guest_id" "uuid",
    "seen_at" timestamp with time zone,
    CONSTRAINT "chat_conversations_checkpoint_summary_len" CHECK ((("checkpoint_summary" IS NULL) OR ("char_length"("checkpoint_summary") <= 40000))),
    CONSTRAINT "chat_conversations_focus_area_check" CHECK ((("focus_area" IS NULL) OR (("focus_area" = ANY (ARRAY['calendar'::"text", 'actions'::"text", 'captures'::"text", 'documents'::"text", 'knowledge'::"text", 'initiatives'::"text", 'projects'::"text", 'flows'::"text", 'mail'::"text", 'crm'::"text", 'prospecting'::"text", 'sequences'::"text", 'campaigns'::"text", 'evals'::"text", 'browser'::"text", 'library'::"text", 'content'::"text", 'marketing'::"text"])) AND ("ai_team_member_id" IS NULL) AND ("agent_teammate_id" IS NULL)))),
    CONSTRAINT "chat_conversations_guest_is_plain" CHECK ((("agent_guest_id" IS NULL) OR (("is_home" IS NULL) AND ("ai_team_member_id" IS NULL) AND ("agent_teammate_id" IS NULL) AND ("capture_id" IS NULL) AND ("focus_area" IS NULL)))),
    CONSTRAINT "chat_conversations_home_is_plain" CHECK ((("is_home" IS NULL) OR (("workspace_id" IS NOT NULL) AND ("ai_team_member_id" IS NULL) AND ("agent_teammate_id" IS NULL) AND ("capture_id" IS NULL) AND ("focus_area" IS NULL)))),
    CONSTRAINT "chat_conversations_home_is_true" CHECK ((("is_home" IS NULL) OR ("is_home" = true))),
    CONSTRAINT "chat_conversations_outside_channel_check" CHECK ((("outside_channel" IS NULL) OR (("is_home" IS NULL) AND (("outside_channel" = 'slack'::"text") OR (("outside_channel" = ANY (ARRAY['sms'::"text", 'dial8'::"text"])) AND ("agent_guest_id" IS NOT NULL)))))),
    CONSTRAINT "chat_conversations_thread_or_bot_conversation" CHECK ((("ai_team_member_id" IS NULL) OR ("agent_teammate_id" IS NULL)))
);


ALTER TABLE "public"."chat_conversations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."chat_conversations"."eve_session_id" IS 'eve durable session id for the root dial8 agent that backs this chat. Written by the EveChatTransport the instant eve mints it; the root agent''s session-ownership ACL resolves {eve_session_id -> conversation.user_id + workspace_id} to authorize continue/stream. Null for cloud-route / Claude-CLI conversations.';


COMMENT ON COLUMN "public"."chat_conversations"."ai_team_member_id" IS 'The AI teammate this conversation is with (bots v2). NULL = an ordinary chat. Set once by the teammate mint; keeps the thread out of chat history and knowledge ingest. One thread per (user_id, ai_team_member_id).';


COMMENT ON COLUMN "public"."chat_conversations"."agent_teammate_id" IS 'The bot (ai_team_member) this main-chat conversation runs as (bots v4 Phase C). NULL = an ordinary chat. Set by the mint when it makes the conversation; a deleted bot leaves NULL and the conversation carries on with the default assistant. Never set on a bot''s own thread (ai_team_member_id).';


COMMENT ON COLUMN "public"."chat_conversations"."focus_area" IS 'A main-chat conversation focused on an area: the main agent with that area''s pack from the first turn. Fixed when it starts. Never a thread or a bot conversation.';


COMMENT ON COLUMN "public"."chat_conversations"."is_home" IS 'True on the person''s one home thread in a workspace (always-on agent A3); NULL otherwise, never false. One per (user_id, workspace_id) via uidx_chat_conversations_home. Never a teammate thread, a bot conversation, a live meeting''s conversation or a focused one.';


COMMENT ON COLUMN "public"."chat_conversations"."checkpoint_summary" IS 'The text of eve''s last compaction checkpoint for this conversation (stored by the memory slot at compaction.completed). Untrusted: rendered fenced as data when a home thread re-primes a new session.';


COMMENT ON COLUMN "public"."chat_conversations"."checkpoint_at" IS 'When checkpoint_summary was stored. A re-primed home thread adds the messages created after it.';


COMMENT ON COLUMN "public"."chat_conversations"."environment_id" IS 'Environments (420): where this chat sends work: the owner''s Mac, or a cloud environment of the chat''s workspace they can see. Null: the next default.';


COMMENT ON COLUMN "public"."chat_conversations"."outside_channel" IS 'Slack (414): set on a person''s conversation for one Slack channel thread (slack_thread). SMS (428) and dial8 (433, another Dial8 user''s agent): set on a guest''s own thread. Never on the home thread. A channel turn may send into it.';


COMMENT ON COLUMN "public"."chat_conversations"."agent_guest_id" IS 'The guest whose own thread this is (427). NULL = not a guest thread. Owned by the guest''s owner; kept out of chat history and knowledge ingest like a teammate thread. One per guest.';


COMMENT ON COLUMN "public"."chat_conversations"."seen_at" IS 'Home threads only (454): the newest message time the person had on screen while visible, focused and recently active. Set by POST /api/presence through one conditional update that clamps it to now() and never moves it backwards. NULL: never reported.';


CREATE TABLE IF NOT EXISTS "public"."chat_memory_epoch" (
    "session_id" "text" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "conversation_id" "uuid",
    "snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "snapshot_hash" "text" NOT NULL,
    "epoch_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "captured_through_seq" integer,
    "captured_through_at" timestamp with time zone,
    "last_capture_at" timestamp with time zone,
    "epoch_seq" integer DEFAULT 0 NOT NULL,
    "live_delta_seqs" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "facts_shown" boolean DEFAULT false NOT NULL,
    CONSTRAINT "chat_memory_epoch_session_id_check" CHECK ((("char_length"("session_id") >= 1) AND ("char_length"("session_id") <= 1024))),
    CONSTRAINT "chat_memory_epoch_snapshot_check" CHECK (("jsonb_typeof"("snapshot") = 'array'::"text"))
);


ALTER TABLE "public"."chat_memory_epoch" OWNER TO "postgres";


COMMENT ON TABLE "public"."chat_memory_epoch" IS 'Profile memory epochs (328): per eve chat session, the facts snapshot frozen at its first recall or last compaction (the `facts` record), plus the capture pass''s position (captured_through_*, last_capture_at). Server only.';


CREATE TABLE IF NOT EXISTS "public"."chat_memory_op" (
    "operation_id" "text" NOT NULL,
