);


ALTER TABLE "public"."chat_memory_op" OWNER TO "postgres";


COMMENT ON TABLE "public"."chat_memory_op" IS 'Memory operation results by eve operationId (328): a replayed recall returns the same bytes, a replayed capture runs once. Pruned past 7 days on write. Server only.';


