CREATE TABLE IF NOT EXISTS "public"."connected_mcp_server" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid",
    "display_name" "text" NOT NULL,
    "server_url" "text" NOT NULL,
    "transport" "text" DEFAULT 'streamable_http'::"text" NOT NULL,
    "auth_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "access_token_encrypted" "text",
    "refresh_token_encrypted" "text",
    "token_expires_at" timestamp with time zone,
    "oauth_metadata" "jsonb",
    "is_enabled" boolean DEFAULT true NOT NULL,
    "disabled_tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "require_approval_tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "tools_cache" "jsonb",
    "tools_cache_refreshed_at" timestamp with time zone,
    "last_health_check_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "slug" "text" GENERATED ALWAYS AS ("public"."mcp_server_slug"("display_name")) STORED,
    "approval_free_tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "allowed_tools" "text"[],
    "reauth_required_at" timestamp with time zone,
    "refresh_lease_until" timestamp with time zone,
    CONSTRAINT "connected_mcp_server_auth_type_check" CHECK (("auth_type" = ANY (ARRAY['none'::"text", 'bearer'::"text", 'oauth2'::"text"]))),
    CONSTRAINT "connected_mcp_server_transport_check" CHECK (("transport" = ANY (ARRAY['streamable_http'::"text", 'sse'::"text"])))
);


ALTER TABLE "public"."connected_mcp_server" OWNER TO "postgres";


COMMENT ON TABLE "public"."connected_mcp_server" IS 'External MCP servers a user has connected. Tokens stored encrypted via aes-256-gcm.';


COMMENT ON COLUMN "public"."connected_mcp_server"."require_approval_tools" IS 'Tool names the person explicitly requires approval for, even a read-only one. Tools in neither list follow the default: read-only runs, anything else needs approval.';


COMMENT ON COLUMN "public"."connected_mcp_server"."slug" IS 'Generated slug used for namespaced tool names (mcp__<slug>__<tool>). Must be unique per user.';


COMMENT ON COLUMN "public"."connected_mcp_server"."approval_free_tools" IS 'Tool names the person explicitly lets the agent run without an approval card. Approval is the default for every tool that is not read-only (src/lib/mcp-client/approval-policy.ts).';


COMMENT ON COLUMN "public"."connected_mcp_server"."allowed_tools" IS 'The tools the person has seen and kept: only these reach the agent (disabled_tools still switches one off). A tool the server lists that is not here is new and stays invisible until added. Null: not seeded yet; the next listing that finds tools seeds it (src/lib/mcp-client/tool-access.ts).';


COMMENT ON COLUMN "public"."connected_mcp_server"."reauth_required_at" IS 'When the provider''s token endpoint first refused this server''s refresh token for good (HTTP 400/401, revoked grant). NULL = healthy. Set and cleared by the token refresh path; cleared on reconnect (451).';


COMMENT ON COLUMN "public"."connected_mcp_server"."refresh_lease_until" IS 'A refresh in flight holds this until then, so no two calls spend the same refresh token (451). NULL = none.';


CREATE TABLE IF NOT EXISTS "public"."contact" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "member_id" "uuid",
    "company_id" "uuid",
    "first_name" "text",
    "last_name" "text",
    "full_name" "text" NOT NULL,
    "email" "text",
    "secondary_emails" "text"[] DEFAULT '{}'::"text"[],
    "phone" "text",
    "avatar_url" "text",
    "job_title" "text",
    "department" "text",
    "linkedin_url" "text",
    "relationship_type" "text" DEFAULT 'contact'::"text",
    "relationship_strength" "text" DEFAULT 'neutral'::"text",
    "last_interaction_at" timestamp with time zone,
    "interaction_count" integer DEFAULT 0,
    "next_followup_at" timestamp with time zone,
    "source" "text" DEFAULT 'manual'::"text",
    "source_provider" "text",
    "provider_contact_id" "text",
    "notes" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "created_by_member_id" "uuid",
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "merged_into_contact_id" "uuid",
    "fts" "tsvector" GENERATED ALWAYS AS (((("setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("full_name", ''::"text")), 'A'::"char") || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("email", ''::"text")), 'A'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", "public"."contact_emails_text"("secondary_emails")), 'A'::"char")) || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("notes", ''::"text")), 'B'::"char"))) STORED,
    "enrichment_status" "text",
    "enriched_at" timestamp with time zone,
    "prospect_list_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "address" "text",
    CONSTRAINT "contact_address_length" CHECK ((("address" IS NULL) OR ("char_length"("address") <= 300))),
    CONSTRAINT "contact_enrichment_status_check" CHECK (("enrichment_status" = ANY (ARRAY['pending'::"text", 'enriched'::"text", 'failed'::"text", 'skipped'::"text"]))),
    CONSTRAINT "contact_relationship_strength_check" CHECK (("relationship_strength" = ANY (ARRAY['strong'::"text", 'warm'::"text", 'neutral'::"text", 'cold'::"text", 'stale'::"text"]))),
    CONSTRAINT "contact_relationship_type_check" CHECK (("relationship_type" = ANY (ARRAY['contact'::"text", 'lead'::"text", 'customer'::"text", 'partner'::"text", 'vendor'::"text", 'internal'::"text", 'candidate'::"text"]))),
    CONSTRAINT "contact_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'email_sync'::"text", 'calendar_sync'::"text", 'capture_participant'::"text", 'csv_import'::"text", 'member'::"text", 'hubspot_sync'::"text", 'prospecting'::"text", 'web_form'::"text", 'sms'::"text", 'import'::"text"]))),
    CONSTRAINT "contact_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'team'::"text", 'workspace'::"text"])))
);

