    CONSTRAINT "customer_booking_phone_shape" CHECK ((("customer_phone" IS NULL) OR ("customer_phone" ~ '^[+][1-9][0-9]{7,14}$'::"text"))),
    CONSTRAINT "customer_booking_source_check" CHECK (("source" = ANY (ARRAY['sms'::"text", 'link'::"text", 'phone'::"text", 'owner'::"text"]))),
    CONSTRAINT "customer_booking_state_check" CHECK (("state" = ANY (ARRAY['requested'::"text", 'confirmed'::"text", 'declined'::"text", 'expired'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "customer_booking_text_lengths" CHECK ((("char_length"("btrim"("customer_name")) >= 1) AND ("char_length"("btrim"("customer_name")) <= 120) AND (("address" IS NULL) OR ("char_length"("address") <= 300)) AND (("note" IS NULL) OR ("char_length"("note") <= 1000)) AND ("char_length"("kind") <= 40))),
    CONSTRAINT "customer_booking_times" CHECK ((("ends_at" > "starts_at") AND (("ends_at" - "starts_at") <= '1 day'::interval)))
);


