CREATE TABLE IF NOT EXISTS "public"."customer_quote" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "contact_id" "uuid",
    "source" "text" NOT NULL,
    "external_id" "text",
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "customer_name" "text",
    "customer_email" "text",
    "customer_phone" "text",
    "address" "text",
    "service" "text",
    "items" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "total_cents" integer,
    "currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "requested_dates" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "notes" "text",
    "raw" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "customer_quote_items_shape" CHECK (
CASE
    WHEN ("jsonb_typeof"("items") = 'array'::"text") THEN ("jsonb_array_length"("items") <= 50)
    ELSE false
END),
    CONSTRAINT "customer_quote_phone_shape" CHECK ((("customer_phone" IS NULL) OR ("customer_phone" ~ '^[+][1-9][0-9]{7,14}$'::"text"))),
    CONSTRAINT "customer_quote_source_check" CHECK (("source" = ANY (ARRAY['web_form'::"text", 'sms'::"text", 'phone'::"text", 'owner'::"text"]))),
    CONSTRAINT "customer_quote_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'sent'::"text", 'accepted'::"text", 'declined'::"text", 'booked'::"text", 'done'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "customer_quote_text_lengths" CHECK (((("customer_name" IS NULL) OR ("char_length"("customer_name") <= 120)) AND (("customer_email" IS NULL) OR ("char_length"("customer_email") <= 254)) AND (("address" IS NULL) OR ("char_length"("address") <= 300)) AND (("service" IS NULL) OR ("char_length"("service") <= 120)) AND (("notes" IS NULL) OR ("char_length"("notes") <= 2000)) AND (("external_id" IS NULL) OR ("char_length"("external_id") <= 120)) AND ("cardinality"("requested_dates") <= 10))),
    CONSTRAINT "customer_quote_total_range" CHECK ((("total_cents" IS NULL) OR (("total_cents" >= 0) AND ("total_cents" <= 100000000))))
);


