CREATE OR REPLACE VIEW "public"."devices_with_multiple_users" AS
 SELECT "device_id",
    "count"(DISTINCT "user_id") AS "user_count",
    "array_agg"(DISTINCT "user_id") AS "user_ids"
   FROM "public"."user_devices"
  GROUP BY "device_id"
 HAVING ("count"(DISTINCT "user_id") > 1);


