CREATE TABLE IF NOT EXISTS "public"."document" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "project_id" "uuid",
    "team_id" "uuid",
    "title" "text" NOT NULL,
    "content" "text",
    "content_json" "jsonb",
    "created_by" "uuid",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "is_pinned" boolean DEFAULT false NOT NULL,
    "sort_order" real DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fts" "tsvector" GENERATED ALWAYS AS (("setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("title", ''::"text")), 'A'::"char") || "setweight"("to_tsvector"('"english"'::"regconfig", COALESCE("content", ''::"text")), 'B'::"char"))) STORED,
    "slug" "text",
    "type" "text" DEFAULT 'note'::"text" NOT NULL,
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "frontmatter" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "published_status" "text" DEFAULT 'published'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "last_edited_by" "uuid",
    "revision" integer DEFAULT 1 NOT NULL,
    "edit_source" "text",
    "edit_summary" "text",
    "canon_key" "text",
    "kind" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("frontmatter" ? 'meeting_prep'::"text") THEN 'prep'::"text"
    WHEN ("frontmatter" ? 'now'::"text") THEN 'now'::"text"
    WHEN ("frontmatter" ? 'skill_id'::"text") THEN 'report'::"text"
    ELSE 'doc'::"text"
END) STORED,
    "visibility" "text" DEFAULT 'workspace'::"text" NOT NULL,
    "edit_meta" "jsonb",
    "outside_derived" boolean DEFAULT false NOT NULL,
    CONSTRAINT "document_canon_key_format" CHECK ((("canon_key" IS NULL) OR ("canon_key" ~ '^[a-z0-9][a-z0-9:._-]{0,63}$'::"text"))),
    CONSTRAINT "document_edit_source_check" CHECK ((("edit_source" IS NULL) OR ("edit_source" = ANY (ARRAY['human'::"text", 'agent'::"text", 'system'::"text"])))),
    CONSTRAINT "document_published_status_check" CHECK (("published_status" = ANY (ARRAY['draft'::"text", 'published'::"text"]))),
    CONSTRAINT "document_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "document_type_check" CHECK (("type" = ANY (ARRAY['note'::"text", 'system'::"text", 'entity'::"text", 'analysis'::"text", 'source_summary'::"text", 'spec'::"text"]))),
    CONSTRAINT "document_visibility_check" CHECK (("visibility" = ANY (ARRAY['workspace'::"text", 'private'::"text"])))
);

