    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "environment_env_vars_check" CHECK (("octet_length"("env_vars") <= 65536)),
    CONSTRAINT "environment_kind_check" CHECK (("kind" = ANY (ARRAY['mac'::"text", 'cloud'::"text"]))),
    CONSTRAINT "environment_kind_shape" CHECK (((("kind" = 'mac'::"text") AND ("owner_user_id" IS NOT NULL) AND ("device_id" IS NOT NULL) AND ("workspace_id" IS NULL) AND ("shared" IS NULL) AND ("network_access" IS NULL) AND ("env_vars" IS NULL) AND ("setup_script" IS NULL)) OR (("kind" = 'cloud'::"text") AND ("owner_user_id" IS NULL) AND ("device_id" IS NULL) AND ("workspace_id" IS NOT NULL) AND ("shared" IS NOT NULL) AND ("network_access" IS NOT NULL)))),
    CONSTRAINT "environment_name_check" CHECK ((("char_length"("name") >= 1) AND ("char_length"("name") <= 80))),
    CONSTRAINT "environment_network_access_check" CHECK (("network_access" = ANY (ARRAY['trusted'::"text", 'restricted'::"text", 'isolated'::"text"]))),
    CONSTRAINT "environment_setup_script_check" CHECK (("octet_length"("setup_script") <= 65536))
);


