CREATE TABLE IF NOT EXISTS "public"."eval_candidate" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "source" "text" NOT NULL,
    "polarity" "text" DEFAULT 'bad'::"text" NOT NULL,
    "ref_type" "text",
    "ref_id" "text",
    "conversation_id" "uuid",
    "skill_slugs" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "tools" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "reason" "text",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "case_draft" "jsonb",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "exported_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "eval_candidate_case_draft_check" CHECK ((("case_draft" IS NULL) OR (("jsonb_typeof"("case_draft") = 'object'::"text") AND ("octet_length"(("case_draft")::"text") <= 8000)))),
    CONSTRAINT "eval_candidate_dedupe_key_check" CHECK ((("char_length"("dedupe_key") >= 1) AND ("char_length"("dedupe_key") <= 300))),
    CONSTRAINT "eval_candidate_evidence_check" CHECK ((("jsonb_typeof"("evidence") = 'object'::"text") AND ("octet_length"(("evidence")::"text") <= 16000))),
    CONSTRAINT "eval_candidate_lists_check" CHECK ((("cardinality"("skill_slugs") <= 20) AND ("cardinality"("tools") <= 40))),
    CONSTRAINT "eval_candidate_polarity_check" CHECK (("polarity" = ANY (ARRAY['bad'::"text", 'good'::"text"]))),
    CONSTRAINT "eval_candidate_reason_check" CHECK ((("reason" IS NULL) OR ("char_length"("reason") <= 500))),
    CONSTRAINT "eval_candidate_ref_check" CHECK (((("ref_type" IS NULL) OR ("char_length"("ref_type") <= 40)) AND (("ref_id" IS NULL) OR ("char_length"("ref_id") <= 300)))),
    CONSTRAINT "eval_candidate_source_check" CHECK (("source" = ANY (ARRAY['thumbs_down'::"text", 'thumbs_up'::"text", 'repeated_failure'::"text", 'input_invalid'::"text", 'draft_rewrite'::"text", 'loop_failed'::"text"]))),
    CONSTRAINT "eval_candidate_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'promoted'::"text", 'dismissed'::"text", 'exported'::"text"])))
);


ALTER TABLE "public"."eval_candidate" OWNER TO "postgres";


COMMENT ON TABLE "public"."eval_candidate" IS 'Evals flywheel (349): one row per signal that an agent turn went wrong (or right, for a thumbs-up). Reviewed by Dial8 staff and promoted into chat skill eval cases. Server-written only.';


COMMENT ON COLUMN "public"."eval_candidate"."evidence" IS 'Templated, clipped evidence: the request, the reply opening, the tool path (clipped inputs, error codes); for a draft rewrite only a similarity score and pointers, never mail text.';


COMMENT ON COLUMN "public"."eval_candidate"."case_draft" IS 'The chat skill eval case (SkillEvalCase JSON) a reviewer promoted it into.';


