    CONSTRAINT "flow_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['entity_status_change'::"text", 'capture_processed'::"text", 'pr_status_changed'::"text", 'schedule'::"text", 'calendar_event'::"text", 'quote_received'::"text"])))
);

