    "approval_id" "uuid",
    "resume" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "flow_run_state_parked_action_id_check" CHECK ((("parked_action_id" IS NULL) OR (("char_length"("parked_action_id") >= 1) AND ("char_length"("parked_action_id") <= 200)))),
    CONSTRAINT "flow_run_state_parked_check" CHECK ((("status" <> 'parked'::"text") OR (("approval_id" IS NOT NULL) AND ("parked_action_id" IS NOT NULL) AND ("resume" IS NOT NULL)))),
    CONSTRAINT "flow_run_state_status_check" CHECK (("status" = ANY (ARRAY['done'::"text", 'parked'::"text", 'resuming'::"text"])))
);


ALTER TABLE "public"."flow_run_state" OWNER TO "postgres";


