    CONSTRAINT "home_turn_reports_cap" CHECK (("cardinality"("report_message_ids") <= 50)),
    CONSTRAINT "home_turn_status_check" CHECK (("status" = ANY (ARRAY['claimed'::"text", 'sent'::"text", 'done'::"text", 'skipped'::"text", 'failed'::"text"]))),
