CREATE TABLE IF NOT EXISTS "public"."local_agent_message" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "author" "text" NOT NULL,
    "text" "text" NOT NULL,
    "policy" "text" DEFAULT 'queue'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error" "text",
    "delivered_at" timestamp with time zone,
    "idempotency_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "person_words" "text"[],
    CONSTRAINT "local_agent_message_author_check" CHECK (("author" = ANY (ARRAY['agent'::"text", 'person'::"text"]))),
    CONSTRAINT "local_agent_message_error_check" CHECK (("char_length"("error") <= 4000)),
    CONSTRAINT "local_agent_message_idempotency_key_check" CHECK (("char_length"("idempotency_key") <= 1000)),
    CONSTRAINT "local_agent_message_person_words_ck" CHECK ((("person_words" IS NULL) OR ("cardinality"("person_words") <= 3))),
    CONSTRAINT "local_agent_message_policy_check" CHECK (("policy" = ANY (ARRAY['steer'::"text", 'queue'::"text"]))),
    CONSTRAINT "local_agent_message_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'delivered'::"text", 'failed'::"text"]))),
    CONSTRAINT "local_agent_message_text_check" CHECK ((("char_length"("text") >= 1) AND ("char_length"("text") <= 20000)))
);


ALTER TABLE "public"."local_agent_message" OWNER TO "postgres";


COMMENT ON TABLE "public"."local_agent_message" IS 'Local agents (410): a message to a local agent, delivered by the Mac (pending → delivered | failed via the ack route). The person reads their own rows; only the service role writes.';


COMMENT ON COLUMN "public"."local_agent_message"."person_words" IS 'Local agents (418): the person''s own words from the chat turn that sent this Dial8-agent message (a join, a steer): the reviewer''s evidence.';


CREATE TABLE IF NOT EXISTS "public"."local_agent_relay_slot" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "session_id" "uuid" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."local_agent_relay_slot" OWNER TO "postgres";


COMMENT ON TABLE "public"."local_agent_relay_slot" IS 'Local agents (410): in-flight model relay calls, at most a few per person (local_agent_relay_acquire). Service role only.';


CREATE TABLE IF NOT EXISTS "public"."local_agent_session" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "folder_id" "uuid" NOT NULL,
    "conversation_id" "uuid",
    "tracked_job_id" "uuid",
    "current_turn" integer DEFAULT 1 NOT NULL,
    "current_tracked_job_id" "uuid",
    "started_by" "text" NOT NULL,
    "mode" "text" DEFAULT 'read'::"text" NOT NULL,
    "request" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "eve_session_id" "text",
    "stream_index" integer,
    "run_id" "text",
    "last_seq" integer,
    "last_seq_run_id" "text",
    "claimed_at" timestamp with time zone,
    "lease_expires_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '06:00:00'::interval) NOT NULL,
    "stop_requested_at" timestamp with time zone,
    "last_signal" "text",
    "last_signal_text" "text",
    "branch" "text",
    "commit_sha" "text",
    "error" "text",
    "ended_at" timestamp with time zone,
    "pending_turn_text" "text",
    "idempotency_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "local_model" boolean DEFAULT false NOT NULL,
    "pr_url" "text",
    "start_words" "text"[],
    "environment_id" "uuid",
    "base_branch" "text",
    CONSTRAINT "local_agent_session_base_branch_check" CHECK ((("base_branch" IS NULL) OR (("mode" = 'edit'::"text") AND ("base_branch" ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,99}$'::"text") AND ("base_branch" !~ '(^HEAD$|^refs/|[.][.]|//|@[{]|[.]lock$|/$|[.]$)'::"text")))),
    CONSTRAINT "local_agent_session_branch_check" CHECK (("char_length"("branch") <= 300)),
    CONSTRAINT "local_agent_session_commit_sha_check" CHECK (("char_length"("commit_sha") <= 64)),
    CONSTRAINT "local_agent_session_current_turn_check" CHECK (("current_turn" >= 1)),
    CONSTRAINT "local_agent_session_error_check" CHECK (("char_length"("error") <= 4000)),
    CONSTRAINT "local_agent_session_eve_session_id_check" CHECK (("char_length"("eve_session_id") <= 200)),
    CONSTRAINT "local_agent_session_idempotency_key_check" CHECK (("char_length"("idempotency_key") <= 1000)),
    CONSTRAINT "local_agent_session_last_seq_check" CHECK (("last_seq" >= 0)),
    CONSTRAINT "local_agent_session_last_seq_run_id_check" CHECK (("char_length"("last_seq_run_id") <= 200)),
    CONSTRAINT "local_agent_session_last_signal_check" CHECK (("last_signal" = ANY (ARRAY['ask'::"text", 'finish'::"text"]))),
    CONSTRAINT "local_agent_session_last_signal_text_check" CHECK (("char_length"("last_signal_text") <= 20000)),
    CONSTRAINT "local_agent_session_mode_check" CHECK (("mode" = ANY (ARRAY['read'::"text", 'edit'::"text"]))),
    CONSTRAINT "local_agent_session_pending_turn_text_check" CHECK (("char_length"("pending_turn_text") <= 20000)),
    CONSTRAINT "local_agent_session_pr_url_ck" CHECK ((("pr_url" IS NULL) OR (("char_length"("pr_url") >= 20) AND ("char_length"("pr_url") <= 2048) AND ("pr_url" ~~ 'https://github.com/%'::"text")))),
    CONSTRAINT "local_agent_session_request_check" CHECK ((("char_length"("request") >= 1) AND ("char_length"("request") <= 20000))),
    CONSTRAINT "local_agent_session_run_id_check" CHECK (("char_length"("run_id") <= 200)),
    CONSTRAINT "local_agent_session_start_words_ck" CHECK ((("start_words" IS NULL) OR ("cardinality"("start_words") <= 3))),
    CONSTRAINT "local_agent_session_started_by_check" CHECK (("started_by" = ANY (ARRAY['agent'::"text", 'person'::"text"]))),
    CONSTRAINT "local_agent_session_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'starting'::"text", 'running'::"text", 'waiting'::"text", 'cancelled'::"text", 'failed'::"text", 'interrupted'::"text", 'expired'::"text"])))
);

ALTER TABLE ONLY "public"."local_agent_session" REPLICA IDENTITY FULL;


ALTER TABLE "public"."local_agent_session" OWNER TO "postgres";


COMMENT ON TABLE "public"."local_agent_session" IS 'Local agents (410): one job on a person''s Mac, in one granted folder. Status is written only by service-role routes (claim CAS, event uploads, lazy reaping). The ledger mirror is one tracked_job row per turn (kind local_agent, run key local_agent:<id>:<turn>).';


COMMENT ON COLUMN "public"."local_agent_session"."local_model" IS 'Local agents (418): the Mac ran this session''s latest launch on a model on the Mac, not the Dial8 relay. Set at each claim from the Mac''s report; C1 narrows the tools by it.';


COMMENT ON COLUMN "public"."local_agent_session"."pr_url" IS 'Local agents (418): the github.com pull request for the session''s own dial8/ branch, opened by the server route or by gh on the Mac.';


COMMENT ON COLUMN "public"."local_agent_session"."start_words" IS 'Local agents (418): the person''s own words from the chat turn that started the job (at most 3, oldest first): the reviewer''s evidence for the Mac body''s calls.';


COMMENT ON COLUMN "public"."local_agent_session"."environment_id" IS 'Environments (420): the Mac environment of the session''s device, written when it starts.';


COMMENT ON COLUMN "public"."local_agent_session"."base_branch" IS 'Environments (420, E3): the local branch an edit job branches from, stamped when it started from its folder''s setting, only for a Mac whose app resolves one. Null: HEAD.';


