    CONSTRAINT "notification_type_check" CHECK (("type" = ANY (ARRAY['action_assigned'::"text", 'action_unassigned'::"text", 'action_status_changed'::"text", 'capture_shared'::"text", 'comment_added'::"text", 'comment_reply'::"text", 'decision_confirmed'::"text", 'cycle_started'::"text", 'project_status_changed'::"text", 'meeting_starting_soon'::"text", 'contact_followup_due'::"text", 'flow_run_output'::"text", 'reminder'::"text", 'work_needs_you'::"text", 'work_failed'::"text", 'agent_digest'::"text", 'workspace_merged'::"text", 'agent_check_in'::"text", 'agent_look_ahead'::"text", 'agent_message'::"text"])))
