    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "consumed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "one_time_link_payload_size" CHECK ((("jsonb_typeof"("payload") = 'object'::"text") AND ("pg_column_size"("payload") <= 4096))),
    CONSTRAINT "one_time_link_purpose_check" CHECK (("purpose" = 'oauth_connect'::"text")),
    CONSTRAINT "one_time_link_token_hash_length" CHECK (("char_length"("token_hash") = 64))
);


ALTER TABLE "public"."one_time_link" OWNER TO "postgres";


COMMENT ON TABLE "public"."one_time_link" IS 'A single-use link bound to one account and one purpose (457): sha256 of the token, expiry, consumed_at. Service role only (no client policy on purpose).';


COMMENT ON COLUMN "public"."one_time_link"."purpose" IS 'What the link does: oauth_connect (start a provider sign-in from a text). src/lib/links/purposes.ts.';


