);


ALTER TABLE "public"."outreach_suppression" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."payment_request" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "contact_id" "uuid",
    "subject_type" "text" NOT NULL,
    "subject_id" "text",
    "action_id" "uuid",
    "description" "text" NOT NULL,
    "amount_cents" integer NOT NULL,
    "currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "application_fee_cents" integer DEFAULT 0 NOT NULL,
    "stripe_account_id" "text" NOT NULL,
    "livemode" boolean DEFAULT false NOT NULL,
    "stripe_payment_link_id" "text",
    "url" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "sent_to_phone" "text",
    "sent_to_email" "text",
    "sent_via" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sent_at" timestamp with time zone,
    "stripe_checkout_session_id" "text",
    "stripe_payment_intent_id" "text",
    "amount_paid_cents" integer,
    "paid_at" timestamp with time zone,
    "paid_followups_queued_at" timestamp with time zone,
    "amount_refunded_cents" integer DEFAULT 0 NOT NULL,
    "refunded_at" timestamp with time zone,
    "disputed_at" timestamp with time zone,
    "dispute_status" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "payment_request_account_shape" CHECK (("stripe_account_id" ~ '^acct_[A-Za-z0-9]{6,64}$'::"text")),
    CONSTRAINT "payment_request_amount_range" CHECK ((("amount_cents" >= 50) AND ("amount_cents" <= 5000000) AND (("application_fee_cents" >= 0) AND ("application_fee_cents" <= "amount_cents")) AND (("amount_paid_cents" IS NULL) OR ("amount_paid_cents" >= 0)) AND ("amount_refunded_cents" >= 0))),
    CONSTRAINT "payment_request_currency_shape" CHECK (("currency" ~ '^[a-z]{3}$'::"text")),
    CONSTRAINT "payment_request_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'paid'::"text", 'refunded'::"text", 'disputed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "payment_request_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['quote'::"text", 'booking'::"text", 'action'::"text", 'job'::"text"]))),
    CONSTRAINT "payment_request_text_lengths" CHECK ((("char_length"("btrim"("description")) >= 1) AND ("char_length"("btrim"("description")) <= 200) AND (("subject_id" IS NULL) OR ("char_length"("subject_id") <= 64)) AND (("url" IS NULL) OR ("char_length"("url") <= 500)) AND (("sent_to_phone" IS NULL) OR ("sent_to_phone" ~ '^[+][1-9][0-9]{7,14}$'::"text")) AND (("sent_to_email" IS NULL) OR ("char_length"("sent_to_email") <= 254)) AND ("cardinality"("sent_via") <= 2) AND (("dispute_status" IS NULL) OR ("char_length"("dispute_status") <= 40))))
);


ALTER TABLE "public"."payment_request" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_request" IS 'A payment link sent to a customer for a quote or job (459): a Stripe Payment Link on the workspace''s connected account, and what happened to it. Service role writes only.';


COMMENT ON COLUMN "public"."payment_request"."subject_type" IS 'What it is for: quote (track B customer_quote), booking (customer_booking), action (a to-do) or job (anything else the owner named).';


COMMENT ON COLUMN "public"."payment_request"."action_id" IS 'The to-do this payment closes when it is paid.';


COMMENT ON COLUMN "public"."payment_request"."status" IS 'open (sent, not paid), paid, refunded (in full; a partial refund keeps paid), disputed, cancelled (the link was switched off unpaid).';


COMMENT ON COLUMN "public"."payment_request"."paid_followups_queued_at" IS 'When the paid follow-ups (close the to-do, CRM note, text the owner, job.paid) were queued. A webhook retry after a lost queue re-queues them; the queue dedupes on the request.';


