    CONSTRAINT "phone_signup_code_e164_format" CHECK (("phone_e164" ~ '^[+][1-9][0-9]{6,14}$'::"text")),
    CONSTRAINT "phone_signup_code_hash_length" CHECK (("char_length"("code_hash") = 64))
);


ALTER TABLE "public"."phone_signup_code" OWNER TO "postgres";


