CREATE TABLE IF NOT EXISTS "public"."proposed_change" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "capture_id" "uuid",
    "change_type" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid",
    "display_text" "text" NOT NULL,
    "title" "text",
    "description" "text",
    "priority" "text",
    "due_date" "date",
    "status_from" "text",
    "status_to" "text",
    "assignee_name" "text",
    "assignee_member_id" "uuid",
    "assignee_contact_id" "uuid",
    "team_id" "uuid",
    "project_id" "uuid",
    "labels" "text"[],
    "email_to_name" "text",
    "email_to_address" "text",
    "email_subject" "text",
    "email_context" "text",
    "extra" "jsonb",
    "anchor_text" "text",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "confidence" real DEFAULT 0.5 NOT NULL,
    "trigger_quote" "text",
    "reasoning" "text",
    "stakes" "text",
    "open_questions" "text"[],
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "applied_at" timestamp with time zone,
    "applied_by" "uuid",
    "result_entity_id" "uuid",
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "auto_accepted" boolean DEFAULT false NOT NULL,
    "document_id" "uuid",
    "conversation_id" "uuid",
    "tracked_job_id" "uuid",
    "origin" "text",
    "fingerprint" "text",
    "base" "jsonb",
    "expires_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "expire_reason" "text",
    CONSTRAINT "proposed_change_change_type_check" CHECK (("change_type" = ANY (ARRAY['create'::"text", 'update'::"text", 'delete'::"text", 'assign'::"text", 'send_email'::"text", 'mcp_call'::"text"]))),
    CONSTRAINT "proposed_change_confidence_check" CHECK ((("confidence" >= (0)::double precision) AND ("confidence" <= (1)::double precision))),
    CONSTRAINT "proposed_change_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['action'::"text", 'project'::"text", 'decision'::"text", 'milestone'::"text", 'initiative'::"text", 'contact'::"text", 'external'::"text", 'comment'::"text"]))),
    CONSTRAINT "proposed_change_expire_reason_check" CHECK ((("expire_reason" IS NULL) OR ("expire_reason" = ANY (ARRAY['ttl'::"text", 'already_true'::"text", 'target_deleted'::"text", 'applied_elsewhere'::"text", 'run_undelivered'::"text"])))),
    CONSTRAINT "proposed_change_one_home" CHECK (("num_nonnulls"("capture_id", "document_id", "conversation_id") <= 1)),
    CONSTRAINT "proposed_change_origin_check" CHECK ((("origin" IS NULL) OR ("origin" = ANY (ARRAY['live_agent'::"text", 'triage'::"text", 'chat'::"text", 'skill_run'::"text", 'work_run'::"text", 'mcp'::"text"])))),
    CONSTRAINT "proposed_change_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'applied'::"text", 'dismissed'::"text", 'expired'::"text"])))
);

ALTER TABLE ONLY "public"."proposed_change" REPLICA IDENTITY FULL;


ALTER TABLE "public"."proposed_change" OWNER TO "postgres";


COMMENT ON COLUMN "public"."proposed_change"."document_id" IS 'Home: the document this suggestion is shown in. At most one of capture_id, document_id, conversation_id.';


COMMENT ON COLUMN "public"."proposed_change"."conversation_id" IS 'Home: the main-chat conversation this suggestion is shown in. Visible only to the conversation owner.';


COMMENT ON COLUMN "public"."proposed_change"."tracked_job_id" IS 'The run that staged it. A run''s suggestions have no home until delivery re-homes them onto its document.';


COMMENT ON COLUMN "public"."proposed_change"."fingerprint" IS 'Hash of workspace + combo + target + proposed values (src/lib/suggestions/fingerprint.ts).';


COMMENT ON COLUMN "public"."proposed_change"."base" IS 'The target''s fields when the suggestion was staged, for the apply-time drift check.';


COMMENT ON COLUMN "public"."proposed_change"."expires_at" IS 'When a pending suggestion nobody acted on becomes expired.';


COMMENT ON COLUMN "public"."proposed_change"."resolved_at" IS 'When it left pending. Dismissed and expired rows are purged some time after it.';


COMMENT ON COLUMN "public"."proposed_change"."expire_reason" IS 'Why an expired suggestion expired: ttl | already_true | target_deleted | applied_elsewhere | run_undelivered.';


