    CONSTRAINT "sms_message_kind_check" CHECK (("kind" = ANY (ARRAY['text'::"text", 'stop'::"text", 'start'::"text", 'help'::"text", 'unknown'::"text", 'limited'::"text", 'approval'::"text", 'code_miss'::"text", 'guest_text'::"text", 'guest_invite'::"text", 'guest_join'::"text", 'signup_code_miss'::"text", 'verification'::"text", 'welcome'::"text", 'reply'::"text", 'notice'::"text", 'unknown_reply'::"text", 'auto_reply'::"text", 'needs_you'::"text", 'approval_result'::"text", 'guest_reply'::"text", 'guest_welcome'::"text", 'guest_notice'::"text", 'away'::"text", 'signup_code'::"text", 'connected'::"text"]))),
