);


ALTER TABLE "public"."sms_message" OWNER TO "postgres";


COMMENT ON TABLE "public"."sms_message" IS 'Texts in and out of the Dial8 number (411), without bodies: rate limits, the daily cap, the once-only unknown-sender reply, and STOP/START from unlinked numbers. Service role only.';


COMMENT ON COLUMN "public"."sms_message"."kind" IS 'in: text, stop, start, help, unknown, limited, approval, code_miss, guest_text, guest_invite, guest_join, signup_code_miss (457). out: verification, welcome, reply, notice, unknown_reply, auto_reply (HELP / START answers), needs_you, approval_result, guest_reply, guest_welcome, guest_notice, away (454), signup_code, connected (457).';


COMMENT ON COLUMN "public"."sms_message"."guest_id" IS 'The guest (agent_guest, 427) this text came from or went to (428): their per-day caps. Null for everyone else.';


COMMENT ON COLUMN "public"."sms_message"."resend_of" IS 'The MessageSid of a text carriers refused from an agent number, which this row resent from the Dial8 number (465).';


CREATE TABLE IF NOT EXISTS "public"."stripe_connect_account" (
    "workspace_id" "uuid" NOT NULL,
    "stripe_account_id" "text" NOT NULL,
    "linked_via" "text" NOT NULL,
    "livemode" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'onboarding'::"text" NOT NULL,
