    "payouts_enabled" boolean DEFAULT false NOT NULL,
    "details_submitted" boolean DEFAULT false NOT NULL,
    "connected_by" "uuid",
    "application_fee_bps" integer DEFAULT 0 NOT NULL,
    "application_fee_cents" integer DEFAULT 0 NOT NULL,
    "ready_at" timestamp with time zone,
    "ready_notified_at" timestamp with time zone,
    "disconnected_at" timestamp with time zone,
    "synced_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "stripe_connect_account_fee_range" CHECK ((("application_fee_bps" >= 0) AND ("application_fee_bps" <= 2000) AND (("application_fee_cents" >= 0) AND ("application_fee_cents" <= 10000)))),
    CONSTRAINT "stripe_connect_account_id_shape" CHECK (("stripe_account_id" ~ '^acct_[A-Za-z0-9]{6,64}$'::"text")),
    CONSTRAINT "stripe_connect_account_linked_via_check" CHECK (("linked_via" = ANY (ARRAY['created'::"text", 'oauth'::"text"]))),
    CONSTRAINT "stripe_connect_account_status_check" CHECK (("status" = ANY (ARRAY['onboarding'::"text", 'ready'::"text", 'restricted'::"text", 'disconnected'::"text"])))
);


ALTER TABLE "public"."stripe_connect_account" OWNER TO "postgres";


COMMENT ON TABLE "public"."stripe_connect_account" IS 'The workspace''s connected Stripe account (459): customers pay into it by direct charges. Service role writes only.';


COMMENT ON COLUMN "public"."stripe_connect_account"."linked_via" IS 'created: Dial8 made it (Accounts v2, full Dashboard) and the owner onboarded on Stripe. oauth: an existing Stripe account the owner linked.';


COMMENT ON COLUMN "public"."stripe_connect_account"."status" IS 'onboarding (Stripe still needs details), ready (can take card payments), restricted (Stripe paused charges), disconnected (the owner removed Dial8).';


COMMENT ON COLUMN "public"."stripe_connect_account"."application_fee_bps" IS 'Dial8''s optional platform fee in basis points of each payment (459). Default 0: pricing isn''t decided. Set by Dial8 staff only.';


COMMENT ON COLUMN "public"."stripe_connect_account"."application_fee_cents" IS 'Dial8''s optional fixed platform fee per payment, in the payment''s currency minor unit (459). Default 0.';


COMMENT ON COLUMN "public"."stripe_connect_account"."ready_notified_at" IS 'When the owner was texted that payments are on: set once, so the confirmation goes out once.';


