CREATE TABLE IF NOT EXISTS "public"."tracked_job" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "member_id" "uuid",
    "kind" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "progress" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "result_summary" "text",
    "source" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "current_step" "text",
    "deliverables" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "needs" "jsonb",
    "error_message" "text",
    "skip_reason" "text",
    "actor" "text" DEFAULT 'system'::"text" NOT NULL,
    "run_key" "text",
    "agent_run_id" "uuid",
    "flow_run_id" "uuid",
    "reviewed_at" timestamp with time zone,
    "last_beat_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deadline_at" timestamp with time zone,
    "ai_team_member_id" "uuid",
    "origin" "text" DEFAULT 'user'::"text" NOT NULL,
    "parent_id" "uuid",
    "root_id" "uuid",
    "depth" integer DEFAULT 0 NOT NULL,
    "opened_at" timestamp with time zone,
    "area" "text",
    "plan" "jsonb",
    CONSTRAINT "tracked_job_actor_check" CHECK (("actor" = ANY (ARRAY['loop'::"text", 'agent'::"text", 'user'::"text", 'system'::"text"]))),
    CONSTRAINT "tracked_job_area_check" CHECK ((("area" IS NULL) OR ("area" = ANY (ARRAY['calendar'::"text", 'actions'::"text", 'captures'::"text", 'documents'::"text", 'knowledge'::"text", 'initiatives'::"text", 'projects'::"text", 'flows'::"text", 'mail'::"text", 'crm'::"text", 'prospecting'::"text", 'sequences'::"text", 'campaigns'::"text", 'evals'::"text", 'browser'::"text", 'library'::"text", 'content'::"text", 'marketing'::"text"])))),
    CONSTRAINT "tracked_job_deliverables_is_array" CHECK (("jsonb_typeof"("deliverables") = 'array'::"text")),
    CONSTRAINT "tracked_job_depth_check" CHECK (("depth" >= 0)),
    CONSTRAINT "tracked_job_has_owner" CHECK ((("member_id" IS NOT NULL) OR ("ai_team_member_id" IS NOT NULL))),
    CONSTRAINT "tracked_job_needs_is_object" CHECK ((("needs" IS NULL) OR ("jsonb_typeof"("needs") = 'object'::"text"))),
    CONSTRAINT "tracked_job_origin_check" CHECK (("origin" = ANY (ARRAY['user'::"text", 'loop'::"text", 'attempt'::"text", 'delegation'::"text", 'chat'::"text"]))),
    CONSTRAINT "tracked_job_plan_object_check" CHECK ((("plan" IS NULL) OR ("jsonb_typeof"("plan") = 'object'::"text"))),
    CONSTRAINT "tracked_job_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'needs_input'::"text", 'needs_review'::"text", 'waiting_on_child'::"text", 'done'::"text", 'failed'::"text", 'skipped'::"text", 'canceled'::"text"])))
);

ALTER TABLE ONLY "public"."tracked_job" REPLICA IDENTITY FULL;


ALTER TABLE "public"."tracked_job" OWNER TO "postgres";


COMMENT ON COLUMN "public"."tracked_job"."current_step" IS 'Live one-line status while running ("Drafting a reply to Dana"). Null once settled.';


COMMENT ON COLUMN "public"."tracked_job"."deliverables" IS 'Array of { type, id, label, workspace_id?, count?, entity_type? } the UI routes to the entity''s own surface.';


COMMENT ON COLUMN "public"."tracked_job"."needs" IS '{ kind: input, questions } while parked on a question; { kind: review, verb } while a deliverable waits on the user; null otherwise.';


COMMENT ON COLUMN "public"."tracked_job"."run_key" IS 'Idempotency key (an Inngest event id, an agent_run id): a retry continues the same row instead of inserting a second one.';


COMMENT ON COLUMN "public"."tracked_job"."deadline_at" IS 'When the reaper may fail a queued/running row that stopped reporting. Null while parked or settled.';


COMMENT ON COLUMN "public"."tracked_job"."ai_team_member_id" IS 'The teammate that did (or is doing) the work — the "which agent" every ledger row needs. NULL until the writers stamp it (steps 4 and 8).';


COMMENT ON COLUMN "public"."tracked_job"."origin" IS 'Same vocabulary as agent_run.origin; every existing row is user.';


COMMENT ON COLUMN "public"."tracked_job"."parent_id" IS 'The delegating work item, for a delegated child (nesting on the surface).';


COMMENT ON COLUMN "public"."tracked_job"."root_id" IS 'The top of the delegation chain.';


COMMENT ON COLUMN "public"."tracked_job"."depth" IS 'Chain depth, 0 for a root.';


COMMENT ON COLUMN "public"."tracked_job"."opened_at" IS 'When the row''s owner opened the item''s detail panel since it last started waiting on them; NULL = not opened since (it may make its teammate''s bot call for you). Stamped only when empty; cleared on every move into needs_input or needs_review.';


COMMENT ON COLUMN "public"."tracked_job"."area" IS 'The area of Dial8 this work belongs to (one of the 16 area keys; NULL: none). The face it shows with is picked from it (one-agent plan, decision 9).';


COMMENT ON COLUMN "public"."tracked_job"."plan" IS 'The agent''s plan for this job: { steps: [{ text, status }], updated_at }. Written only by src/lib/work/plan.ts setWorkPlan, never part of progress.';


