    CONSTRAINT "user_phone_consent_version_length" CHECK ((("char_length"("consent_version") >= 1) AND ("char_length"("consent_version") <= 40))),
    CONSTRAINT "user_phone_e164_format" CHECK (("phone_e164" ~ '^[+][1-9][0-9]{6,14}$'::"text")),
    CONSTRAINT "user_phone_line_check" CHECK (("line" = ANY (ARRAY['dial8'::"text", 'business'::"text"])))
);


ALTER TABLE "public"."user_phone" OWNER TO "postgres";


COMMENT ON TABLE "public"."user_phone" IS 'A person''s linked phone for texting the agent (411). One per person. A verified number has one Dial8-line holder and any number of business lines (464). The person reads and deletes their own row; only the service role writes.';


COMMENT ON COLUMN "public"."user_phone"."workspace_id" IS 'The workspace this number''s texts go to (the person''s home thread there).';


COMMENT ON COLUMN "public"."user_phone"."opted_out_at" IS 'Set when the number texted STOP (cleared by START or a new verification). Nothing is texted to it while set.';


COMMENT ON COLUMN "public"."user_phone"."consent_version" IS 'Which SMS consent words the person agreed to in Settings (src/lib/sms/consent.ts SMS_CONSENT_VERSION), at consented_at.';


COMMENT ON COLUMN "public"."user_phone"."alerts_consented_at" IS 'Set when the person turned on texts from the agent when it needs them (426). Unset: Dial8 texts only replies to their own texts.';


COMMENT ON COLUMN "public"."user_phone"."alerts_consent_version" IS 'Which alert consent words they agreed to (src/lib/sms/consent.ts SMS_ALERTS_CONSENT_VERSION).';


COMMENT ON COLUMN "public"."user_phone"."line" IS 'Which number reaches this person (464): dial8 = the Dial8 number (one holder per phone), business = only the business numbers of the workspaces they belong to (any number of accounts per phone).';


CREATE TABLE IF NOT EXISTS "public"."user_presence" (
    "user_id" "uuid" NOT NULL,
    "client_id" "text" NOT NULL,
    "surface" "text" NOT NULL,
    "state" "text" NOT NULL,
    "active_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_presence_client_id_shape" CHECK (("client_id" ~ '^[A-Za-z0-9_-]{8,64}$'::"text")),
    CONSTRAINT "user_presence_state_check" CHECK (("state" = ANY (ARRAY['active'::"text", 'idle'::"text", 'locked'::"text", 'hidden'::"text"]))),
    CONSTRAINT "user_presence_surface_check" CHECK (("surface" = ANY (ARRAY['web'::"text", 'desktop'::"text", 'ios'::"text"])))
);


ALTER TABLE "public"."user_presence" OWNER TO "postgres";


COMMENT ON TABLE "public"."user_presence" IS 'Whether a person is at a Dial8 app right now (454, docs/plans/reach-follows-you.md): one row per person and browser or app install, pinged by POST /api/presence. Present = a row in state active whose active_at is under 5 minutes old. Service role only; rows untouched for 30 days are pruned by the notification-purge cron.';


COMMENT ON COLUMN "public"."user_presence"."client_id" IS 'A random id the client keeps in localStorage: one per browser or app install (8 to 64 letters, digits, dashes or underscores).';


COMMENT ON COLUMN "public"."user_presence"."surface" IS 'Which app pinged: web, desktop or ios.';


COMMENT ON COLUMN "public"."user_presence"."state" IS 'What the last ping said. The web writes only active (a stale row is its absence); the desktop main window writes active, idle or locked; iOS will write active or hidden.';


COMMENT ON COLUMN "public"."user_presence"."active_at" IS 'When a ping last said active. Not touched by any other state, so it also says when the person was last active on this client. NULL before the first.';


COMMENT ON COLUMN "public"."user_presence"."updated_at" IS 'When the last ping of any state landed. The notification-purge cron deletes rows older than 30 days.';


