CREATE OR REPLACE VIEW "public"."users_with_multiple_devices" AS
 SELECT "user_id",
    "count"(DISTINCT "device_id") AS "device_count",
    "array_agg"(DISTINCT "device_id") AS "device_ids"
   FROM "public"."user_devices"
  GROUP BY "user_id"
 HAVING ("count"(DISTINCT "device_id") > 1);


ALTER VIEW "public"."users_with_multiple_devices" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."view" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
