    "slug" "text",
    "entity_type" "public"."view_entity_type" NOT NULL,
    "visibility" "public"."view_visibility" DEFAULT 'personal'::"public"."view_visibility" NOT NULL,
    "layout" "public"."view_layout" DEFAULT 'list'::"public"."view_layout" NOT NULL,
    "filters" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "grouping" "jsonb",
    "sub_grouping" "jsonb",
    "ordering" "jsonb" DEFAULT '[{"field": "created_at", "direction": "desc"}]'::"jsonb" NOT NULL,
    "display_properties" "text"[] DEFAULT '{}'::"text"[],
    "board_group_by" "text",
    "show_completed" boolean DEFAULT true,
