    CONSTRAINT "view_scope_type_check" CHECK ((("scope_type" IS NULL) OR ("scope_type" = ANY (ARRAY['project'::"text", 'initiative'::"text", 'contact'::"text", 'company'::"text", 'prospect_list'::"text", 'eval_suite'::"text"]))))
