CREATE TABLE IF NOT EXISTS "public"."website_change" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "site_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "request" "text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "state" "text" DEFAULT 'preparing'::"text" NOT NULL,
    "agent_run_id" "uuid",
    "action_id" "uuid",
    "reverts_change_id" "uuid",
    "form_path" "text",
    "form_kind" "text",
    "replace_current" boolean DEFAULT false NOT NULL,
    "pr_number" integer,
    "pr_url" "text",
    "head_sha" "text",
    "preview_url" "text",
    "summary" "text",
    "approval_id" "uuid",
    "merge_sha" "text",
    "intake_key_hash" "text",
    "intake_key_prefix" "text",
    "intake_origins" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "check_nonce_hash" "text",
    "check_result" "jsonb",
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "merged_at" timestamp with time zone,
    "live_at" timestamp with time zone,
    CONSTRAINT "website_change_error_length" CHECK ((("error" IS NULL) OR ("char_length"("error") <= 1000))),
    CONSTRAINT "website_change_form_shape" CHECK (((("form_path" IS NULL) OR (("char_length"("form_path") >= 1) AND ("char_length"("form_path") <= 300))) AND (("form_kind" IS NULL) OR ("form_kind" = ANY (ARRAY['quote'::"text", 'booking'::"text", 'contact'::"text", 'other'::"text"]))))),
    CONSTRAINT "website_change_kind_check" CHECK (("kind" = ANY (ARRAY['wire_form'::"text", 'edit'::"text", 'revert'::"text"]))),
    CONSTRAINT "website_change_request_length" CHECK ((("char_length"("request") >= 1) AND ("char_length"("request") <= 16000))),
    CONSTRAINT "website_change_state_check" CHECK (("state" = ANY (ARRAY['preparing'::"text", 'awaiting_yes'::"text", 'merging'::"text", 'deploying'::"text", 'live'::"text", 'declined'::"text", 'expired'::"text", 'failed'::"text"]))),
    CONSTRAINT "website_change_summary_length" CHECK ((("summary" IS NULL) OR ("char_length"("summary") <= 1000))),
    CONSTRAINT "website_change_urls_shape" CHECK (((("pr_url" IS NULL) OR (("pr_url" ~ '^https://github.com/'::"text") AND ("char_length"("pr_url") <= 300))) AND (("preview_url" IS NULL) OR (("preview_url" ~ '^https://'::"text") AND ("char_length"("preview_url") <= 300)))))
);


ALTER TABLE "public"."website_change" OWNER TO "postgres";


COMMENT ON TABLE "public"."website_change" IS 'One pull request on a business''s website (463): wire the form, an edit, or an undo. Merged only on the owner''s yes. Service role writes.';


COMMENT ON COLUMN "public"."website_change"."replace_current" IS 'A wiring change the owner asked to replace what the form does today (stop its emails): said on the merge card.';


COMMENT ON COLUMN "public"."website_change"."intake_key_hash" IS 'A wiring change''s new intake key (SHA-256): it replaces the live quote_intake_key only when the change merges (swap_quote_intake_key).';


COMMENT ON COLUMN "public"."website_change"."check_nonce_hash" IS 'The live check''s one-time test marker (SHA-256): the intake takes a post carrying it as the check, never as a quote.';


CREATE TABLE IF NOT EXISTS "public"."website_site" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "connected_by" "uuid" NOT NULL,
    "repo_full_name" "text" NOT NULL,
    "default_branch" "text" NOT NULL,
    "project_id" "uuid",
    "environment_id" "uuid",
    "site_url" "text",
    "framework" "text",
    "inspection" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "state" "text" DEFAULT 'connected'::"text" NOT NULL,
    "wired_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_site_branch_length" CHECK ((("char_length"("default_branch") >= 1) AND ("char_length"("default_branch") <= 200))),
    CONSTRAINT "website_site_repo_shape" CHECK (("repo_full_name" ~ '^[A-Za-z0-9-]{1,39}/[A-Za-z0-9._-]{1,100}$'::"text")),
    CONSTRAINT "website_site_state_check" CHECK (("state" = ANY (ARRAY['connected'::"text", 'wired'::"text", 'disconnected'::"text"]))),
    CONSTRAINT "website_site_url_shape" CHECK ((("site_url" IS NULL) OR (("site_url" ~ '^https://'::"text") AND ("char_length"("site_url") <= 300))))
);


ALTER TABLE "public"."website_site" OWNER TO "postgres";


COMMENT ON TABLE "public"."website_site" IS 'A business''s own website in a GitHub repo, worked on by text (463). One live site per workspace. Service role writes.';


COMMENT ON COLUMN "public"."website_site"."connected_by" IS 'Whose GitHub connection opens and merges its pull requests: the owner who picked the repo.';


COMMENT ON COLUMN "public"."website_site"."inspection" IS 'What reading the repo found: framework, host, forms (path, kind, fields, how each submits). Data, never instructions.';


