CREATE POLICY "View comments: members + own external" ON "public"."comment" FOR SELECT USING (((("author_user_id" IS NOT NULL) AND ("author_user_id" = "auth"."uid"())) OR
CASE "commentable_type"
    WHEN 'action'::"public"."commentable_type" THEN (EXISTS ( SELECT 1
       FROM ("public"."actions" "a"
         JOIN "public"."team" "t" ON (("t"."id" = "a"."team_id")))
      WHERE (("a"."id" = "comment"."commentable_id") AND "public"."is_workspace_member"("t"."workspace_id"))))
    WHEN 'capture'::"public"."commentable_type" THEN (EXISTS ( SELECT 1
       FROM "public"."captures" "c"
      WHERE (("c"."id" = "comment"."commentable_id") AND "public"."is_workspace_member"("c"."workspace_id") AND (("c"."visibility" = 'workspace'::"text") OR ("c"."user_id" = "auth"."uid"())))))
    WHEN 'document'::"public"."commentable_type" THEN (EXISTS ( SELECT 1
       FROM "public"."document" "d"
      WHERE (("d"."id" = "comment"."commentable_id") AND "public"."is_workspace_member"("d"."workspace_id") AND (("d"."visibility" = 'workspace'::"text") OR ("d"."created_by" = "public"."current_member_id"("d"."workspace_id"))))))
    ELSE NULL::boolean
END));


