-- auth.users triggers that call the app's functions (new user setup).
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TRIGGER on_auth_user_created_mark_signup_invite AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.mark_signup_invite_used();

-- Storage buckets.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('attachments', 'attachments', 'f', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('workspace-merges', 'workspace-merges', 'f', '52428800', '{application/json}') ON CONFLICT (id) DO NOTHING;

-- storage.objects and realtime.messages (private channel) policies.
CREATE POLICY agent_nudge_workspace_members_can_subscribe ON realtime.messages AS PERMISSIVE FOR SELECT TO authenticated
  USING (((realtime.topic() ~~ 'agent-nudge:%'::text) AND (EXISTS ( SELECT 1
   FROM (public.captures c
     JOIN public.member m ON (((m.workspace_id = c.workspace_id) AND (m.user_id = auth.uid()))))
  WHERE (c.id = (NULLIF(split_part(realtime.topic(), ':'::text, 2), ''::text))::uuid)))));

CREATE POLICY browser_cmd_owner_can_subscribe ON realtime.messages AS PERMISSIVE FOR SELECT TO authenticated
  USING (((realtime.topic() ~~ 'browser-cmd:%'::text) AND ((NULLIF(split_part(realtime.topic(), ':'::text, 2), ''::text))::uuid = auth.uid())));

CREATE POLICY local_agent_device_owner_can_subscribe ON realtime.messages AS PERMISSIVE FOR SELECT TO authenticated
  USING (((realtime.topic() ~~ 'device:%'::text) AND (split_part(realtime.topic(), ':'::text, 2) = (( SELECT auth.uid() AS uid))::text)));

CREATE POLICY "Users can delete their own files" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'attachments'::text) AND (lower((auth.uid())::text) = lower((storage.foldername(name))[1]))));

CREATE POLICY "Users can update their own files" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'attachments'::text) AND (lower((auth.uid())::text) = lower((storage.foldername(name))[1]))));

CREATE POLICY "Users can upload their own files" ON storage.objects AS PERMISSIVE FOR INSERT TO public
  WITH CHECK (((bucket_id = 'attachments'::text) AND (lower((auth.uid())::text) = lower((storage.foldername(name))[1]))));

CREATE POLICY "Users can view their own files" ON storage.objects AS PERMISSIVE FOR SELECT TO public
  USING (((bucket_id = 'attachments'::text) AND (lower((auth.uid())::text) = lower((storage.foldername(name))[1]))));

CREATE POLICY "attachments workspace delete" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'attachments'::text) AND (EXISTS ( SELECT 1
   FROM public.attachments a
  WHERE (((a.storage_path = objects.name) OR (a.thumbnail_path = objects.name)) AND public.is_workspace_member(a.workspace_id))))));

CREATE POLICY "attachments workspace read" ON storage.objects AS PERMISSIVE FOR SELECT TO public
  USING (((bucket_id = 'attachments'::text) AND (EXISTS ( SELECT 1
   FROM public.attachments a
  WHERE (((a.storage_path = objects.name) OR (a.thumbnail_path = objects.name)) AND public.is_workspace_member(a.workspace_id) AND ((a.note_id IS NULL) OR (EXISTS ( SELECT 1
           FROM public.captures c
          WHERE ((c.id = a.note_id) AND ((c.visibility = 'workspace'::text) OR (c.user_id = auth.uid())))))))))));
